import * as _ from "lodash";
import { Device, Resource, Pin, Peripheral } from "./requirements";

// Class to track which pins are marked as allowing conflicts.  It indicates that it's allowed only
// if marked, and if something else would conflict with it.

class ConflictTracker<T extends Resource> {

	constructor(private readonly conflicts: { [assignment: string]: T[] }) { }

	public areConflictsAllowed(req: T) {

		// If it's not actually conflicting with anything, indicate false.  This way, we can allow
		// such marked pins to be shared as normal

		return req.areConflictsAllowed() && 1 < _.size(this.conflicts[req.userOverride]);
	}
}

export class PinConflictTracker extends ConflictTracker<Pin> {
	constructor(deviceRequirements: Device) {

		// Find all pin reqs that can conflict with another pin req

		super(
			_.chain(_.values(deviceRequirements.interfaceRequirementsMap))
				.flatMap((group) => group.requirements)
				.flatMap((req) => req.pinRequirements)
				.filter((pinReq) => pinReq.used && pinReq.areConflictsAllowed())
				.groupBy((pinReq) => pinReq.userOverride)
				.value());
	}
}

export class PeripheralConflictTracker extends ConflictTracker<Peripheral> {
	constructor(deviceRequirements: Device) {

		// Find all perf reqs that can conflict with another perf req

		super(
			_.chain(_.values(deviceRequirements.interfaceRequirementsMap))
				.flatMap((group) => group.requirements)
				.map((req) => req instanceof Peripheral ? req : null) // needed to force type of array entries
				.filter((req) => req && req.areConflictsAllowed())
				.groupBy((req) => req.userOverride)
				.value());
	}
}
