import { ButtonClickResult } from "public/defs";
import { storage } from "../../storage";
import { ButtonConfigurableMgr } from "./buttonConfigurableMgr";

export class StandardButtonConfigurableMgr extends ButtonConfigurableMgr<ButtonClickResult> {
	public async getClickResult(_productPath: string, fileOrFolder?: string) {
		if (fileOrFolder && !this.def.pickDirectory) {
			const { data } = await storage.openFile(fileOrFolder);
			return { fileOrFolder, fileContents: data };
		}
		return { fileOrFolder };
	}

	public override getDelayReason() {
		return "Loading file...";
	}
}
