import * as _ from "lodash";
// Contains class and related facilities for managing gpio interface instance in core pinmux.

import { EnumerationConfigurableMgr } from "./configurables/enumerationConfigurableMgr";
import { Interface } from "dataInterfaces";
import { AMemberMgr, SetSource } from "./member";
import { MultiPinMgr } from "./multiPin";
import { NameMemberMgr } from "./name";
import { AObjectMgr } from "./object";
import { PinMgr } from "./pin";
import { PinMemberMgr } from "./pinObjectMembers";
import { IPinsViewProvider } from "./pins";
import {
	EnumerationOption,
} from "public/defs";
import { GPIOInterfaceInstance } from "public/runtime";
import { Runtime } from "../resources/runtime";
import { createAddInterfaceInstanceStatement } from "../scripting/serialize";
import { SelectionFilterGroup } from "./selectionFilterGroup";
import { GPIO } from "../solver/requirements";
import { createHeader, NameToConfigurableHeader } from "./ui/header";
import { filterHiddenPinMembers, getAssignedPins } from "./funcs";
import { format } from "../formatting/gpioInterfaceFormatter";
import { setAssignedValue } from "./interfaceInstance";
import { SerializationOptions } from "../scripting/toScript";
import { IMyListItem } from "../IMyListItem";
import { InternalValidationLogger } from "./validations";

const numPinsConfigurableName: keyof GPIOInterfaceInstance = "$numPins";

/**
 * Only used in core pinmux to manage gpio pin configuration. Mainly, supports
 * group GPIO pins which is not needed in sys config.
 */
export class GPIOInterfaceInstanceMgr
	extends AObjectMgr<GPIOInterfaceInstance> implements IMyListItem, IPinsViewProvider {

	private readonly nameMember: NameMemberMgr;
	private readonly solverReq: GPIO;

	// Pins are exposed as members of an interface instance
	// This tracks member managers for those pins
	private readonly pins: PinMemberMgr[] = [];
	// select all pins flag, not a member cause it does not need to be serialized.
	private selectAll: boolean = true;
	// Track objects that support setting configurable values as a group
	private pinConfigurableHeaders: NameToConfigurableHeader;
	private readonly numPins: EnumerationConfigurableMgr<GPIOInterfaceInstance, number>;
	private readonly id: string;
	private readonly maxAllowed: number;

	constructor(
		runtime: Runtime,
		private readonly iface: Interface,
	) {

		super(runtime, (options, member) => format(this, options, member));

		const { id, name } = this.runtime.getInterfaceInstanceNextNameAndId(this.iface.name);
		this.id = id;

		this.addFixedMember(runtime.getFormattersMap(), "$interface", this.iface);

		this.solverReq
			= new GPIO(
				this.id,
				this.iface.name,
			);

		this.maxAllowed = _.size(this.runtime.getDeviceData().gpio.pinInfo);

		// create built-in num pins configurable

		const options: EnumerationOption<number>[] = _.map(_.range(1, this.maxAllowed + 1), (num) => {
			return {
				name: num,
			};
		});

		this.numPins = new EnumerationConfigurableMgr<GPIOInterfaceInstance, number>(
			this,
			runtime.getFormattersMap(),
			{
				name: numPinsConfigurableName,
				displayName: "Number of GPIO pins",
				options,
				default: options[0].name,
				getDisabledOptions: () => {
					const numUsedByOthers = this.getNumTotalGPIOUsed() - this.getNumOfGPIOPinsUsed();
					// limit options dynamically to what is actually possible
					// num available = max available - (num used by all - num currently used by us)
					const numAvailableToThisReq = this.maxAllowed - numUsedByOthers;
					const disabledOptions = _.map(
						_.filter(this.numPins.def.options, (o) => o.name > numAvailableToThisReq),
						(o) => ({
							name: o.name,
							reason: `${numUsedByOthers} GPIO pins have already been used`,
						}),
					);
					return disabledOptions;
				},
			},
		);

		this.nameMember = new NameMemberMgr(this, runtime.getFormattersMap(), { default: name },
			{ isReadOnly: false, isHidden: false });

		this.setNumOfGPIOPins(this.numPins.getValue());

	}

	public override getContainingInstanceMgrs() {
		return [this];
	}

	public override getContainingTreeNodes() {
		return [this.runtime.getInterfaceMgr(this.iface.name)];
	}

	public applyUIDefaults() {
		// nothing to do
	}

	public modifiedInUI() {
		// Intentionally blank - core pinmux components are ALWAYS user created
	}

	public getID() {
		return this.id;
	}

	public getName() {
		return this.getNameMgr().getValue();
	}

	public setSelectAll(value: boolean): void {
		this.selectAll = value;
		_.each(this.pins, (pinInstance) => {
			pinInstance.valueObjectMgr.setUsed(value, SetSource.USER_ASSIGN);
		});
	}

	public getNameMgr() {
		return this.nameMember;
	}

	public getNumPinsMgr() {
		return this.numPins;
	}

	public isSelectAllEnabled() {
		return this.selectAll;
	}

	public setUseCase(_useCaseName: string) {
		// is meaningless at this point, there should only be 1 use case
		return;
	}

	public getSolverRequirements() {
		this.solverReq.pinRequirements = _.map(this.pins, (p) => p.valueObjectMgr.getSolverRequirement());
		return [this.solverReq];
	}

	public solveComplete() {
		_.each(this.pins, (p) => p.valueObjectMgr.solveComplete());
	}

	public applySolverValidation() {
		_.each(this.pins, (p) => p.valueObjectMgr.applySolverValidation(p));
	}

	public override preRemove(): void {
		this.runtime.removeInterfaceInstance(this);
	}

	public getNumOfGPIOPinsUsed() {
		return this.pins.length;
	}

	public revealMember(_focusedListItemPath: string[]) {
	}

	public getPinMemberMgrs() {
		return _.filter(this.pins, (pin) => pin.def.name in this.memberMgrs);
	}

	public getVisiblePinMgrs() {
		return filterHiddenPinMembers(this.pins);
	}

	public getMultiPinMgr(): MultiPinMgr {
		return null;
	}

	public getPinConfigurablesHeaders(): NameToConfigurableHeader {
		return this.pinConfigurableHeaders;
	}

	public isReservation() {
		return !this.runtime.isCorePinmux();
	}

	public override validate(validationLogger: InternalValidationLogger): void {
		super.validate(validationLogger);
		_.each(this.pins, (p) => p.valueObjectMgr.validate(validationLogger));
	}

	public getAddInstanceStatement(instIdentifier: string) {
		return createAddInterfaceInstanceStatement(this, instIdentifier);
	}

	public isRemovable(): boolean {
		return true;
	}

	public override onMemberChanged(mem: AMemberMgr<any>) {
		if (mem === this.numPins) {
			this.setNumOfGPIOPins(mem.getValue());
		}
	}

	public getNumTotalGPIOUsed() {
		const container = this.runtime.getInterfaceMgr(this.iface.name);
		return _.sum(_.map(container.instances, (i: GPIOInterfaceInstanceMgr) => i.getNumOfGPIOPinsUsed()));
	}

	public setLockStatus(status: boolean) {
		_.each(this.getVisiblePinMgrs(), (pin) => {
			setAssignedValue(status, pin);
		});
	}

	public getUsedPins() {
		const reqs = this.getSolverRequirements();
		return getAssignedPins(reqs);
	}

	protected override getMembersInScriptOrder(_options: SerializationOptions): AMemberMgr<any>[] {

		// num pins can alter how many, so it must be set first

		return [
			this.numPins,
			..._.filter(this.memberMgrs, (mem) => mem !== this.numPins),
		];
	}

	private addGPIOPins(numOfGPIOPinsToAdd: number) {

		_.times(numOfGPIOPinsToAdd, () => {

			// Assumption : only 1 interface pin, only 1 use case pin
			// The use case pin is only needed for core pinmux

			const useCasePin = _.values(_.values(this.iface.useCases)[0].useCasePins)[0];
			const pinName = this.pins.length.toString();

			const newPin = new PinMgr(
				this.runtime,
				(options) => format(this, options, pinName),
				pinName,
				new SelectionFilterGroup(),
				useCasePin,
				null,
				{},
				this,
				undefined,
				this.isReservation(),
			);

			// create a member based on the pin

			const pinMember = new PinMemberMgr(
				newPin,
				this.runtime.getFormattersMap(),
				{
					name: pinName,
				},
				this,
			);

			// also track pins separately for pin related operations

			this.pins.push(pinMember);
		});

	}

	private removeGPIOPins(numOfGPIOPinsToRemove: number) {

		const removeIndex = (-numOfGPIOPinsToRemove);

		// remove from our tracking

		const removed = this.pins.splice(removeIndex, numOfGPIOPinsToRemove);

		// call remove to clean up base class and managed object

		_.each(removed, (m) => {
			this.removeMember(m);
		});
	}

	private setNumOfGPIOPins(numOfGPIOPins: number) {

		if (numOfGPIOPins === this.getNumOfGPIOPinsUsed()) {
			throw new Error("No change in the number of GPIO pins requested");
		}

		if (numOfGPIOPins > this.getNumOfGPIOPinsUsed()) {
			this.addGPIOPins(numOfGPIOPins - this.getNumOfGPIOPinsUsed());
		} else {
			this.removeGPIOPins(this.getNumOfGPIOPinsUsed() - numOfGPIOPins);
		}

		// re-create headers
		this.pinConfigurableHeaders = createHeader(
			_.flatMap(this.pins, (p) => p.valueObjectMgr.getNonBuiltInConfigurables()),
		);
	}
}
