import * as _ from "lodash";
import { AMemberMgr } from "./member";
import { RuntimeObject, ModuleInstance } from "public/runtime";
import { AObjectMgr } from "./object";
import { Statement } from "../scripting/serialize";
import { FormattersMap } from "../formatting/formattersMap";

export class FixedDataMember<ValueType, RuntimeObjectType extends RuntimeObject = RuntimeObject>
	extends
	AMemberMgr<ValueType, RuntimeObjectType> {

	constructor(
		parentObjectMgr: AObjectMgr<RuntimeObjectType>,
		formattersMap: FormattersMap,
		name: keyof RuntimeObjectType | "addInstance",
		value: ValueType,
	) {
		super(
			parentObjectMgr,
			formattersMap,
			{
				name: name as string,
				hidden: true,
			},
			value,
		);
	}

	public changeData(value: ValueType) {
		this.value = value;
	}

	public setValueFromRequiredArgs() {
		this.set();
	}

	public setValueFromArgs() {
		this.set();
	}

	public removeArgs() {
		throw new Error("Configurable contains fixed data and should not have args to be removed");
	}

	public removeReqArgs() {
		this.removeArgs();
	}

	public override set() {
		throw new Error("Configurable contains fixed data and cannot be modified");
	}

	public generateScriptStatements(): Statement[] {
		return [];
	}

	public override shouldSerialize() {
		return false;
	}

	// uiState/validation is frozen, so these functions do nothing

	public override resetDefaultUIState() {
	}

	public override excludeFromInternalMaps() {
		return true;
	}
}

export class SharedByFixedDataMember extends FixedDataMember<ModuleInstance[], ModuleInstance> {
	public override get() {
		// always return in a well-defined order
		return _.sortBy(this.value, (i) => i.$name);
	}
}
