import * as _ from "lodash";
import { http } from "../../http";
import { MetaContentLocation } from "./resourceLoader";
import { isNode, isCloud } from "../../platform";
import { deviceDataDir } from "../../paths";

// This function loads all metadata associated with the SOC device data.  It first 
// looks for a bundle specific to that device id, but if not found, will use 
// the raw path to load resources (assuming non-cloud of course)
export function loadSocMetadata(deviceId: string) {

	const filePath = isNode() ? deviceDataDir() : undefined;

	return fetchBundle("deviceData/" + deviceId + "/metadata.bundle", filePath)
		.then((mainBundle) => {
			return fetchBundle("deviceData/legacy/metadata.bundle", filePath)
				.then((legacyAdaptionBundle) => [mainBundle, legacyAdaptionBundle]);
		});
}

// Load Product metadata content
export function loadProductMetaData(
	productFilePath: string, includePaths: string[]): Promise<MetaContentLocation[]> {

	if (isCloud() && _.endsWith(productFilePath, ".syscfg")) {
		// ignore the script directory in the cloud for the time being 
		// PMUX-1005
		return Promise.resolve([]);
	}

	return fetchBundle(productFilePath + ".bundle")
		.then((result) => [result])
		.catch(() => {
			const path = require("path");
			return _.map(includePaths, (includePath) => {
				const productFileDirPath = path.dirname(productFilePath);
				const filePath = path.resolve(productFileDirPath, includePath);
				return { filePath };
			});
		});
}

// try to fetch .bundle file, optionally fall back to file system loader
function fetchBundle(bundle: string, filePath?: string): Promise<MetaContentLocation> {
	bundle = _.trimStart(bundle, "/");
	const promise = http.get(bundle)
		.then((response) => {
			return { bundle: response };
		});

	if (filePath) {
		return promise.catch(() => {
			return { filePath };
		});
	}
	return promise;
}
