import * as _ from "lodash";
import { DevicePin, NameToDevicePinMap } from "dataInterfaces";
import { FormattersMap } from "./formattersMap";
import { UserPreference, PinDisplayType } from "../userPreferences";
import { assertUnreachable } from "../utils";
import { PinMap } from "../pinMap";

class DevicePinFormatter {

	constructor(private readonly pinMap: PinMap, private readonly userPref: UserPreference) { }

	public toString(devicePin: DevicePin) {
		// Virtual Pin
		if (devicePin.devicePinType === "Virtual") {
			return devicePin.name;
		}

		// Determine which preference to look at
		const pinInfo = this.pinMap.get(devicePin);
		const displayOptions = _.isEmpty(pinInfo.headerInfo) ?
			this.userPref.getPreferences().devicePinDisplayType.getSelectedEnums() :
			this.userPref.getPreferences().headerPinDisplayType.getSelectedEnums();

		// Device/Internal Pin
		return _.map(displayOptions, (opt) => {
			switch (opt) {
				case PinDisplayType.DEVICENAME: {
					return devicePin.designSignalName;
				}
				case PinDisplayType.DEVICENUM: {
					return devicePin.name;
				}
				case PinDisplayType.HEADERNAME: {
					return _.first(pinInfo.headerInfo).headerPin.name || "";
				}
				case PinDisplayType.HEADERNUM: {
					const headerInfo = _.first(pinInfo.headerInfo);
					return headerInfo.headerPin.number + (headerInfo.header.boardNumberOffset || 0);
				}
				default: {
					assertUnreachable(opt);
					return null;
				}
			}
		}).join("/");
	}
}

export function registerDevicePins(
	devicePins: NameToDevicePinMap,
	pinMap: PinMap,
	objectIdentifiers: FormattersMap,
	userPreference: UserPreference) {
	const formatter = new DevicePinFormatter(pinMap, userPreference);
	_.each(devicePins, (pin) => objectIdentifiers.set(pin, () => formatter.toString(pin)));
}
