import * as _ from "lodash";
import { getDeviceDescriptions, getRenamedDeviceId } from "../data";
import { productInRange, isTIProductVersion, tiVersionToSemver } from "../utils";
import { ScriptAndProductLoader } from "../resources/otherLoaders/scriptAndProductLoader";
import { IAvailableProducts } from "../product/available";
import { loadProducts, loadScriptDirProductPathProduct } from "../product/loadResources";
import { Product, MinProductFile, AvailableProductInfo } from "../product/types";
import { loadMinProductFile } from "../product/parseProductFile";
import * as semver from "semver";
import {
	ParsedArgs,
	ArgsError,
	InvalidArgError,
	ParsedArg,
	Script,
	SetupError,
} from "./argTypes";
import { isCloud } from "../platform";

export async function resolveProducts(parsedArgs: ParsedArgs<Script>, loader: ScriptAndProductLoader, knownProducts: IAvailableProducts) {
	let products: Product[] = [];
	if (!parsedArgs.product && await hasBuiltInProduct(parsedArgs.device.value)) {
		const productPath = await getBuiltinProductPath(parsedArgs.device.value);
		products = await loadProducts([productPath], loader, true);
	}
	else {
		const scriptNames = _.chain(parsedArgs.script)
			.map((scriptArgs) => scriptArgs.script?.path)
			.compact()
			.value();
		products = await processProductArgs(parsedArgs.product, loader, knownProducts, scriptNames);
	}
	if (parsedArgs.ccxxImageMode.value) {

		// filter out any products that include CCXX image meta content
		// this will ensure those products are not shown in the GUI and
		// references to them are not saved in serialized scripts
		products = _.filter(products, (p) => p.file.includesCCXXImageComponents);
		if (_.isEmpty(products)) {
			throw new ArgsError(
				`Can't enable "${parsedArgs.ccxxImageMode.userArgName}": No products set to includesCCXXImageComponents`);
		}
	}
	return products;
}

async function hasBuiltInProduct(deviceName: string) {
	const descriptions = await getDeviceDescriptions();
	const renamedDevice = getRenamedDeviceId(deviceName, descriptions);
	const deviceDes = _.find(descriptions.devices, (device) => device.name === renamedDevice);
	return deviceDes ? deviceDes.builtInProduct : false;
}

async function getBuiltinProductPath(deviceName: string) {
	const descriptions = await getDeviceDescriptions();
	const renamedDevice = getRenamedDeviceId(deviceName, descriptions);
	return `deviceData/${renamedDevice}/.metadata/product.json`;
}

async function processProductArgs(
	args: ParsedArg<string>[],
	loader: ScriptAndProductLoader,
	availableProducts: IAvailableProducts,
	scriptDirProductPaths: string[]) {

	const scriptProducts = Promise.all(_.map(scriptDirProductPaths, loadScriptDirProductPathProduct));

	let productFiles = await Promise.all(
		_.map(
			args,
			(arg) => processProductArg(arg.value, loader, availableProducts, `Invalid argument '${arg.userArgName}'`),
		),
	);
	productFiles = await resolveProductDependencies(productFiles, loader, availableProducts);

	const paths = _.uniq(_.map(productFiles, (p) => p.path));
	const products = await loadProducts(paths, loader);

	// only want to update the available list if the load succeeded
	// to avoid polluting it with broken products
	updateAvailableProducts(products, availableProducts);

	return [
		...products,
		...(await scriptProducts),
	];
}

function processProductArg(
	productDescriptor: string,
	loader: ScriptAndProductLoader,
	availableProductsProvider: IAvailableProducts,
	errorDecorator: string,
) {

	const parts = productDescriptor.split("@");
	const size = _.size(parts);
	if (size > 2) {
		throw new InvalidArgError(`Invalid format ${productDescriptor}`, errorDecorator);
	} else if (size === 2) {
		return processProductRefArg(parts[0], parts[1], loader, availableProductsProvider, errorDecorator);
	} else {
		return processProductPathArg(productDescriptor, loader, errorDecorator);
	}
}

async function readProductFile(
	productPath: string,
	loader: ScriptAndProductLoader,
	errorDecorator: string,
) {

	try {
		const filePath = loader.resolve(productPath);
		const fileSource = await loader.readProductFile(filePath);
		return loadMinProductFile(filePath, fileSource);
	} catch (e) {
		throw new SetupError(e.message, errorDecorator);
	}
}

function matchAvailableProduct(name: string, version: string) {
	if (isCloud()) {

		// Cloud always uses the latest version of a product, so if we're on the cloud and there's 
		// a newer version, then use that

		return (productInfo: AvailableProductInfo) => productInfo.name === name && productInfo.version >= version;
	}
	return (productInfo: AvailableProductInfo) => productInfo.name === name && productInfo.version === version;
}

async function processProductRefArg(
	name: string,
	version: string,
	loader: ScriptAndProductLoader,
	availableProductsProvider: IAvailableProducts,
	errorDecorator: string,
) {
	const availableProductsInfo = availableProductsProvider.getProductInfo();
	const info = _.filter(availableProductsInfo, matchAvailableProduct(name, version));

	if (_.isEmpty(info)) {
		throw new InvalidArgError(`No product with name "${name}" and version "${version}" found`, errorDecorator);
	}
	if (info.length > 1) {
		throw new InvalidArgError(
			`There are multiple products with name "${name}" and version "${version}.\n`
			+ "Please use the product's path instead.",
			errorDecorator,
		);
	}
	return readProductFile(info[0].path, loader, errorDecorator);
}

function processProductPathArg(
	productPath: string,
	loader: ScriptAndProductLoader,
	errorDecorator: string,
) {
	return readProductFile(productPath, loader, errorDecorator);
}

async function resolveProductDependencies(
	existingProducts: MinProductFile[], // products that potentially have dependencies
	loader: ScriptAndProductLoader,
	availableProducts: IAvailableProducts,
): Promise<MinProductFile[]> {
	const dependencies =
		_.chain(existingProducts)
			// save the source so that we can get better error message if dependency is not found
			.flatMap((p) => {
				return p.raw.dependencies ?
					_.map(p.raw.dependencies, (productRange, productName) => ({ source: p.raw.name, productName, productRange })) :
					undefined;
			})
			.compact()
			.uniq()
			.filter((d) => !_.find(existingProducts, (p) => productInRange(p.raw, d)))
			.compact()
			.value();

	if (_.isEmpty(dependencies)) {
		return existingProducts;
	} else {
		existingProducts = [
			...existingProducts,
			...await Promise.all(
				_.map(
					dependencies,
					(d) => processProductRange(
						d.productName,
						d.productRange,
						loader,
						availableProducts,
						`Cannot resolve dependency of ${d.source}`,
					),
				)),
		];
		return resolveProductDependencies(
			existingProducts,
			loader,
			availableProducts);
	}
}

async function processProductRange(
	productName: string,
	productRange: string,
	loader: ScriptAndProductLoader,
	availableProductsProvider: IAvailableProducts,
	errorDecorator: string,
) {
	const availableProductsInfo = availableProductsProvider.getProductInfo();
	const infos = _.chain(availableProductsInfo)
		.filter((a) => productInRange(a, { productName, productRange }))
		.map((a) => ({ ...a, cleanedVersion: isTIProductVersion(a.version) ? tiVersionToSemver(a.version) : a.version }))
		.value();
	if (_.isEmpty(infos)) {
		throw new Error(`${errorDecorator}: No product with name "${productName}" and version "${productRange}" found`);
	}
	const sorted = infos.sort((a, b) => semver.rcompare(a.cleanedVersion, b.cleanedVersion));

	return readProductFile(_.head(sorted).path, loader, errorDecorator);
}

function updateAvailableProducts(
	products: Product[],
	availableProducts: IAvailableProducts) {

	return availableProducts.update(_.map(products, (p) => p.file));
}
