const $moduleProxyHandler: ProxyHandler<any> = {
	set: (target: any, prop: string, val: any) => {
		if (_.includes(modReadOnlyKeys, prop)) {
			throw new TypeError("read only property: " + prop);
		} else {
			return Reflect.set(target, prop, val);
		}
	},
	deleteProperty: (target: any, prop: string) => {
		if (_.includes(modReadOnlyKeys, prop)) {
			throw new TypeError("read only property: " + prop);
		} else {
			return Reflect.deleteProperty(target, prop);
		}
	},
};

interface ModuleInstanceMgrOptionalParams {
	parent?: ModuleInstanceMgr;
	parentArrayMgr?: ModuleInstanceAdderMgr;
}

export const enum ModuleType {
	TOP,
	INTERNAL,
	ALL, // TOP and INTERNAL
}

type BuiltInConfigurableMgr = HardwareMemberMgr | NameMemberMgr | PinFrequencyConfigurableMgr;
export type NonObjectMemberMgr = MetaContentConfigurableMgr | BuiltInConfigurableMgr;

/**
 * Manages instances of runtime object created based on modules.
 */
export class ModuleInstanceMgr<T extends ModuleInstance = ModuleInstance>
	extends AObjectMgr<T> implements IMyListItem {

	protected static createInstanceImpl<ClassType extends ModuleInstanceMgr>(
		runtime: Runtime,
		mod: Module,
		constructor: () => ClassType) {

		// Static instance must be created first

		const moduleMgr = runtime.getModuleMgr(mod.$name);
		moduleMgr.initStatic(false);

		// Now create the non-static instance
		// meta-content derived configurables are done after to allow derived classes to specialize

		const instMgr = constructor();
		instMgr.initMetaConfigurables();

		// Setup global references to the new instance, and only then fetch dynamic configurables
		// This allows us to deal with cyclic references between modules

		mod.$instances.push(instMgr.managedObject);
		moduleMgr.instances.push(instMgr);
		moduleMgr.static.addSharedBy(instMgr);
		instMgr.initDynamicConfigurables();
		return instMgr;
	}

	public readonly parentModuleInstanceAdderMgr?: ModuleInstanceAdderMgr;
	public readonly parentInstanceMgr?: ModuleInstanceMgr;
	public hardwareMemberMgr: HardwareMemberMgr;
	public readonly metaContentConfigurableMgrs: { [memberName: string]: MetaContentConfigurableMgr } = {};
	public readonly addSeqNum: number;

	protected id: string;
	protected readonly nonObjectMembers: NonObjectMemberMgr[] = [];
	protected readonly builtInMembers: BuiltInConfigurableMgr[] = [];
	private nameMemberMgr: NameMemberMgr;
	private readonly interfaceReqs: InterfaceRequirements;
	private readonly moduleInstanceReqs: ModuleInstanceRequirements;
	private readonly moduleReqs: ModuleRequirements;
	private readonly sharedModuleInstanceReqs: SharedModuleInstanceRequirements;
	private readonly sharedBy: { parent: ModuleInstanceMgr, shareWithByDefault?: string }[] = [];
	private readonly sharedByMember: SharedByFixedDataMember;
	private readonly topModule: boolean = false;
	private extendedConfig: (StandardConfigurable | ConfigurableGroup)[];

	// view nodes that are resolved to generate the instance UI that are unchanging
	private nonObjectNodes: ViewNode[];
	private pinmuxNode: PinMuxContainerNode;
	private otherDepsNode: OtherDepsContainerNode;

	private inOnChange: ConfigurableMgr<any> = null;
	private isBeingConstructed = true;

	private validationLogger: IValidationLogger & LegacyInstanceValidation;

	protected constructor(
		runtime: Runtime,
		protected module: Module,
		protected userCreatedOrTouched: boolean,
		optionalParams: ModuleInstanceMgrOptionalParams = {},
	) {
		super(runtime, (options, member) => format(this, options, member));
		this.addSeqNum = configurationChanged();
		this.parentModuleInstanceAdderMgr = optionalParams.parentArrayMgr;
		this.topModule = this.runtime.isTopModule(module.$name);

		// Create the fixed builtin members for the meta-content to reflect on

		const formattersMap = this.runtime.getFormattersMap();
		this.parentInstanceMgr = optionalParams.parent;
		if (this.parentInstanceMgr) {
			this.addFixedMember(formattersMap, "$ownedBy", this.parentInstanceMgr.managedObject);
		}
		this.sharedByMember = new SharedByFixedDataMember(
			this, formattersMap, "$sharedBy", []);

		this.addFixedMember(formattersMap, "$module", new Proxy(module, $moduleProxyHandler));

		this.addFixedMember(formattersMap, "$uiState",
			new Proxy(this.memberMgrs, managedUIStateProxyHandler) as any as InstanceUIState);

		// Create objects to manage requirements as they change based on meta data

		this.interfaceReqs
			= new InterfaceRequirements(this.runtime, this);
		this.moduleInstanceReqs
			= new ModuleInstanceRequirements(this.runtime, this);
		this.sharedModuleInstanceReqs
			= new SharedModuleInstanceRequirements(this.runtime, this);
		this.moduleReqs
			= new ModuleRequirements(this.runtime, this);
	}

	// We want to return all owning instances, until we hit one that is a top module.  That way we will see error 
	// summary badges even where they are owned, but we won't put the badge on an owning module if the child is in the 
	// left pane itself.  This way, you'll see that POWER has an error, as do Other Dependencies, but only if you click
	// on the module that pulled it in.  The parents of POWER (of which there are many) would otherwise all have errors
	// and it would look kinda scary.

	public override getContainingInstanceMgrs(): ModuleInstanceMgr[] {
		if (!this.isTopModule()) {
			if (this.parentInstanceMgr) {
				return [this, ...this.parentInstanceMgr.getContainingInstanceMgrs()];
			}
			return [this, ..._.flatMap(this.sharedBy, (inst) => inst.parent.getContainingInstanceMgrs())];
		}
		return [this];
	}

	// As with getContainingInstanceMgrs, find tree nodes for owning instances until a top module is hit.
	// In addition, we need to find the hardware nodes too

	public override getContainingTreeNodes(): ITreeNode[] {
		const swNodes = _.flatMap(this.getContainingInstanceMgrs(), (i) => i.getModuleMgr());
		const hwComponent = this.hardwareMemberMgr.getValue();
		const hwNodes = hwComponent ? this.runtime.getModuleToHardwareMap().getTreeNodes(hwComponent) : [];
		return [...swNodes, ...hwNodes];
	}

	// Unlike getContainingTreeNodes, this returns the main leaf node that this module instance would be found at

	public getLeafTreeNode(): ITreeNode {
		return this.getModuleMgr();
	}

	public getPrimaryTab() {
		return TabName.SOFTWARE;
	}

	public reApplyParentArgs() {
		const parent = this.getOwner();
		if (parent) {
			parent.applyArgsToChild(this.managedObject);
		}
	}

	public applyArgsToChild(child: ModuleInstance) {
		const childMember = _.find(this.getModuleInstanceMemberMgrs(ModuleType.ALL), (mgr) => mgr.getValue() === child);
		if (childMember) {
			childMember.reApplyArgs();
			this.reApplyParentArgs();
		}
	}

	public revealMember(itemPath: string[]) {
		_.each(this.getViewNodes(), (n) => {
			if (n.type === "container") {
				return !reveal(n, itemPath); // explicitly break out of loop once revealed
			}
			return true;
		});
	}

	public setLockStatus(status: boolean) {
		_.each(this.getAllLockables(), (l) => l.setLockStatus(status));
	}

	public isStatic(): this is StaticModuleInstanceMgr {
		return false;
	}

	public isTopModule() {
		return this.topModule;
	}

	public getID() {
		return this.id;
	}

	public isExclusivelyOwned() {
		return this.parentInstanceMgr;
	}

	public isRemovable() {
		return !this.isExclusivelyOwned() && _.isEmpty(this.sharedBy);
	}

	public addSharedBy(parent: ModuleInstanceMgr, requiredArgs?: InstanceArgs, shareWithByDefault?: string) {
		this.sharedBy.push({ parent, shareWithByDefault });
		this.sharedByMember.changeData(_.map(this.sharedBy, (entry) => entry.parent.managedObject));
		if (requiredArgs) {
			this.setValueFromRequiredArgs(
				requiredArgs,
				parent,
			);
		}
	}

	public override remove() {
		if (!this.isBeingConstructed) {
			configurationChanged();
			super.remove();
		}
	}

	public removeSharedBy(inst: ModuleInstanceMgr) {

		// it is possible for a single inst to have multiple references to us
		// we only want to remove one reference for each call

		_.pullAt(this.sharedBy, _.findIndex(this.sharedBy, (i) => i.parent === inst));

		this.sharedByMember.changeData(_.map(this.sharedBy, (entry) => entry.parent.managedObject));
		if (_.isEmpty(this.sharedBy)) {
			// What should be done with the replaced instance, it could potentially be obsolete.
			// For now, if it was not created by the user and is not used by anything, just remove it.
			if (!this.isUserCreatedOrTouched() && !this.isBeingConstructed) {
				this.remove();
				return;
			}
		}
		_.each(this.nonObjectMembers, (mem) => mem.removeRequiredByParent(inst));
	}

	public isCurrentlyShared() {
		return !_.isEmpty(this.sharedBy);
	}

	public getSharedBy() {
		return _.map(this.sharedBy, (i) => i.parent);
	}

	public getShareWithByDefault() {
		return _.find(this.sharedBy, (i) => !_.isEmpty(i.shareWithByDefault))?.shareWithByDefault;
	}

	public getOwner() {
		return this.parentInstanceMgr;
	}

	public inArray() {
		return !!this.parentModuleInstanceAdderMgr;
	}

	public canBeShared() {
		return !this.isExclusivelyOwned();
	}

	public getName() {
		return this.getNameMgr().getValue();
	}

	public getNameMgr() {
		return this.nameMemberMgr;
	}

	public getOwnershipInfo() {
		const owner = this.parentInstanceMgr && this.parentInstanceMgr.managedObject;
		const sharer = this.sharedBy ? _.map(this.sharedBy, (p) => p.parent.managedObject) : [];
		return (owner || !_.isEmpty(sharer)) ? { owner, sharer } : null;
	}

	public getParents() {
		return _.compact([
			this.getOwner(),
			...this.getSharedBy(),
		]);

	}

	// get a copy of the current owned and shared reqs
	public getOwnedAndSharedReqs() {
		// Note, we want a clone of the underlying objects in the array, not just a clone of the 
		// array.  That's because updateArgs may change the args props on the original objects 
		return {
			shared: _.map(this.sharedModuleInstanceReqs.getCurrentRequirements(), _.clone),
			owned: _.map(this.moduleInstanceReqs.getCurrentRequirements(), _.clone),
		};
	}

	public override validate(validations: Validations): void {
		super.validate(validations);

		if (this.module.validate) {

			if (!this.validationLogger) {
				const target = {
					memberMgrs: this.memberMgrs,
					managedObject: this.managedObject,
					validationLogger: this.runtime.getValidationLogger(),
				};
				this.validationLogger = validationLoggerWithLegacy(target);
			}

			this.module.validate(this.managedObject, this.validationLogger);
		}

		// max instances validation
		if (!this.isStatic()) {
			this.getModuleMgr().validateInstanceCount(this.runtime.getValidationLogger(), this.managedObject);
		}
	}

	public finalValidate(): void {

		if (this.managedObject.$module.validatePinmux) {

			const validation = _.clone(this.runtime.getValidationLogger());

			// Do not add the raw validation structures that we use for validate
			// This is a newer API and thus doesn't have legacy stuff to support

			this.managedObject.$module.validatePinmux(this.managedObject, validation);
		}
	}

	public applySolverValidation() {
		_.each(this.getInterfaceInstanceMemberMgrs(), (i) => i.valueObjectMgr.applySolverValidation(i));
	}

	public getInterfaceInstanceMemberMgrs() {
		return _.map(
			this.interfaceReqs.getCurrentRequirements(),
			(req) => this.memberMgrs[req.name] as InterfaceInstanceMemberMgr | GPIOPinMemberMgr | ExtendedPinMemberMgr,
		);
	}

	public getInstanceAdderMemberMgrs() {
		return (
			_.chain(this.moduleInstanceReqs.getCurrentRequirements())
				.filter((req) => !!req.useArray)
				.map((req) => this.memberMgrs[req.name] as ModuleInstanceAdderMemberMgr)
				.value()
		);
	}

	public getInternalModuleInstanceMemberMgrs() {
		return this.getModuleInstanceMemberMgrs(ModuleType.INTERNAL);
	}

	public getTopModuleInstanceMemberMgrs() {
		return this.getModuleInstanceMemberMgrs(ModuleType.TOP);
	}

	public getModuleMemberMgrs(): ModuleMemberMgr[] {
		return _.map(
			this.moduleReqs.getCurrentRequirements(),
			(req) => this.memberMgrs[req.name] as ModuleMemberMgr,
		);
	}

	public getSharedModuleInstanceMemberMgrs() {
		return _.map(
			this.sharedModuleInstanceReqs.getCurrentRequirements(),
			(req) => this.memberMgrs[req.name] as SharedInstanceMemberMgr,
		);
	}

	// Returns statements to add this instance, if those statements are necessary and haven't yet been added

	public getAddInstanceStatements() {

		// If this instance hasn't already been added, add it.  The reason it may already be added is that we call this
		// for both the initial adds for user included modules, but then also later if the module has any configuration 
		// to serialize.  The later will handle shared modules which need to be added at that point.  
		//
		// Owned modules are never added, but are just referenced via their parent, so they never need an add

		if (!this.isExclusivelyOwned()) {
			const modulesAdded = this.runtime.getSerializationContext().getModulesAdded();
			if (!modulesAdded.has(this)) {
				modulesAdded.add(this);
				const scriptIdentifier = this.getScriptIdentifier();
				return this.createAddInstanceStatements(scriptIdentifier);
			}
		}
		return [];
	}

	public getAllChildren() {
		const instanceAdderInstances = _.flatMap(this.getInstanceAdderMemberMgrs(),
			(m) => m.valueObjectMgr.getInstances());
		const childModuleInstanceMgrs = [
			..._.flatMap(this.getSharedModuleInstanceMemberMgrs(), (mgr) => mgr.valueObjectMgr),
			..._.flatMap(this.getModuleInstanceMemberMgrs(ModuleType.ALL), (mgr) => mgr.valueObjectMgr),
			...instanceAdderInstances,
		];
		return childModuleInstanceMgrs;
	}

	public getUsedPins() {

		const reqs = this.getSolverRequirements();
		const pinSelectionMap = getAssignedPins(reqs);
		const childModules = this.getAllChildren();
		return _.reduce(childModules, (result, m) => {
			result = (new Set([...result, ...m.getUsedPins()]));
			return result;
		}, pinSelectionMap);
	}

	public getSolverRequirements() {
		return _.flatMap(
			this.getInterfaceInstanceMemberMgrs(),
			(mem) => mem.valueObjectMgr.getSolverRequirements() as (Peripheral | GPIO)[],
		);
	}

	public solveComplete() {
		_.each(
			this.getInterfaceInstanceMemberMgrs(),
			(mem) => mem.valueObjectMgr.solveComplete(),
		);
	}

	public override onMemberChanged(member: AnyMemberMgr, source: SetSource): void {
		// The only thing scripts can do is call scripting functions (which are already protected) 
		// and set members.  As such, we need to guard everything that happens on a member set.  
		// This might call onChange, onHardwareChanged, as well as fetching new requirements, which
		// can indirectly call filter etc.  But by guarding the whole thing, we know that scripting
		// is correctly guarded

		disableScriptingForCallback(() => {
			if (member === this.nameMemberMgr) {
				this.onNameChanged();
			} else if (member instanceof ConfigurableMgr) {
				if (!this.inOnChange) { // block cascading on changes
					this.runOnChanged(member, () => {
						if (member.def.onChange) {
							guardCallbackAccess(() =>
								withDeprecatedAccess({ read: member.def.deprecated },
									() => member.def.onChange(this.managedObject, this.managedObject.$uiState)),
								"onChange",
								this,
								this.getModuleName(),
							);
						}
					});
					this.resolveRequirements(member, source);
				}
			}
		});
	}

	public onButtonClicked<ButtonResultType>(member: ButtonConfigurableMgr<ButtonResultType>, response: ButtonResultType): void {
		// Unlike onMemberChanged, buttons can only be clicked within the UI and not triggered via a script or callback.  
		// As such, we know that scripting is already disabled and this can be a bit simpler

		if (!this.inOnChange) {
			if (member.def.onComplete) {
				this.runOnChanged(member, () => member.def.onComplete(this.managedObject, this.managedObject.$uiState, response));
				this.resolveRequirements(member);
			}
			if (member.def.scriptingOnComplete) {
				runAsUserScript(() => member.def.scriptingOnComplete(this.managedObject, this.managedObject.$uiState, response));
			}
		}
	}

	public getModuleMgr() {
		return this.runtime.getModuleMgr(this.managedObject.$module.$name);
	}

	public modifiedInUI() {
		if (this.isExclusivelyOwned()) {
			this.parentInstanceMgr.modifiedInUI();
		}
		if (this.isTopModule()) {
			this.setUserCreatedOrTouched(true);
		}
	}

	public setUserCreatedOrTouched(val: boolean) {
		this.userCreatedOrTouched = val;
	}

	// Indicates if the module was included in the configuration by user actions.  This includes both modules that the 
	// user explicitly added, as well as top modules pulled in by another module that are then subsequently modified by
	// the  user.  The reason for the latter case is that if a module pulled in a shared SPI, and then the user made 
	// significant modifications to it, we don't necessarily want to lose those modifications if they later remove 
	// whatever pulled in the SPI.  A better long term approach may be to prompt the user, but so far that hasn't been
	// requested.

	public isUserCreatedOrTouched() {
		return this.userCreatedOrTouched;
	}

	public getScriptIdentifier(): string {
		const identifers = this.runtime.getSerializationContext().getModuleIdentifiers();
		const instScriptIdentifier = this.getModuleMgr().getInstanceScriptIdentifier(this);
		return identifers.getScriptIdentifiers(this, instScriptIdentifier);
	}

	public getModuleName() {
		return this.getModuleMgr().getName();
	}

	public override currentlyAllowMetaAssign() {
		return !!this.inOnChange;
	}

	public override currentMetaAssign() {
		return this.inOnChange;
	}

	public isReservation() {
		return false;
	}

	public applyUIDefaults() {
		const hardwareDefault = this.runtime.getModuleToHardwareMap().getUIDefault(this.module);
		if (hardwareDefault) {
			this.memberMgrs.$hardware.set(hardwareDefault, SetSource.USER_ASSIGN);
		}
	}

	public getViewNodesForGroup(group: string) {
		return _.filter([
			...this.getModuleInstanceMgrsInOrder(ModuleType.ALL),
			...this.getSharedModuleInstanceMemberMgrs(),
		], (m) => m.def.group === group && !m.def.hidden);
	}

	public getViewNodes() {

		if (!this.nonObjectNodes) {
			this.nonObjectNodes = [
				new ValidationLeafNode(this, this.runtime.getValidations()),
				new ConfigLeafNode(this.builtInMembers, "builtin"),
				...createViewNodesFromConfig(this.module.config, this, "/group"),
				...createViewNodesFromConfig(this.extendedConfig, this, "/extendedConfig"),
			];
		}
		const nodes = [...this.nonObjectNodes];

		const ifaceMgrs = this.getInterfaceInstanceMemberMgrs();
		if (!_.isEmpty(ifaceMgrs)) {
			const { group } = this.runtime.getPinmuxUIOptions();
			const pinmuxContent = new PinMuxLeafNode(ifaceMgrs);
			if ("collapsed" === group || "expanded" === group) {
				if (!this.pinmuxNode) {
					this.pinmuxNode = new PinMuxContainerNode(this, "collapsed" === group);
				}
				this.pinmuxNode.setContent(pinmuxContent);
				nodes.push(this.pinmuxNode);
			} else if ("merged" === group) {
				nodes.push(pinmuxContent);
			} else {
				assertUnreachable(group);
			}
		}

		// group object member configurables (that aren't explicitly grouped) in to two groups
		// a less prevalent "Other Dependencies" and more prevalent "in lined" dependencies

		const ungroupped = _.filter(
			[
				...this.getModuleInstanceMgrsInOrder(ModuleType.ALL),
				...this.getSharedModuleInstanceMemberMgrs(),
			], (m) => !m.def.group || m.def.hidden);
		const { other, inline } = _.groupBy(
			[
				...ungroupped,
				...this.getModuleMemberMgrs(),
			], (m) => (m.def.hidden || m instanceof ModuleMemberMgr) ? "other" : "inline");

		if (inline) {
			nodes.push(...inline);
		}

		if (!_.isEmpty(other)) {
			if (!this.otherDepsNode) {
				this.otherDepsNode = new OtherDepsContainerNode(this);
			}
			this.otherDepsNode.setContent(other);
			nodes.push(this.otherDepsNode);
		}

		return nodes;
	}

	public override getScriptStatements(identifier: string, options: SerializationOptions): Statement[] {

		// Save the identifier

		this.runtime.getSerializationContext().getModuleInstanceIdentifiers().set(this, identifier);

		// Determine the configuration statements

		const configStatements = [
			...super.getScriptStatements(identifier, options),
			...this.getUIStatements(identifier, options),
		];

		// We don't need an add statement if there's nothing to actually configure

		if (_.isEmpty(configStatements)) {
			return [];
		}
		return [
			...this.getAddInstanceStatements(),
			...configStatements,
		];
	}

	public shouldSerializeAdd() {

		// We want an addModule or addInstance statement for anything explicitly included in the configuration by the
		// user's actions.  See isUserCreatedOrTouched for more details.

		// Note that implicitly created modules via sharedModuleInstances are also created with AddInstance, but with
		// false (non user created) passed in, and later on in the script (right before being configured).  This 
		// originally was to prevent them from being selected and then deleted early, but that is now handled 
		// elsewhere.  However, this is still done to indicate they aren't really part of the user's configuration 
		// directly.  As such, they will return false here (unless they are user-modified top modules as well).

		return this.isUserCreatedOrTouched();
	}

	public shouldSerializeConfig() {
		// Implicitly created modules via moduleInstances are serialized as part of their parent's config (return false)
		// Implicitly created modules via sharedModuleInstances are serialized individually once all parents are
		// serialized (return true)

		return !this.isExclusivelyOwned();
	}

	public getModuleInstanceMgrsInOrder(type: ModuleType) {
		const reqs = this.moduleInstanceReqs.getCurrentRequirements();
		const moduleInstmemberMgrs = [
			...this.getModuleInstanceMemberMgrs(type),
			...this.getInstanceAdderMemberMgrs(),
		];
		return _.sortBy(moduleInstmemberMgrs, (item) => {
			return _.indexOf(_.map(reqs, (req) => req.name), item.def.name);
		});
	}

	public onUserScriptsComplete() {

		// If this module has a migrateLegacySettings function, and at least one of it's deprecated
		// members was touched, then run that migration script

		if (this.module.migrateLegacyConfiguration &&
			_.some(this.memberMgrs, (m) => m.def.deprecated && m.isUserModified())) {
			runAsUserScript(() => this.module.migrateLegacyConfiguration(this.managedObject), { read: true });
		}
	}

	public getModName() {
		return this.module.$name;
	}

	public override getContainingModule() {
		return { modInstMgr: this, memberPath: [] as string[] };
	}

	protected getExtendConfigArgs() {
		return {};
	}

	protected addMetaContentConfigurableMgrs(configs: StandardConfigurable[]) {
		const configurableMgrs = _.map(configs, (def) => this.createMetaContentConfigurableMgr(def));
		addMetaContentConfigurableMgrs(this, configurableMgrs);
		this.nonObjectMembers.push(...configurableMgrs);
	}

	protected createMetaContentConfigurableMgr(def: StandardConfigurable): MetaContentConfigurableMgr {
		return createMetaContentConfigurableMgr(def, this, this.runtime.getFormattersMap(), this.getModName());
	}

	protected override preRemove() {

		const moduleMgr = this.getModuleMgr();

		_.remove(moduleMgr.instances, (i) => i === this);
		_.remove(this.managedObject.$module.$instances, (i) => i === this.managedObject);

		moduleMgr.static.removeSharedBy(this);
	}

	// split out the creation of meta-content derived configurables so that derived classes can override

	protected initMetaConfigurables() {

		const runtime = this.runtime;
		const formattersMap = runtime.getFormattersMap();

		// Create the meta-content defined static configurables (which may override $name and $hardware)

		const { $name, $hardware, moduleConfigs } = this.splitConfigs();

		const { id, nameMemberMgr } = this.createNameMemberMgr($name);
		this.id = id;
		this.nameMemberMgr = nameMemberMgr;

		this.hardwareMemberMgr = new HardwareMemberMgr(
			this, $hardware, runtime.getModuleToHardwareMap(), runtime.getDeviceData(), formattersMap);

		// Add built-in configurables to appropriate containers

		this.builtInMembers.push(this.nameMemberMgr, this.hardwareMemberMgr);
		this.nonObjectMembers.push(this.nameMemberMgr, this.hardwareMemberMgr);

		// Now add all static meta-content defined configurables

		this.addMetaContentConfigurableMgrs(_.values(moduleConfigs));

		// Create all configurables based on the one-time call to init

		if (this.module.extendConfig) {
			const extendConfig = () => {
				const config = this.module.extendConfig(this.getExtendConfigArgs());
				if (config && !_.isArray(config)) {
					throw new Error(this.getModuleName() + ": extendConfig must return an array");
				}
				return config;
			};
			this.extendedConfig = guardCallbackAccess(extendConfig, "extendConfig", this, this.getModuleName());

			this.addMetaContentConfigurableMgrs(flattenConfigs(this.extendedConfig));
		}
	}

	// Split out the first call to resolveRequirements so we can handle circular dependencies between static and 
	// instance (see cyclicReferences-spec)

	protected initDynamicConfigurables() {
		this.resolveRequirements();
		this.isBeingConstructed = false;
	}

	protected override getMembersInScriptOrder(options: SerializationOptions): AnyMemberMgr[] {

		// Note that since shared ownership may assign required args, we treat that
		// assignment as a non-object assignment, but of the child module.
		// So the object members of THIS module are all object members other than
		// shared ones

		const objectMembers = _.difference(_.values(this.memberMgrs),
			[...this.nonObjectMembers, ...this.getSharedModuleInstanceMemberMgrs()]);

		// Likewise, non-object members include the assignment statements to the
		// shared parents

		const nonObjectMembers = [
			...this.nonObjectMembers,
			..._.chain(this.sharedBy)
				.flatMap((sb) => sb.parent.getSharedModuleInstanceMemberMgrs())
				.filter((m) => m.get() === this.managedObject)
				.value(),
		];

		// nonObject members go first, since object members depend on them

		return [
			..._.sortBy(nonObjectMembers, (m) => m.getSerializationOrder(options)),
			...objectMembers,
		];
	}

	protected createNameMemberMgr(nameConfig: NameConfigurable): { id: string, nameMemberMgr: NameMemberMgr } {

		validateConfigurable(nameConfig, `Configurable "$name" of "${this.getModName()}"`, SCHEMA.NameConfigurable);

		const modName = this.getModName();
		const namePrefix: string = nameConfig.defaultPrefix ||
			// eslint-disable-next-line deprecation/deprecation
			this.module.defaultInstanceName ||
			this.runtime.getModuleMgr(modName).getDefaultInstanceName(modName);

		const nameStartingIndex = nameConfig.startingIndex || 0;

		const nameAndId = this.runtime.getModuleInstanceNextNameAndId(modName, namePrefix, nameStartingIndex);

		const config: NameTextConfig = {
			default: nameAndId.name,
			longDescription: nameConfig.longDescription,
			description: nameConfig.description,
		};

		const isHidden =
			(!this.isTopModule() && (nameConfig.hidden !== false)) || this.getModuleMgr().getUIView() === "fileTree";

		return {
			id: nameAndId.id,
			nameMemberMgr: new NameMemberMgr(this, this.runtime.getFormattersMap(), config,
				{
					isReadOnly: false,
					isHidden,
				}),
		};
	}

	// Create the add instance statements

	protected createAddInstanceStatements(scriptIdentifier: string): Statement[] {

		// Note that we need to ensure the static module is also added, so we have something to call addInstance() on

		return [
			...this.getModuleMgr().static.getAddInstanceStatements(),
			createAddModuleInstanceStatement(
				scriptIdentifier, this.getModuleMgr().getScriptIdentifier(), this.isUserCreatedOrTouched()),
		];
	}

	private getUIStatements(identifier: string, options: SerializationOptions): Statement[] {
		if (options.includeUIState) {

			// Serialize the UI specific nodes
			// MemberMgrs that are also container nodes, will be covered by
			// the generic algorithm, when the member is visited.

			return _.flatMap(this.getViewNodes(),
				(n) => n instanceof AContainerNode ? n.getUIScriptStatements(identifier) : []);
		}
		return [];
	}

	private splitConfigs() {
		const { $name, $hardware, ...moduleConfigs } = this.module.$configByName;
		return {
			$name,
			$hardware,
			moduleConfigs: moduleConfigs as {
				[configName: string]: StandardConfigurable,
			},
		};
	}

	private runOnChanged(changedMember: ConfigurableMgr<any>, action: () => void) {
		this.inOnChange = changedMember;
		try {
			action();
		} finally {
			this.inOnChange = null;
		}
	}

	private onNameChanged() {
		this.resolveRequirements(this.nameMemberMgr);
	}

	private resolveRequirements(cause?: AnyMemberMgr, reason?: SetSource) {
		this.interfaceReqs.resolveRequirements(cause, reason);
		this.moduleInstanceReqs.resolveRequirements(cause, reason);
		this.sharedModuleInstanceReqs.resolveRequirements(cause, reason);
		this.moduleReqs.resolveRequirements(cause, reason);
	}

	private getModuleInstanceMemberMgrs(type: ModuleType) {
		return (
			_.chain(this.moduleInstanceReqs.getCurrentRequirements())
				.filter((req) =>
					!req.useArray &&
					(ModuleType.ALL === type ||
						(ModuleType.TOP === type) === this.runtime.isTopModule(req.moduleName)),
				)
				.map((req) => this.memberMgrs[req.name] as ModuleInstanceMemberMgr)
				.value()
		);
	}

	private getAllLockables() {
		return _.map(this.getInterfaceInstanceMemberMgrs(), (m) => m.valueObjectMgr);
	}
}

function areRequiredSettingsCompatible(
	requiredArgs: InstanceArgs,
	child: ModuleInstanceMgr,
	allowUnlocked: boolean,
): boolean {
	return _.every(requiredArgs, (arg, key) => {
		const member = child.memberMgrs[key];
		if (member instanceof ModuleInstanceMgr) {
			return areRequiredSettingsCompatible(arg as InstanceArgs, member, allowUnlocked);
		} else {
			// When allowUnlock is true, any member that is not readOnly is considered compatible.
			// - auto assign => no allowUnlocked
			// - user assign => allowUnlocked because we will change the unlocked members into compatible values
			// - validation => no allowUnlocked because at this point all changes should have been made 
			return (allowUnlocked && !member.uiState.readOnly) ||
				_.isEqual(arg, member.getValue());
		}
	});
}

// Use this when we want to relax the constraint and allow instances that have members
// with UNLOCKED incompatible values.
export function isSharedAssignable(child: ModuleInstanceMgr, requiredArgs: InstanceArgs) {
	return areRequiredSettingsCompatible(requiredArgs, child, true);
}

export function isCompatibleWithReq(child: ModuleInstanceMgr, requiredArgs: InstanceArgs) {
	return areRequiredSettingsCompatible(requiredArgs, child, false);
}

// We need a factory instantiation method as we can't do everything we need in the constructor as we want some of the 
// initialization to differ for derived classes.  To do that we have the following options:
// 1) create a static public "create" function in the class and alter it in derived classes
// 2) create a factory object that is a friend in order to access the non-public methods
// 3) create a factory object that instantiates a derived version of ModuleInstanceMgr with necessary functions public
// 4) create a factory object that derives from ModuleInstanceMgr in order to access the protected methods
//
// #1 will not work because typescript forces derives classes to have the same static methods (public/private level as 
// well as signature), and they need to differ in signature
// #2 will not work as there's no "friend" feature in typescript
// #3 and #4 would both work, but #4 is less typing and returns a simpler object

export class ModuleInstanceMgrFactory extends ModuleInstanceMgr {
	public static createInstance(
		runtime: Runtime,
		mod: Module,
		userCreated: boolean,
		optionalParams: ModuleInstanceMgrOptionalParams) {

		return ModuleInstanceMgr.createInstanceImpl(runtime, mod, () => new ModuleInstanceMgr(runtime, mod, userCreated, optionalParams));
	}

	// Prevent accidental construction

	private constructor() {
		super(null, null, null, null);
	}
}
