import * as _ from "lodash";
import * as path from "path";
import { BundleLoader } from "./bundleLoader";
import { FileSystemLoader } from "./fileSystemLoader";
import { System, ScriptingObject } from "public/runtime";
import { MetaCodeLoader } from "../contextify";
import { Product } from "../../product/types";
import { internalBoundary } from "../../niceExceptions";
import { assertUnreachable } from "../../utils";

// Provide access to raw resources before they are evaluated and bound
// to a particular runtime. They can also be used to directly fetch resources
// that don't reference the runtime such as JSON files.
export interface IMetaContentLoader {
	hasResource(fullPath: string): boolean;
	loadResource(fullPath: string): MetaCodeLoader;
	getProduct(): Product; // Reference back to the product this resource loader belongs to
	listResources(fullPath: string): string[]; // list resources in a directory
	isFile(fullPath: string): boolean; // check if a resource is a file resource
	getCombinedPath(fullPath: string): string;
}

interface FilePath {
	filePath: string;
}

interface BundleData {
	bundle: string;
}

export type MetaContentLocation = FilePath | BundleData;

function isBundle(resource: MetaContentLocation): resource is BundleData {
	return "bundle" in resource;
}

interface MetaCodeGlobalsFactory {
	createSystemObj(physicalPath: string): System;
	getScripting(): ScriptingObject;
}

// Runtime object for data-only resources.  It can just return null
// for these objects as they aren't to be used!

const jsonGlobalsFactory: MetaCodeGlobalsFactory = {
	createSystemObj: () => null,
	getScripting: () => null,
};

// This class is responsible for loading resources.  It is given an array of
// paths or paths to bundles, and then loads resources from those in the order
// given. 

interface ResourceEntry {
	resource: any;
}

interface ErrorEntry {
	error: Error;
}

function isResource(entry: ResourceEntry | ErrorEntry): entry is ResourceEntry {
	return "resource" in entry;
}

const metaFolder = ".meta";

// Applies a relative path to an existing path
export function toFullPath(includingFilePath: string, relativePath: string) {
	if ("/" === relativePath[0]) {

		// A full path was passed in - it's relative to nothing

		includingFilePath = "";

	} else if (!includingFilePath) {

		// A relative path without an including path was passed in
		// treat it as relative to root

		includingFilePath = "/";
	}

	const combinedPath = includingFilePath.split("/");
	combinedPath.pop();	// Remove name of file
	_.each(relativePath.split("/"), (pathEntry) => {
		if (".." === pathEntry) {
			if (1 === combinedPath.length) { // include empty "/" element
				throw new Error("Cannot specify a path above the root path");
			}
			combinedPath.pop();
		} else if ("." !== pathEntry) {
			combinedPath.push(pathEntry);
		}
	});
	return combinedPath.join("/");
}

function getBaseExtension(resourceType: ResourceType) {
	switch (resourceType) {
		case ResourceType.CODE: {
			return ".js";
		}
		case ResourceType.DATA: {
			return ".json";
		}
		case ResourceType.TEMPLATE: {
			return ".xdt";
		}
		default:
			assertUnreachable(resourceType);
	}
}

const extensionPrefix = ".syscfg";
export function toCanonicalPath(originalPath: string, resourceType: ResourceType) {
	// If the default extension is already there, we can remove it as the canonical path implies it

	const defaultExtension = `${extensionPrefix}${getBaseExtension(resourceType)}`;
	if (_.endsWith(originalPath, defaultExtension)) {
		originalPath = originalPath.slice(0, -_.size(defaultExtension));
	}

	// Need to resolve .. and eliminate .meta too

	return _.replace(toFullPath(null, originalPath), `/${metaFolder}/`, "/");
}

function createLoader(resource: MetaContentLocation, product: Product) {
	if (isBundle(resource)) {
		return new BundleLoader(resource.bundle, product);
	} else {
		return new FileSystemLoader(resource.filePath, product);
	}
}

// This loader wraps multiple meta-content loaders so that they are searched in the correct order.
// It does not depend on the runtime, and thus can be used before the runtime is created to load
// data resources, or to query for resources.  
// 
// To non-data resources can be loaded by using ResourceLoader (below) which is associated with 
// a runtime.

export class RawResourceLoader {

	// I've memoized these two public function as the file system checks are expensive when not
	// using a bundle, and since we cache loaded resources in this.loadedResources anyway, we may
	// as well also cache what is a file and what a folder contains too.

	public isFile = _.memoize((fullPath: string) => {
		const sanitizedFullPath = sanitize(fullPath, null);
		const { physicalPath, loader } = this.findPathAndLoader(sanitizedFullPath);
		return loader.isFile(physicalPath);
	});

	public listResources = _.memoize((fullPath: string) => {

		const sanitizedFullPath = sanitize(fullPath, null);

		if (this.isFile(sanitizedFullPath)) {
			throw new Error("Can't list resource for a file");
		}

		const possiblePaths = this.calculatePhysicalPaths(sanitizedFullPath);

		return (
			_.chain(possiblePaths)
				.flatMap((p) => _.flatMap(this.loaders, (rl) => rl.listResources(p)))
				.uniq() // paths can be duplicated across loaders
				.value()
		);
	});

	private readonly loaders: IMetaContentLoader[];
	private readonly loadedResources: { [key: string]: ResourceEntry | ErrorEntry } = {};
	private readonly resourcePhysicalPaths: string[] = [];

	constructor(arg: Product[] | MetaContentLocation[] | RawResourceLoader) {
		if (_.isArray(arg)) {
			this.loaders = (
				isSocMetadata(arg)
					? _.map(arg, (r) => createLoader(r, null))
					: _.flatMap(arg, (p) => _.map(p.resources, (r) => createLoader(r, p)))
			);
		} else {
			this.loaders = arg.loaders;

			// Do not copy the loaded resources cache
			// Non-data resources are stateful, and that state is in the cache entry
			// We could copy data resource entries, but it's likely a minimal runtime savings as 
			// they are likely only ever accessed once anyway...
		}
	}

	public getLoadedResourcePhysicalPaths() {
		return this.resourcePhysicalPaths;
	}

	public getJSONResource(fullPath: string) {

		// Load the resource as normal, but use a dummy runtime (as it shouldn't contain executable code)

		const sanitizedFullPath = sanitize(fullPath, ResourceType.DATA);
		return this.loadResource(sanitizedFullPath, jsonGlobalsFactory);
	}

	public getProduct(fullPath: string, resourceType: ResourceType) {

		// Find the loader associated with the resource, and return that loader's product

		const sanitizedFullPath = sanitize(fullPath, resourceType);
		return this.findPathAndLoader(sanitizedFullPath).loader.getProduct();
	}

	protected loadResource(sanitizedFullPath: string, runtime: MetaCodeGlobalsFactory) {
		if (!(sanitizedFullPath in this.loadedResources)) {

			// Initializing the resource could pull in other resources, so add 
			// a dummy one to prevent recursive includes

			this.loadedResources[sanitizedFullPath] = {
				error: new Error(`Cyclic reference detected in ${sanitizedFullPath}`),
			};

			try {

				// Find the correct loader and real path, then use that loader to get
				// the resource init function

				const { physicalPath, loader } = this.findPathAndLoader(sanitizedFullPath);
				const loaderFunc: MetaCodeLoader = loader.loadResource(physicalPath);

				// Generate system/scripting variables, then call the resource init function in an
				// internal boundary (so that exceptions will list the location of the internal error)

				const system = runtime.createSystemObj(physicalPath);
				const scripting = runtime.getScripting();
				const resource = internalBoundary(() => loaderFunc(_, system, system, scripting, (p) => system.getScript(p + ".js")));

				// Cache the resource for next time
				this.resourcePhysicalPaths.push(physicalPath);
				this.loadedResources[sanitizedFullPath] = { resource };
			} catch (error) {
				this.loadedResources[sanitizedFullPath] = { error };
			}
		}

		const entry = this.loadedResources[sanitizedFullPath];
		if (isResource(entry)) {
			return entry.resource;
		}

		throw entry.error;
	}

	private findPathAndLoader(sanitizedFullPath: string) {

		const pathsToTest = this.calculatePhysicalPaths(sanitizedFullPath);

		// Now, find a loader that has a resource at one of those paths.  Save the path we searched
		// along the way

		let physicalPath: string;
		const loader = _.find(this.loaders, (l) => {
			physicalPath = _.find(pathsToTest, (p) => l.hasResource(p));
			return !!physicalPath;
		});
		if (!loader) {
			const resourcePaths = _.map(this.loaders, (l) => {
				return _.map(pathsToTest, (p) => {
					return l.getCombinedPath(p);
				});
			});
			const pathsToBeListed = _.chain(resourcePaths)
				.flatten()
				.compact()
				.value();
			if (_.isEmpty(pathsToBeListed)) {
				throw new NoSuchResourceError(`No such resource: ${sanitizedFullPath}`);
			} else {
				throw new NoSuchResourceError(`No such resource: ${sanitizedFullPath}\nPaths searched: \n` +
					_.join(pathsToBeListed, "\n"));
			}
		}

		return {
			physicalPath,
			loader,
		};
	}

	private calculatePhysicalPaths(sanitizedFullPath: string) {

		// We need to search not only fullPath, but also any where along fullPath but with a .meta 
		// folder inserted in the hierarchy.  We start with full path, then with .meta at the top, 
		// and work down from there.

		// First, generate all the paths we're going to look up against

		const pathParts = _.split(sanitizedFullPath, "/");
		const pathsToTest = [sanitizedFullPath, ..._.chain(pathParts)
			.drop() // drop first element so we don't test .meta//rest/of/path
			.map((_unused, index) => {
				return _.join([
					..._.slice(pathParts, 0, index + 1),
					metaFolder,
					..._.slice(pathParts, index + 1)], "/");
			})
			.reverse()
			.value()];

		return pathsToTest;
	}
}

export class NoSuchResourceError extends Error {
	constructor(msg: string) {
		super(msg);
	}
}

// Extends RawResourceLoader by associating it with a runtime so that it can be used to 
// load non-data resources

export class ResourceLoader extends RawResourceLoader {

	constructor(rawLoader: RawResourceLoader, private runtime: MetaCodeGlobalsFactory) {
		super(rawLoader);
	}

	public getResource(fullPath: string, resourceType: ResourceType) {
		return this.loadResource(sanitize(fullPath, resourceType), this.runtime);
	}
}

export function isSocMetadata(
	productsOrSOCResources: Product[] | MetaContentLocation[]): productsOrSOCResources is MetaContentLocation[] {
	return !_.isEmpty(productsOrSOCResources) && !((productsOrSOCResources[0] as any as Product).file);
}

function addExtensionIfNeeded(fullPath: string, resourceType: ResourceType) {
	if (resourceType === null) {
		return fullPath;
	} else {
		const extension = path.extname(fullPath);
		const validExtension = getBaseExtension(resourceType);
		if (extension && extension !== validExtension) {
			throw new Error(`${fullPath}: Invalid extension: The file should end with ${validExtension}`);
		}
		return _.endsWith(fullPath, validExtension) ? fullPath : `${fullPath}${extensionPrefix}${validExtension}`;
	}
}

export const enum ResourceType {
	CODE,
	DATA,
	TEMPLATE,
}

function sanitize(fullpath: string, resourceType: ResourceType) {
	return addExtensionIfNeeded(toFullPath(null, fullpath), resourceType);
}
