import * as _ from "lodash";
import { SCHEMA, validateMeta, parseMetaJSON } from "../JSONschemaValidator";
import { ProductFile, MinProductFile } from "./types";
import { MinProductFile as MinProductFileDef } from "public/defs";
import { fs } from "../fileSystem";

// Parse product file without schema validation, see MinProductFile
export function loadMinProductFile(filePath: string, fileSource: string): MinProductFile {

	const raw: MinProductFileDef = _.cloneDeep(parseMetaJSON(fileSource, filePath, SCHEMA.MinProductFile));

	return {
		path: filePath,
		raw,
	};
}

// Adapt to the internal product file interface
export function toProductFile(minProductFile: MinProductFile, isBuiltIn: boolean = false): ProductFile {
	const def = validateMeta(minProductFile.raw, minProductFile.path, SCHEMA.ProductFile);
	return {
		path: minProductFile.path,
		...def,
		isBuiltIn,
	};
}

export function loadProductFile(filePath: string): ProductFile {
	return toProductFile(loadMinProductFile(filePath, fs.readFile(filePath)));
}
