import * as _ from "lodash";
import { assumeError, assumeNoError } from "./choices";
import { glucoseBudget } from "./debug";
import { Device, Peripheral, Pin, GPIO } from "./requirements";
import * as data from "dataInterfaces";

export function init(deviceData: data.AdaptedDeviceInfo) {
	findRelatedPeripherals(deviceData);
}

let relationsMap: { [key: string]: string } = {};

function findRelatedPeripherals(deviceData: data.AdaptedDeviceInfo) {

	// Create a map of interface names to an array of what interfaces 
	// their peripherals support

	const relationsMapArray = _.mapValues(deviceData.interfaces, (iface) => {
		return _.uniq(_.flatten(_.map(iface.peripherals, (peripheral) => {
			return _.keys(peripheral.interfaces);
		})));
	});

	// If an interface relates to another, and that one relates to a 
	// third one, we want to make the first dependent on the third too.
	// To do this, we'll recursively search for this case and add it in
	// until we don't find any more.

	function findAdditional() {
		return !_.find(relationsMapArray, (iface, name) => {
			return !!_.find(iface, (relatedIface) => {
				const additional = _.difference(relationsMapArray[relatedIface], iface);
				if (!_.isEmpty(additional)) {
					relationsMapArray[name] = _.union(relationsMapArray[relatedIface], iface);
					return true;
				}
				return false;
			});
		});
	}
	while (!findAdditional()) { }

	// now just map the arrays into a unique string

	relationsMap = _.mapValues(relationsMapArray, (value) => {
		return _.sortBy(value).join("_");
	});
}

type SolveFun = () => boolean;
interface Assignment {
	peripheralName: string;
	pinName: string;
}
interface Assignments {
	[key: string]: Assignment;
}

// -----------------------------------------------------------------------------
// SavedSolution
// This encapsulates the valid and invalid requirements (both peripheral and 
// pin) in a given solution.  It allows a future solution to be compared with
// this one in order to determine what changed.  This allows errors to not be
// retried unnecessarily, but correctly retried if something previous valid is
// changed.
// -----------------------------------------------------------------------------

export class SavedSolution {

	public interfaces: { [key: string]: SavedInterfaceRequirement } = {};
	public assignments?: Assignments;
	private relatedInterfaces: { [key: string]: SavedInterfaceRequirement[] } = {};
	private restarts = glucoseBudget.restarts;

	constructor(deviceRequirements: Device, ignoreErrors: boolean);

	// Next constructor should really be private
	constructor(
		deviceRequirements: Device,
		ignoreErrors: boolean,
		ignoreSolutions: boolean,
		previousAssignments: Assignments);
	constructor(
		deviceRequirements: Device,
		ignoreErrors: boolean,
		ignoreSolutions?: boolean,
		previousAssignments?: Assignments) {

		if (!ignoreSolutions) {
			this.assignments = {};
		}

		if (deviceRequirements) {
			_.each(deviceRequirements.interfaceRequirementsMap, (interfaceReq, interfaceName) => {
				if (interfaceReq.requirements.length > 0) {
					interfaceName = relationsMap[interfaceName];
					this.relatedInterfaces[interfaceName] = this.relatedInterfaces[interfaceName] || [];
					_.each(interfaceReq.requirements, (req) => {
						if (req instanceof Peripheral) {
							if (!req.solution.errorText) {
								const peripheral = new SavedPeripheralRequirement(
									req, this, ignoreErrors, ignoreSolutions, previousAssignments);
								this.interfaces[peripheral.name] = peripheral;
								this.relatedInterfaces[interfaceName].push(peripheral);
							}
						} else {
							const gpio = new SavedGPIORequirement(req, this, ignoreErrors, ignoreSolutions, previousAssignments);
							this.interfaces[gpio.name] = gpio;
							this.relatedInterfaces[interfaceName].push(gpio);
						}
					});
				}
			});
		}
	}

	public compare(deviceRequirements: Device) {
		const newSolution = new SavedSolution(deviceRequirements, false, true, this.assignments);

		// Mark everything that was previously valid and hasn't changed as assigned

		let changedPreviouslyValidItem = false;
		_.each(this.interfaces, (origPeripheral, peripheral) => {
			if (!origPeripheral.isError) {
				const newPeripheral = newSolution.interfaces[peripheral];
				if (newPeripheral) {
					newPeripheral.isAssigned = true;
					_.each(origPeripheral.assignedPins.pins, (_obj, pin) => {
						const newPin = newPeripheral.unknownPins.pins[pin];
						if (newPin) {
							newPeripheral.assignedPins.pins[pin] = newPin;
							delete newPeripheral.unknownPins.pins[pin];
						} else {
							changedPreviouslyValidItem = true;
						}
					});
				} else {
					changedPreviouslyValidItem = true;
				}
			}
		});

		// If we removed/changed something that previously was valid, then we must re-check all errors
		// along with any new requirements

		if (!changedPreviouslyValidItem && this.restarts >= newSolution.restarts) {

			// Move everything that was invalid and hasn't changed to the known errors set.

			_.each(this.interfaces, (origPeripheral, peripheral) => {
				const newPeripheral = newSolution.interfaces[peripheral];
				if (newPeripheral) {
					if (origPeripheral.isError) {
						newPeripheral.isError = true;
					} else {
						_.each(origPeripheral.errorPins.pins, (_obj, pin) => {
							const newPin = newPeripheral.unknownPins.pins[pin];
							if (newPin) {
								newPeripheral.errorPins.pins[pin] = newPin;
								delete newPeripheral.unknownPins.pins[pin];
							}
						});
					}
				}
			});
		}

		return newSolution;
	}

	public findValidSolution(solve: SolveFun) {
		this.assumeUnassignedAreErrors();

		this.validateUnknowns(solve);
	}

	public assumeUnassignedAreErrors() {
		_.each(this.interfaces, (iFace) => {
			iFace.assumeUnassignedAreErrors();
		});
	}

	public validateUnknowns(solve: SolveFun) {

		// We want errors to be forced elsewhere when the user overrides something.
		// As such, we need to apply overrides and then apply other pins.  This is 
		// complicated by the fact that we're often assuming that pins solved for 
		// previously should be valid if nothing has changed.

		// So to start, try adding any new overrides and solving.  We do this at an
		// interface level because an override could likely change what peripheral 
		// is chosen, forcing significant errors on the other related peripherals, 
		// so we need to test them as a group.

		_.each(this.relatedInterfaces, (relatedPeripherals) => {
			// If there are any new overrides in this set of peripherals, include
			// them in the solution and solve

			const hasOverridesToTest = _.reduce<SavedInterfaceRequirement, boolean>(
				relatedPeripherals, (result, relatedPeripheral) => {
					return relatedPeripheral.assumeNoErrorsInOverrides() || result;
				}, false);
			if (hasOverridesToTest) {
				if (!solve()) {
					// We couldn't solve with the new overrides, but we can't mark 
					// them as errors just yet - another previously valid non-
					// overridden pin may be conflicting, and we want the 
					// overridden pins to be solved for first.

					// So, we'll mark all previously valid pins on these interfaces
					// as unknowns.  That will free up these requirements to choose
					// what peripheral/ioset they can use more freely.

					_.each(relatedPeripherals, (relatedPeripheral) => {
						relatedPeripheral.markNonOverridesPreviouslyAssigned();
					});

					// Next, since we're now changing previously valid pins, 
					// previous errors may now be valid.  As such, mark all 
					// previously invalid pins as unknowns

					_.each(this.interfaces, (iFace) => {
						iFace.markErrorsAsUnknown();
					});

					// Finally, validate overrides.  This will add the new 
					// overrides pin by pin and find corresponding errors

					_.each(relatedPeripherals, (relatedPeripheral) => {
						relatedPeripheral.validate(solve, OverrideType.Override, relatedPeripheral.unknownPins);
					});
				} else {
					// Solving succeeded without any special steps - mark all those
					// now valid pins as assigned

					_.each(relatedPeripherals, (relatedPeripheral) => {
						relatedPeripheral.markOverridesAssigned();
					});
				}
			}
		});

		// Now solve for all non-override pins that were previously valid

		_.each(this.interfaces, (iFace) => {
			iFace.validate(solve, OverrideType.Any, iFace.previouslyAssignedPins);
		});

		// Now solve for all non-override pins

		_.each(this.interfaces, (iFace) => {
			iFace.validate(solve, OverrideType.Any, iFace.unknownPins);
		});
	}
}

// -----------------------------------------------------------------------------
// SavedInterfaceRequirement
// This is a valid or invalid interface requirement from a solution.  It is 
// designed only to be used from within findValidSolution to exclude errors and
// validate new requirements, or to revalidate errors if a pre-existing 
// requirement is changed.  It contains functions that allow it to be included/ 
// excluded from a solution, to validate if including it leads to a valid 
// solution, and to write error information to the solution should it not be 
// valid.
// Operations on it apply to the underlying pin requirements, so that it can be
// operated on as a group
// -----------------------------------------------------------------------------

class SavedInterfaceRequirement {

	public errorPins = new PinCollection();
	public unknownPins = new PinCollection();
	public previouslyAssignedPins = new PinCollection();
	public assignedPins = new PinCollection();
	public isError: boolean;
	public isAssigned = false;

	constructor(
		public name: string,
		private id: string,
		isError: boolean,
		pinRequirements: Pin[],
		solution: SavedSolution,
		ignoreErrors: boolean,
		ignoreSolutions: boolean,
		previousAssignments: Assignments) {

		this.isError = !ignoreSolutions && isError;

		_.each(pinRequirements, (pinReq) => {
			if (pinReq.used) {
				const pin = new SavedPinRequirement(pinReq, solution, this.name, previousAssignments, id);

				if (ignoreSolutions) {
					this.unknownPins.pins[pin.name] = pin;
				} else if ("" === pinReq.solution.errorText) {
					this.assignedPins.pins[pin.name] = pin;
				} else if (!ignoreErrors) {
					this.errorPins.pins[pin.name] = pin;
				}
			}
		});
	}

	public hasAssignedPins() {
		return !_.isEmpty(this.assignedPins.pins);
	}

	public assumeUnassignedAreErrors() {
		if (!this.isAssigned) {
			assumeError(this.id);
		}

		this.errorPins.assumeError(OverrideType.Any);
		this.unknownPins.assumeError(OverrideType.Any);
	}

	public assumeNoErrorsInOverrides() {
		if (this.unknownPins.assumeNoError(OverrideType.Override) || this.isOverride()) {
			assumeNoError(this.id);
			return true;
		}
		return false;
	}

	public markNonOverridesPreviouslyAssigned() {
		this.assignedPins.assumeError(OverrideType.NonOverride);
		this.assignedPins.moveTo(this.previouslyAssignedPins, OverrideType.NonOverride);

		// If the peripheral was not overridden or not previously assigned,
		// and it has no assigned pins, then assume the peripheral (and any
		// pin overrides it has) are errors

		if ((!this.isOverride() || !this.isAssigned) && !this.hasAssignedPins()) {
			assumeError(this.id);

			this.unknownPins.assumeError(OverrideType.Override);

			this.isAssigned = false;
		}
	}

	public markErrorsAsUnknown() {
		this.isError = false;
		this.errorPins.moveTo(this.unknownPins, OverrideType.Any);
	}

	public markOverridesAssigned() {
		this.unknownPins.moveTo(this.assignedPins, OverrideType.Override);
	}

	public validate(solve: SolveFun, overrideType: OverrideType, unknownPins: PinCollection) {
		// Try with everything first - maybe there aren't any errors at all

		// If we aren't an error, and there's unknown pins to validate
		if ((!this.isError && unknownPins.assumeNoError(overrideType)) ||

			// or if we are an override and we're solving for overrides
			(overrideType === OverrideType.Override && this.isOverride()) ||

			// or if we've never been assigned (unassigned peripheral with no pins) 
			(!this.isAssigned && overrideType !== OverrideType.Override && unknownPins === this.unknownPins)) {

			assumeNoError(this.id);

			if (!solve()) {

				// Nope.  Assume everything's wrong (overrides or not) and add it back pin by pin

				unknownPins.assumeError(OverrideType.Any);
				if (this.hasAssignedPins() || solve()) {
					// Peripheral is good, validate each pin

					unknownPins.validate(this.assignedPins, this.errorPins, solve, overrideType);

				} else {

					// We couldn't even solve for just the peripheral

					assumeError(this.id);
					this.isError = true;
				}
			} else {
				// All these pins are valid

				unknownPins.moveTo(this.assignedPins, overrideType);
			}
		}
	}

	protected isOverride() {
		return false;
	}
}

// -----------------------------------------------------------------------------
// SavedPeripheralRequirement
// This is a SavedInterfaceRequirement for a peripheral requirement
// -----------------------------------------------------------------------------

class SavedPeripheralRequirement extends SavedInterfaceRequirement {

	private static generateName(peripheralReq: Peripheral) {
		return peripheralReq.id +
			peripheralReq.userOverride +
			peripheralReq.restrictTo +
			peripheralReq.canShareWith +
			peripheralReq.areConflictsAllowed();
	}

	constructor(
		private peripheralReq: Peripheral,
		solution: SavedSolution,
		ignoreErrors: boolean,
		ignoreSolutions: boolean,
		previousAssignments: Assignments) {
		super(
			SavedPeripheralRequirement.generateName(peripheralReq),
			peripheralReq.id,
			"" !== peripheralReq.solution.errorText,
			peripheralReq.pinRequirements,
			solution,
			ignoreErrors,
			ignoreSolutions,
			previousAssignments);
	}

	protected override isOverride() {
		return !!this.peripheralReq.userOverride;
	}
}

// -----------------------------------------------------------------------------
// SavedGPIORequirement
// This is a SavedInterfaceRequirement for a gpio requirement
// -----------------------------------------------------------------------------

class SavedGPIORequirement extends SavedInterfaceRequirement {

	constructor(
		gpioReq: GPIO,
		solution: SavedSolution,
		ignoreErrors: boolean,
		ignoreSolutions: boolean,
		previousAssignments: Assignments) {
		super(
			gpioReq.id,
			gpioReq.id,
			false,
			gpioReq.pinRequirements,
			solution,
			ignoreErrors,
			ignoreSolutions,
			previousAssignments);
	}
}

// -----------------------------------------------------------------------------
// PinCollection
// This is a collection of pins with some utility functions
// -----------------------------------------------------------------------------

const enum OverrideType {
	NonOverride,
	Override,
	Any,
}

class PinCollection {

	public pins: { [key: string]: SavedPinRequirement } = {};

	public assumeError(overrideType: OverrideType) {
		return this.forEach(overrideType, (pin) => {
			pin.assumeError();
		});
	}

	public assumeNoError(overrideType: OverrideType) {
		return this.forEach(overrideType, (pin) => {
			pin.assumeNoError();
		});
	}

	public moveTo(toCollection: PinCollection, overrideType: OverrideType) {
		return this.forEach(overrideType, (pin, pinName) => {
			delete this.pins[pinName];
			toCollection.pins[pinName] = pin;
		});
	}

	public validate(onSuccess: PinCollection, onFailure: PinCollection, solve: SolveFun, overrideType: OverrideType) {
		return this.forEach(overrideType, (pin, pinName) => {
			delete this.pins[pinName];
			if (pin.validate(solve)) {
				onSuccess.pins[pinName] = pin;
			} else {
				onFailure.pins[pinName] = pin;
			}
		});
	}

	private forEach(overrideType: OverrideType, func: (pin: SavedPinRequirement, name: string) => void) {

		let applied = false;
		_.each(this.pins, (pin, pinName) => {
			if (OverrideType.Any === overrideType || (OverrideType.Override === overrideType) === pin.isOverride()) {
				applied = true;
				func(pin, pinName);
			}
		});
		return applied;
	}
}

// -----------------------------------------------------------------------------
// SavedPinRequirement
// This is the same as SavedPeripheralRequirement, for for a pin requirement 
// only
// -----------------------------------------------------------------------------

class SavedPinRequirement {
	public name: string;
	private possibleConflict?: Assignment;
	private id: string;
	private userOverride: string;

	constructor(
		pinReq: Pin,
		private solution: SavedSolution,
		peripheralName: string,
		previousAssignments: Assignments,
		peripheralId: string) {

		this.userOverride = pinReq.userOverride;
		this.name = pinReq.getUnqualifiedName() +
			pinReq.userOverride +
			pinReq.restrictTo +
			pinReq.canShareWith +
			_.map(pinReq.interfacePins, (p) => p.name) +
			pinReq.areConflictsAllowed();
		if (solution.assignments && "" === pinReq.solution.errorText &&
			"" !== pinReq.solution.assignedToName) {
			solution.assignments[pinReq.solution.assignedToName] = {
				peripheralName,
				pinName: this.name,
			};
		}
		if (previousAssignments && this.isOverride()) {
			this.possibleConflict = previousAssignments[pinReq.userOverride];
		}

		this.id = peripheralId + "->" + pinReq.getUnqualifiedName();
	}

	public assumeError() {
		assumeError(this.id);
	}

	public assumeNoError() {
		assumeNoError(this.id);
	}

	public validate(solve: SolveFun) {
		this.assumeNoError();
		if (!solve()) {
			if (this.isOverride() && this.possibleConflict) {
				const conflictPeripheral = this.solution.interfaces[this.possibleConflict.peripheralName];
				if (conflictPeripheral) {
					const conflictPin = conflictPeripheral.assignedPins.pins[this.possibleConflict.pinName];
					if (conflictPin && !conflictPin.isOverride()) {
						conflictPin.assumeError();
						if (solve()) {
							// Note that kicking a previously valid pin out means 
							// we really should re-test error pins.  However, we 
							// can't get to here unless we failed a go-for-broke
							// override attempt earlier, and that should have 
							// already invalidated some pins to re-test and thus
							// moved errors to unknown.  See validateUnknowns and
							// markErrorsAsUnknown elsewhere

							conflictPeripheral.errorPins.pins[this.possibleConflict.pinName] = conflictPin;
							delete conflictPeripheral.assignedPins.pins[this.possibleConflict.pinName];
							return true;
						} else {
							conflictPin.assumeNoError();
						}
					}
				}
			}
			this.assumeError();
			return false;
		}
		return true;
	}

	public isOverride() {
		return !!this.userOverride;
	}
}
