import * as _ from "lodash";
import { Iterable } from "../clauseGeneration";
import { push, SolutionMap, pushError, pushAssumption, ApplyableChoice } from "../choices";

export interface IChoice extends ApplyableChoice {
	readonly id: number;
	name?: string;
	apply(solutionMap: SolutionMap): void;
}

export abstract class AbstractChoice implements IChoice {
	public readonly id: number;
	public name?: string;

	constructor() {
		this.id = push(this);
	}

	public abstract apply(solutionMap: SolutionMap): void;
}

export abstract class AbstractErrorChoice implements IChoice {
	public readonly restrictsGPIO: boolean;
	public readonly id: number;
	public name?: string;

	constructor(name: string, restrictsGPIO = false, assumeError = false) {
		this.restrictsGPIO = restrictsGPIO;
		this.id = pushError(this, name, assumeError);
	}

	public abstract apply(solutionMap: SolutionMap): void;
}

export abstract class AbstractAssumption implements IChoice {
	public readonly id: number;
	public name?: string;

	constructor(name: string) {
		this.id = pushAssumption(this, name);
	}

	public apply() {
		// Assumptions will rarely (if ever) need to apply anything
	}
}

// Map implementation for a number or string to some type
//
// The implemenation assumes that a number can be converted into a string for a 
// key arbitrarily, and relies on the functional interface to enforce typing
//
// It clearly won't work for K != number | string, but that's not possible to 
// assert on.  However, it would be picked up very quickly at runtime.

class ChoiceMap<K extends number | string, V> implements Iterable<K, V> {
	protected c: { [key: string]: V } = {};

	public forEach(callbackfn: (value: V, index: K) => void) {
		_.each(this.c, (v, k) => {
			(callbackfn as any)(v, k);
		});
	}
}

export class RelatedChoices<Key extends number | string, ChoiceType extends IChoice>
	extends ChoiceMap<Key, ChoiceType[]> {
	public get(key: Key) {
		return this.c[key as any as string] || (this.c[key as any as string] = []);
	}

	public addKey(key: Key) {
		this.get(key);
	}
}

export class PartiallyShared<ChoiceType extends AbstractChoice> {
	public readonly mutuallyExclusive: ChoiceType[] = [];
	public readonly shareable: { [key: string]: ChoiceType[] } = {};

	public push(choice: ChoiceType) {
		this.mutuallyExclusive.push(choice);
	}

	public pushShared(choice: ChoiceType, key: string) {
		const related = this.shareable[key] || (this.shareable[key] = []);
		related.push(choice);
	}
}

export class RelatedSharedChoices<Key extends number | string, ChoiceType extends IChoice>
	extends ChoiceMap<Key, PartiallyShared<ChoiceType>> {
	public get(key: Key) {
		return this.c[key as any as string] || (this.c[key as any as string] = new PartiallyShared<ChoiceType>());
	}
}
