import * as _ from "lodash";
import { Resource, Pin as PinResource } from "../solver/requirements";
import { EnumerationConfigurableMgr } from "./configurables/enumerationConfigurableMgr";
import { EnumerationConfigurable } from "public/defs";
import { InterfaceInstance, Pin } from "public/runtime";
import { AObjectMgr } from "./object";
import { createMemberValueSuggestedSolutionStatement } from "../scripting/serialize";
import { SetSource } from "./member";
import { FormattersMap } from "../formatting/formattersMap";
import { SerializationOptions } from "../scripting/toScript";
import { Const } from "../utils";
import { Validations } from "./validations";

/**
 * Manages the built-in $assign,  $assignAllowConflicts and $suggestSolution (which is assign like)
 */
abstract class AssignMgr<T extends InterfaceInstance | Pin> extends EnumerationConfigurableMgr<T> {

	private beingSet = false;

	public constructor(
		parent: AObjectMgr<T>,
		formattersMap: FormattersMap,
		configDef: EnumerationConfigurable,
	) {
		super(
			parent,
			formattersMap,
			configDef,
		);
	}

	public override getUIHash(_validations: Validations): string {
		// Return undefined to always refresh by default
		// This is safer, and we aren't likely to have many of these in a single view, other than pins.  And pins are
		// already covered in PinMemberMgr's version of this function

		return undefined;
	}

	// Since a write to $assign updates $assignAllowConflicts, and vice versa, we need to 
	// block infinite updates.  To do that, we'll indicate the value is equal if we're
	// already in the process of being written to.

	protected override isEqual(val: string) {
		return this.beingSet || (super.isEqual(val) && !this.updateNeeded(val));
	}

	// Called to indicate if an update is needed

	protected abstract updateNeeded(newValue: string): boolean;

	// Likewise, we'll set isBeingSet before doing the real update of the value.

	protected override onSet(newVal: string) {
		try {
			this.beingSet = true;
			this.update(newVal);
		} finally {
			this.beingSet = false;
		}
	}

	// Called with the new setting value to update

	protected abstract update(newValue: string): void;
}

/**
 * Manage $assign on a interface instance
 */
export class OverrideMgr<T extends InterfaceInstance | Pin,
	TParent extends AObjectMgr<T> = AObjectMgr<T>> extends AssignMgr<T> {

	public constructor(
		public override parentObjectMgr: TParent,
		formattersMap: FormattersMap,
		protected readonly solverReq: Resource,
		def: EnumerationConfigurable,
	) {
		super(
			parentObjectMgr,
			formattersMap,
			def,
		);
	}

	protected override shouldSerialize(options: SerializationOptions) {

		// Note that if $assignAllowConflicts is set, our value is updated as well to remain in
		// sync.  So, if we are set, and it wasn't because of $assignAllowConflicts, then we need
		// to serialize that value

		// In addition, if we are locking pinmux, we also want to serialize.  But again, only
		// if $assignAllowConflicts isn't set (ie already locked in a different way) and we
		// have a valid solution (can't assign an error to $assign)

		return (this.value !== Const.ANY && !this.solverReq.areConflictsAllowed()) ||
			(options.lockPinmux && !this.solverReq.areConflictsAllowed() && !_.isEmpty(this.solverReq.solution.assignedToName));
	}

	// If conflicts are allowed then an update is needed - any write to us clears
	// that setting

	protected updateNeeded() {
		return this.solverReq.areConflictsAllowed();
	}

	// Set $assignAllowConflicts to "Any" to clear the allow conflicts setting and
	// to keep that member in sync.  Then set the override in the solver requirement

	protected update(newVal: string) {
		this.parentObjectMgr.memberMgrs.$assignAllowConflicts.set(Const.ANY, SetSource.TOOL_INTERNAL);
		this.solverReq.userOverride = newVal === Const.ANY ? null : newVal;
	}
}

/**
 * Manage $assignAllowConflicts on a interface instance
 */
export class AllowConflictsMgr<T extends InterfaceInstance | Pin> extends AssignMgr<T> {

	public constructor(
		public override parentObjectMgr: AObjectMgr<T>,
		formattersMap: FormattersMap,
		private readonly solverReq: Resource,
		def: EnumerationConfigurable,
	) {
		super(
			parentObjectMgr,
			formattersMap,
			{
				...def,
				hidden: true,
				readOnly: false,
			},
		);
	}

	// If not allowing conflicts, then we can use $assign to serialize

	protected override shouldSerialize() {
		return this.solverReq.areConflictsAllowed();
	}

	// If conflicts are not allowed, and it's not being set to "Any", then an update is needed as 
	// a write to us will set that

	protected updateNeeded(val: string) {
		return (val !== Const.ANY) === this.solverReq.areConflictsAllowed();
	}

	// Set $assign to keep that member in sync, then mark the solver requirement as
	// allowing conflicts or not

	protected update(newVal: string) {
		this.parentObjectMgr.memberMgrs.$assign.set(newVal, SetSource.TOOL_INTERNAL);
		if (newVal === Const.ANY) {
			this.solverReq.disallowConflicts();
		} else {
			this.solverReq.allowConflicts(newVal);
		}
	}
}

/**
 * Manage $suggestSolution on a interface instance
 */
export class SuggestSolutionMgr<T extends InterfaceInstance | Pin, R extends Resource>
	extends AssignMgr<T> {

	public static optionSet = false;

	public static readonly errorTag = "<error>";
	public static readonly invalidTag = "<invalid>";

	private static addBuiltinOptions(def: EnumerationConfigurable) {
		const builtinOptions = [{ name: SuggestSolutionMgr.errorTag }, { name: SuggestSolutionMgr.invalidTag }];
		return _.extend({}, def, { options: [...builtinOptions, ...def.options] });
	}

	public constructor(
		public override parentObjectMgr: AObjectMgr<T>,
		formattersMap: FormattersMap,
		protected readonly solverReq: R,
		def: EnumerationConfigurable,
	) {
		super(
			parentObjectMgr,
			formattersMap,
			{
				...SuggestSolutionMgr.addBuiltinOptions(def),
				hidden: true,
				readOnly: false,
			},
		);
	}

	// uiState is frozen, so these functions do nothing

	public override resetDefaultUIState() {
	}

	// override from EnumerationConfigurableMgr

	public override generateScriptStatements(parentIdentifier: string, options: SerializationOptions) {
		return [
			createMemberValueSuggestedSolutionStatement(
				this.def, parentIdentifier, this.getRValueForScript(options), {}),
		];
	}

	// Should always treat as not user modified

	public override isUserModified() {
		return false;
	}

	protected getRValueForScript(_options: SerializationOptions) {
		return this.solverReq.solution.assignedToName || SuggestSolutionMgr.errorTag;
	}

	// We want to serialize, unless $assign (user-override) is being used
	// We don't want to serialize if we're migrating - either the user will lock prior to
	// migration, or they want to re-solve with the changed pinmux data

	protected override shouldSerialize(options: SerializationOptions) {
		const hasError = !_.isEmpty(this.solverReq.solution.errorText);
		const hasSolution = !_.isEmpty(this.solverReq.solution.assignedToName);
		const isOverridden = !_.isEmpty(this.solverReq.userOverride);
		const isMigration = options.deviceDataMigration;

		return !isMigration &&              // If they want to preserve the solution, they'll lock first
			!(isOverridden && !hasError) && // $assign will handle overrides, unless there's an error
			!(!hasSolution && !hasError);   // If we don't have a solution or error, we aren't used (multi-pin case)
	}

	// We don't update anything else, so we can safely say sure

	protected updateNeeded(_val: string) {
		return true;
	}

	// Set the solution object, unless the pin is marked unused

	protected update(newVal: string) {
		if (!(this.solverReq instanceof PinResource) || this.solverReq.used) {
			SuggestSolutionMgr.optionSet = true;
			if (newVal !== SuggestSolutionMgr.errorTag) {
				this.solverReq.solution.assignedToName = newVal;
			} else {
				this.solverReq.solution.errorText = "Resource conflict";
			}
		}
	}

	protected override transform(val: string) {
		if (SuggestSolutionMgr.errorTag === val) {
			return val;
		}

		const option = _.find(this.def.options, (o) => o.name === val);

		if (!option) {
			return SuggestSolutionMgr.invalidTag;
		}
		return val;
	}

	protected override validateValue() {
		return true;
	}
}
