import * as _ from "lodash";
import { SysConfig } from "./sysConfig";
import { ErrorStore } from "./errorStore";
import { ResolvedArgs } from "./args/argTypes";
import { getDeviceData } from "./data";
import { RawResourceLoader, isSocMetadata } from "./resources/metaContentLoaders/resourceLoader";
import { loadSocMetadata } from "./resources/metaContentLoaders/loaderFactory";
import { BoardParser } from "./boardSupport/boardParser";
import { initSettings } from "./settings";
import { UserPreference } from "./userPreferences";
import { supportsProjectMigration } from "./migration/migrate";
import { waitForGlucoseToInit } from "./solver/glucoseFunctions";

let currentCacheKey: string = null;
let cachedPromise: Promise<SysConfig> = null;

/**
 * Get a promise ( see http promise ) for a SysConfig object
 */
export function getSysConfig(
	errorStore: ErrorStore,
	resolvedArgs?: ResolvedArgs,
	createNew = false,
) {

	// If no ResolvedArgs are passed in, assume it's looking for the cached version
	// This is used by the global save, and determination of if props changed in LoadConfigPage
	// Make configParams non-optional to see what uses this

	if (!resolvedArgs) {
		return cachedPromise;
	}

	// If this is the same device, just return the same promise

	const { deviceId, partId, packageId } = resolvedArgs;
	const key = deviceId + partId + packageId;
	if (key === currentCacheKey && !createNew) {
		return cachedPromise;
	}

	// It's new - so update the key and re-create

	currentCacheKey = key;
	cachedPromise = getSysConfigImpl(resolvedArgs, errorStore);
	return cachedPromise;
}

async function getSysConfigImpl(resolvedArgs: ResolvedArgs, errorStore: ErrorStore) {

	// Parallelize the loading of independent external data:
	// 1) pinmux device data
	// 2) products or legacy templates
	// 3) settings

	const { deviceId, partId, packageId, loadSOCMetaData } = resolvedArgs;
	const [deviceData, { rawResourceLoader, products }, settings] = await Promise.all([
		getDeviceData(deviceId, partId, packageId, loadSOCMetaData),
		loadResources(resolvedArgs, deviceId),
		initSettings(),
	]);

	// Load and parse a board if requested (which must happen after we get the resource loader)

	const board = (resolvedArgs.boardId && resolvedArgs.boardId !== "undefined") ?
		decodeURIComponent(resolvedArgs.boardId) : null;
	if (board) {
		const parser = new BoardParser(rawResourceLoader, deviceData);
		await parser.loadBoard(board);
	}

	// Glucose has some async tasks that must complete before we call into it.
	// It starts that when imported, this is just to ensure it's done before we go further and perhaps use it.

	await waitForGlucoseToInit();

	// Create the runtimes

	return new SysConfig(
		resolvedArgs,
		deviceData,
		new UserPreference(settings, errorStore),
		rawResourceLoader,
		settings,
		products,
		getCurrentTargetDBDevice(),
	);
}

async function loadResources(resolvedArgs: ResolvedArgs, deviceId: string) {
	const productsOrSOCResources = resolvedArgs.loadSOCMetaData ? await loadSocMetadata(deviceId) : resolvedArgs.products;
	const rawResourceLoader = new RawResourceLoader(productsOrSOCResources);
	return {
		rawResourceLoader,
		products: isSocMetadata(productsOrSOCResources) ? null : productsOrSOCResources,
	};
}

export function clearSysConfigCache() {
	currentCacheKey = null;
	cachedPromise = null;
}

function getCurrentTargetDBDevice() {
	if (supportsProjectMigration()) {
		return window.eclipseGetCurrentTargetDBDevice();
	}
	return "";
}
