import * as _ from "lodash";
import { Requirements } from "./requirements";
import { ModuleInstanceRequirement, ModuleInstanceAdderRequirement } from "public/defs";
import { isModuleInstanceAdderRequirement } from "../funcs";
import { SetSource, InstanceArgType } from "../member";
import { ModuleInstanceAdderMemberMgr } from "../moduleMemberMgrs/moduleInstanceAdderMemberMgr";
import { ModuleInstanceMgrFactory } from "../moduleInstance";
import { ModuleInstanceMemberMgr } from "../moduleMemberMgrs/moduleInstanceMemberMgr";
import { ModuleInstanceAdderMgr } from "../moduleInstanceAdderMgr";
import { validateInstanceCreateAllowed } from "../../validateAdd";
import { InstanceAdderLengthLegacyMemberMgr } from "../instanceAdderLegacyCompatibility";
import { assignmentToString } from "../../niceExceptions";
import { adaptNonStaticModuleReqs, compareInstanceReqs } from "../moduleArgs";

export class ModuleInstanceRequirements extends Requirements<"moduleInstances"> {

	protected adaptReqs(reqs: ModuleInstanceRequirement[]) {
		return adaptNonStaticModuleReqs(reqs);
	}

	protected categorizeReqs(reqs: ModuleInstanceRequirement[]) {
		return compareInstanceReqs(
			this.currentRequirements,
			reqs,
			this.instanceMgr.getModuleMgr().module.recreateOnArgsChange,
		);
	}

	protected resolve(newReqs: ModuleInstanceRequirement[], updatedReqs: ModuleInstanceRequirement[], reason?: SetSource) {
		_.each(
			newReqs,
			(req) => {
				if (isModuleInstanceAdderRequirement(req)) {
					return this.resolveModuleInstanceAdderReq(req);
				} else {
					return this.resolveModuleInstanceReq(req);
				}
			});
		// We should refresh the required args from the parent chain if we are a child re-resolving grand children
		// independently from a parent resolution
		// Don't refresh args if the req change is not caused by an user assign to prevent self looping
		if (reason === SetSource.USER_ASSIGN) {
			this.instanceMgr.reApplyParentArgs();
		}

		this.resolveUpdates(updatedReqs);
	}

	protected getFunctionName(): "moduleInstances" {
		return "moduleInstances";
	}

	private resolveUpdates(reqs: ModuleInstanceRequirement[]) {
		_.each(
			reqs,
			(req) => {
				const currentMemberMgr = this.instanceMgr.memberMgrs[req.name];
				if (isModuleInstanceAdderRequirement(req)) {
					(currentMemberMgr as ModuleInstanceAdderMemberMgr).updateArgs(req);
				} else {
					(currentMemberMgr as ModuleInstanceMemberMgr).updateArgs(req);
				}
				return currentMemberMgr;
			});
	}

	private resolveModuleInstanceAdderReq(req: ModuleInstanceAdderRequirement) {
		const adderMemberMgr = new ModuleInstanceAdderMemberMgr(
			this.instanceMgr,
			this.runtime.getFormattersMap(),
			req,
			this.runtime,
			(parentArrayMgr: ModuleInstanceAdderMgr, index: number) => {
				const mod = parentArrayMgr.getModuleMgr().module;
				validateInstanceCreateAllowed(mod);
				const instMgr
					= ModuleInstanceMgrFactory.createInstance(
						this.runtime,
						mod,
						false,
						{
							parent: this.instanceMgr,
							parentArrayMgr,
						},
					);
				const requiredArgs = _.size(parentArrayMgr.def.fixedRequiredArgs) > index ?
					parentArrayMgr.def.fixedRequiredArgs[index] : parentArrayMgr.def.requiredArgs;
				instMgr.setValueFromRequiredArgs(requiredArgs, this.instanceMgr);
				// only set fixedArgs for the first n instances(the length of fixedArgs)
				const args = _.size(parentArrayMgr.def.fixedArgs) > index ?
					parentArrayMgr.def.fixedArgs[index] : parentArrayMgr.def.args;
				instMgr.setValueFromArgs(args, InstanceArgType.META);
				return instMgr;
			},
		);
		// This is a hack to support scripts of modules that migrated
		// from a basic config+dynamic child instance pattern
		// to using instance adder pattern.
		// The instance adder is introduced in CCS 9.3.
		// This piece of code can be removed if we believe there are no longer
		// any usable scripts that have not yet migrated.
		if (req.legacyMigrationOptions && this.validateLegacyMigrationOptions(req)) {
			const { lengthConfigName, instanceNameMapping } = req.legacyMigrationOptions;
			if (this.instanceMgr.memberMgrs[lengthConfigName]) {
				this.instanceMgr.removeMember(this.instanceMgr.memberMgrs[lengthConfigName]);
			}
			return new InstanceAdderLengthLegacyMemberMgr(
				this.instanceMgr,
				this.runtime.getFormattersMap(),
				lengthConfigName,
				req.defaultInstanceCount || 0,
				adderMemberMgr.getAdder(),
				instanceNameMapping,
			);
		}
		return adderMemberMgr;
	}

	private validateLegacyMigrationOptions(req: ModuleInstanceAdderRequirement) {
		const { lengthConfigName, instanceNameMapping } = req.legacyMigrationOptions;
		if (
			this.instanceMgr.memberMgrs[lengthConfigName] &&
			!(this.instanceMgr.memberMgrs[lengthConfigName] instanceof InstanceAdderLengthLegacyMemberMgr)
		) {
			throw new Error(
				`${assignmentToString(
					lengthConfigName,
				)} cannot be used as lengthConfigName because a member of the same name exists.`,
			);
		}
		if (_.isArray(instanceNameMapping)) {
			if (!_.isEqual(_.uniq(instanceNameMapping), instanceNameMapping)) {
				throw new Error(
					"instanceNameMapping cannot have duplicate values.",
				);
			}
			if (instanceNameMapping.length !== req.maxInstanceCount) {
				throw new Error(
					"The number of elements in instanceNameMapping must equal maxInstanceCount.",
				);
			}
		}

		return true;
	}

	private resolveModuleInstanceReq(req: ModuleInstanceRequirement) {
		const { module } = this.runtime.loadModule(req.moduleName);
		validateInstanceCreateAllowed(module);
		const instMgr = ModuleInstanceMgrFactory.createInstance(
			this.runtime,
			module,
			false,
			{
				parent: this.instanceMgr,
			},
		);

		const collapsed = !!req.hidden || (_.isUndefined(req.collapsed) ? instMgr.isTopModule() : req.collapsed);
		return new ModuleInstanceMemberMgr(this.runtime, instMgr, req, this.instanceMgr, collapsed);
	}
}
