import * as _ from "lodash";
// ------------------------------------------------------------------------------------------------
// Clauses
// A "clause" in this domain is a boolean algebra expression that must be true that consists only 
// of boolean literals, NOTs of those literals, and ORs.  Since all must be true, they can be 
// thought of as all be ANDed together in one super expression.  The SAT solver (glucose) is then
// responsible for solving such that all clauses are true.
//
// This file is an abstraction for adding clauses to a raw array in memory for glucose to later 
// read.  Literals in the clause are added as 32 bit integers to that memory.  NOTs of a literal 
// are signified using a negative value of the literal.  The clauses are ended with a zero, because
// literals can never be zero - this is what separates the clauses in memory.
// ------------------------------------------------------------------------------------------------

import { initializeClauses, glucoseModule } from "./glucoseFunctions";
import { numChoices, generateHeaderComments, numAssumptions } from "./choices";
import { textBasedClauses, profileGlucose, debugSolution, log } from "./debug";

// Buffer address in memory, it's current size, and the offset into it where we are writing 
// literals to

let buf = 0;
let size = 0;
let offset = 0;

// A 32 bit type view into that buffer

let typedArray: Int32Array = null;

// Total number of clauses written

let numClauses = 0;

// A text representation of clauses for debugging only

let textClauses = "";

// The current value of the clause based on a known solution.  Used for debugging
let clauseValue = false;

export function reset() {
	offset = 0;
	numClauses = 0;
}

export function apply() {
	if (textBasedClauses) {
		let text = generateHeaderComments();

		text += "p cnf " + numChoices() + " " + (numClauses + numAssumptions()) + "\n";
		text += textClauses;
		textClauses = "";

		if (console.clear) {
			console.clear();
		}
		log(text);
	}

	if (profileGlucose) {
		log("Applying: " + numChoices() + " choices, " + numClauses + " clauses");
	}

	initializeClauses(numChoices(), numClauses, buf);
}

export function addLiteral(lit: number) {
	if (offset === size) {
		// Enlarge buffer

		size = (size === 0) ? 256 : Math.floor(size * 3 / 2);

		buf = glucoseModule._realloc(buf, size * 4);
		// eslint-disable-next-line no-bitwise
		typedArray = glucoseModule.HEAP32.subarray(buf >> 2, (buf >> 2) + size * 4);
	}

	// Write literal to buffer

	typedArray[offset++] = lit;

	if (textBasedClauses) {
		textClauses += lit + " ";
		if (!_.isEmpty(debugSolution) && lit !== 0) {
			lit = parseInt(lit.toString(), 10);
			const trueLit = _.includes(debugSolution, lit > 0 ? lit : -lit);
			clauseValue = clauseValue || ((lit > 0) ? trueLit : !trueLit);
		}
	}
}

export function endClause(comments: string) {
	// 0 signifies the end of the clause

	++numClauses;
	addLiteral(0);
	if (textBasedClauses) {
		textClauses += "c " + comments + "\n";
		if (!_.isEmpty(debugSolution)) {
			if (clauseValue) {
				textClauses = _.chain(textClauses)
					.split("\n")
					.dropRight(2)
					.join("\n")
					.value() + "\n";
				clauseValue = false;
			}
		}
	}
}
