import { AdaptedDeviceInfo, DeviceDescription, PartDescription } from "dataInterfaces";
import { getToolVersion } from "./toolVersion";
import * as _ from "lodash";

// create a data-less device
function createDataLessDevice(deviceId: string) {

	const adaptedDeviceInfo: AdaptedDeviceInfo = {
		versions: {
			tool: getToolVersion(),
		},
		showIOSets: false,
		showPreferredVoltage: false,
		devicePins: {},
		peripherals: {},
		peripheralPins: {},
		packageDescription: {
			type: "None",
			numRows: 0,
			numColumns: 0,
		},
		interfaces: {},
		powerDomains: {},
		templates: {
			fileListArray: [],
		},
		showExtendedPinTypes: false,
		rowColumnInverted: false,
		deviceId,
		device: deviceId,
		part: deviceId,
		package: deviceId,
		gpio: {
			isOptimizable: false,
			pinInfo: {},
		},
		cores: [],
	};

	const packageDescription: Discovery.PackageDescription = {
		id: deviceId,
		name: deviceId,
		description: "",
		packageID: deviceId,
	};

	const partDescription: PartDescription = {
		packageDescriptions: [packageDescription],
		name: deviceId,
		description: "",
		partID: deviceId,
		targetDBDevices: [],
	};

	const deviceDescription: DeviceDescription = {
		name: deviceId,
		family: deviceId,
		description: deviceId,
		package: [packageDescription],
		part: [partDescription],
		legacyNames: [],
		builtInProduct: false,
		hasClocktree: false,
		cores: [],
	};

	return { adaptedDeviceInfo, deviceDescription, packageDescription, partDescription };
}

// map data less device into an object keyed by ids.
function toMapById(devices: ReturnType<typeof createDataLessDevice>[]) {
	return (_.keyBy(devices, (d) => d.adaptedDeviceInfo.deviceId));
}

// Image only devices are special devices with no pinmux data
// they are needed to support CCXX image configuration/generation (ImageCreator)
const imageOnlyDevicesArr = [
	createDataLessDevice("CC3120R"),
	createDataLessDevice("CC3130R"),
	createDataLessDevice("CC3135R"),
];

const imageOnlyDevices = toMapById(imageOnlyDevicesArr);

export function isImageOnlyDevice(deviceId: string) {
	return !!imageOnlyDevices[deviceId];
}

// Id for other device, part, package
export const builtInDevices = toMapById([
	createDataLessDevice("Other"),
	...imageOnlyDevicesArr,
]);

export function isDataLessDevice(deviceId: string) {
	return !!builtInDevices[deviceId];
}
