import { storage, syscfgWorkspace } from "./storage";
import * as _ from "lodash";
import * as path from "path";
import { fsUtils } from "./fsutil";
import { isUnderTest, isCloud } from "./platform";
import { parseJSON } from "./utils";

const MAX_RECENT = 10;

interface SettingsFileContent {
	recentProjects: string[];
	userPreferences: { [key: string]: any };
}

// due to legacy reasons, older files may not have some of the members defined
type LoadedSettingsFileContent = Partial<SettingsFileContent>;

export class Settings {

	protected content: SettingsFileContent;
	public constructor(
		private settingsPath: string,
	) {
	}

	public async init() {
		if (!this.content) {
			let loadedResponse: LoadedSettingsFileContent;
			try {
				loadedResponse = await this.loadSettings();
			} catch (e) {
				// ignore - not critical
			}

			if (!loadedResponse) {
				loadedResponse = {};
			}

			const { userPreferences, recentProjects } = loadedResponse;
			const settings = {
				// legacy settings files may not have user prefs defined
				userPreferences: userPreferences || {},
				// older cloud workspaces don't have settings file, so they will not have
				// recentProjects defined
				recentProjects: recentProjects || [],
			};
			this.content = settings;
		}
	}

	public addRecent(filePath: string) {
		const newRecentProjects = _.take(_.uniq([filePath, ...this.content.recentProjects]), MAX_RECENT);
		this.content.recentProjects = newRecentProjects;
		return this.stringifyAndSave();
	}

	public clearRecentProjects() {
		this.content.recentProjects = [];
		return this.stringifyAndSave();
	}

	public removeProject(file: string) {
		_.remove(this.content.recentProjects, (f) => f === file);
		return this.stringifyAndSave();
	}

	public getRecentProjects() {
		return this.content.recentProjects;
	}

	public setUserPreference<T>(name: string, value: T) {
		this.content.userPreferences[name] = value;
		return this.stringifyAndSave();
	}

	public getUserPreference<T>(name: string) {
		return this.content.userPreferences[name] as T;
	}

	protected async saveSettings(settingsJSON: string) {
		return storage.saveFile(this.settingsPath, settingsJSON);
	}

	// write the Properties object to json
	private async stringifyAndSave() {
		const settingsJSON = JSON.stringify(this.content);
		return this.saveSettings(settingsJSON);
	}

	private async loadSettings() {
		const data = (await storage.openFile(this.settingsPath)).data;
		return parseJSON<LoadedSettingsFileContent>(data);
	}
}

class TestSettings extends Settings {
	public override async init() {
		if (!this.content) {
			this.content = { userPreferences: {}, recentProjects: [] };
		}
	}

	protected override async saveSettings(_settingsJSON: string) {
		return { path: "testSettings.json" };
	}
}

async function create() {

	const dir = isCloud() ? syscfgWorkspace : fsUtils.getAppDataDir();
	const settingsPath = path.join(dir, "pinmux.json");

	const settings = isUnderTest() ? new TestSettings("testSettings.json") : new Settings(settingsPath);
	await settings.init();
	return settings;
}

export const initSettings = _.memoize(create);

// get settings immediately (on file load) if running in the cloud (ignore errors - that will be fetched later)
// We don't want to do this in the cli case as we likely won't use it and getAppDataDir accesses the file system

if (isCloud()) {
	initSettings().catch(() => { });
}

