import { ConfigurableGroup, InstanceUIState, Module, AnyConfigurable } from "public/defs";
import { isConfigurableGroup } from "../objectManagers/configGroups";
import { ModuleInstance } from "public/runtime";

type ISearchable = Module | ConfigurableGroup;

export function showGroupConfig(
	groupname: string, inst: ModuleInstance, ui: InstanceUIState): void {
	hideGroupConfigInternal(groupname, inst, ui, false);
}

export function hideGroupConfig(
	groupname: string, inst: ModuleInstance, ui: InstanceUIState): void {
	hideGroupConfigInternal(groupname, inst, ui, true);
}

function hideGroupConfigInternal(
	groupname: string, inst: ModuleInstance, ui: InstanceUIState, toHide: boolean): void {
	const group = findGroup(groupname, inst.$module);
	if (group) {
		hideGroup(group.config, ui, toHide);
	} else {
		throw new Error("No group called " + groupname + "found");
	}
}

function findGroup(groupname: string, searchable: ISearchable): ConfigurableGroup | void {
	for (const c of searchable.config) {
		if (isConfigurableGroup(c)) {
			if (c.name && c.name === groupname) {
				return c;
			} else {
				const found = findGroup(groupname, c);
				if (found) {
					return found;
				}
			}
		}
	}
}

function hideGroup(
	config: (AnyConfigurable | ConfigurableGroup)[], ui: InstanceUIState, toHide: boolean) {
	for (const c of config) {
		if (isConfigurableGroup(c)) {
			hideGroup(c.config, ui, toHide);
		} else if (c.name) {
			ui[c.name].hidden = toHide;
		}
	}
}
