import * as _ from "lodash";
import {
	Module,
	ModuleInstanceAdderRequirement,
} from "public/defs";
import { validateJSONschema, SCHEMA, SCHEMAToType } from "../JSONschemaValidator";
import { isGPIOInterfaceRequirement, isModuleInstanceAdderRequirement } from "./funcs";

export type DynamicReqFunction =
	keyof Pick<Module, "pinmuxRequirements" | "sharedModuleInstances" | "moduleInstances" | "modules">;

export type FunctionToType<FunctionName extends DynamicReqFunction> = ReturnType<Module[FunctionName]>[0];

export function validateReqs<T extends DynamicReqFunction>(
	reqs: FunctionToType<T>[],
	functionName: T,
	isGPIOOptimizable: boolean,
) {
	if (!_.isArray(reqs)) {
		throw new Error("non-array returned");
	}
	switch (functionName) {
		case "pinmuxRequirements":
			_.each(reqs as FunctionToType<"pinmuxRequirements">[], (req) => {
				if (!("extend" in req)) {
					const schema = isGPIOInterfaceRequirement(req, isGPIOOptimizable)
						? SCHEMA.GPIOInterfaceRequirement : SCHEMA.InterfaceRequirement;
					validateReq(req, schema);
				} else {
					validateReq(req, SCHEMA.InterfaceExtensionRequirement);
				}
			});
			break;

		case "sharedModuleInstances":
			validateAll(reqs as FunctionToType<"sharedModuleInstances">[], SCHEMA.SharedModuleInstanceRequirement);
			break;

		case "moduleInstances":

			const instReqs = reqs as FunctionToType<"moduleInstances">[];
			const [moduleInstanceAdderReqs, moduleInstanceReqs] =
				_.partition(instReqs, (r) => isModuleInstanceAdderRequirement(r));
			validateAll(moduleInstanceReqs, SCHEMA.ModuleInstanceRequirement);
			validateAll(moduleInstanceAdderReqs as ModuleInstanceAdderRequirement[], SCHEMA.ModuleInstanceAdderRequirement);
			break;

		case "modules":
			validateAll(reqs as FunctionToType<"modules">[], SCHEMA.ModuleRequirement);
			break;

		default:
	}
}

function validateAll<T extends SCHEMA>(
	reqs: SCHEMAToType<T>[],
	schema: T) {
	_.each(reqs, (req) => {
		validateReq(req, schema);
	});
}

function validateReq<T extends SCHEMA>(
	req: SCHEMAToType<T>,
	schema: T) {
	const error = validateJSONschema(schema, req);
	if (error !== null) {
		throw new Error(`invalid object returned: ${error}`);
	}
}
