import * as _ from "lodash";
// Functionality related to multi pin

import * as data from "dataInterfaces";
import { EnumerationConfigurableMgr } from "./configurables/enumerationConfigurableMgr";
import { AMemberMgr, SetSource } from "./member";
import { AObjectMgr } from "./object";
import { PinMgr } from "./pin";
import { PinMemberMgr } from "./pinObjectMembers";
import { EnumerationConfigurable as EnumerationConfigurableDef, EnumerationOption } from "public/defs";
import { MultiPin } from "public/runtime";
import { SelectionFilterGroup } from "./selectionFilterGroup";
import { clearSolution } from "../utils";
import { filterHiddenPinMembers } from "./funcs";
import { InterfaceInstanceMgr } from "./interfaceInstance";
import { FormattersMap } from "../formatting/formattersMap";
import { format } from "../formatting/multiPinFormatter";
import { Runtime } from "../resources/runtime";
import { Pin } from "../solver/requirements";
import { Validations } from "./validations";

const numPinsConfigurableName: keyof MultiPin = "$numPins";

/**
 * Manages multi pin requirement and related configuration object. Used only
 * in core pinmux.
 */
export class MultiPinMgr extends AObjectMgr<MultiPin> {

	private selectAll: boolean = true;
	private readonly pins: PinMemberMgr[] = []; // member mgr for pin members	
	private solverReqs: Pin[] = [];
	private readonly numPins: EnumerationConfigurableMgr<MultiPin, number>;
	private tooFewUsedPins = false;
	private readonly formattersMap: FormattersMap;

	constructor(
		runtime: Runtime,
		private readonly peripheralFilter: SelectionFilterGroup,
		private readonly pinSet: data.UseCasePinSet,
		private readonly parentMgr: InterfaceInstanceMgr,
		private readonly reserved: boolean = false,
	) {

		super(runtime, (options, member) => format(this.parentMgr, options, member));
		this.formattersMap = runtime.getFormattersMap();

		this.updateSolverReqs(this.pinSet.minCount);
		this.pins = this.createPinMemberMgrs();

		this.numPins =
			new EnumerationConfigurableMgr(
				this,
				this.formattersMap,
				this.createNumPinsConfigurableDef(),
			);

		this.addFixedMember(this.formattersMap, "$useCasePinSet", pinSet);
	}

	public override getContainingInstanceMgrs() {
		return this.parentMgr.getContainingInstanceMgrs();
	}

	public override getContainingTreeNodes() {
		return this.parentMgr.getContainingTreeNodes();
	}

	public modifiedInUI() {
		// Intentionally blank - core pinmux components are ALWAYS user created
	}

	public override onMemberChanged(mem: AMemberMgr<any>) {
		if (mem === this.numPins) {
			this.updateSolverReqs(Number(mem.getValue()));
		}
	}

	public getSolverRequirement() {

		// Get the list of interface pins to consider for each multi-pin requirement
		// This is the list of used (checked) underlying pins that aren't overridden

		const interfacePinNames = _.chain(this.pins)
			.filter((pin) => pin.valueObjectMgr.getUsed() && !pin.valueObjectMgr.getSolverRequirement().userOverride)
			.map((pin) => _.first(pin.valueObjectMgr.getSolverRequirement().interfacePins))
			.value();

		const overriddenPinCount = _.chain(this.pins)
			.filter((pin) => pin.valueObjectMgr.getUsed() && !!pin.valueObjectMgr.getSolverRequirement().userOverride)
			.size()
			.value();

		// If there aren't enough choices, return nothing and just mark an error

		this.tooFewUsedPins = (interfacePinNames.length + overriddenPinCount) < this.solverReqs.length;
		if (this.tooFewUsedPins) {
			return [];
		}

		// Set that list for every one of the multi-pin requirements

		_.each(this.solverReqs, (req) => {
			req.interfacePins = interfacePinNames;
		});

		// Check for overrides

		_.each(this.solverReqs, (req) => { req.userOverride = null; });
		let index = 0;
		_.each(this.pins, (pin) => {
			const req = pin.valueObjectMgr.getSolverRequirement();
			if (pin.valueObjectMgr.getUsed() &&
				req.userOverride &&
				this.solverReqs[index]) {

				this.solverReqs[index].userOverride = req.userOverride;
				this.solverReqs[index].interfacePins = req.interfacePins;

				// Copy over the error if the suggested solution is an error

				_.assign(this.solverReqs[index].solution, req.solution);
				++index;
			}
		});

		// Check for suggested solutions 

		_.each(this.pins, (pin) => {
			const req = pin.valueObjectMgr.getSolverRequirement();
			if (pin.valueObjectMgr.getUsed() &&
				!req.userOverride &&
				this.solverReqs[index] &&
				req.solution.assignedToName) {

				_.assign(this.solverReqs[index].solution, req.solution);
				++index;
			}
		});

		// Mark suggested solution errors for non-overrides
		// There may be more errors than we have requirements for, but we we'll copy those over 
		// below in solveComplete()

		_.each(this.pins, (pin) => {
			if (this.solverReqs[index] &&
				pin.valueObjectMgr.getUsed() &&
				pin.valueObjectMgr.getSolution().errorText &&
				!pin.valueObjectMgr.getSolverRequirement().userOverride) {

				_.assign(this.solverReqs[index].solution, pin.valueObjectMgr.getSolution());
				++index;
			}
		});

		return this.solverReqs;
	}

	public solveComplete() {

		// Clear existing solutions

		_.each(this.pins, (pin) => {
			clearSolution(pin.valueObjectMgr.getSolverRequirement().solution);
		});

		if (!this.tooFewUsedPins) {

			// Where solutions were found, find the corresponding pin that matches the
			// solved for interface pin, and assign that solution to it

			let errors: string[] = [];
			_.each(this.solverReqs, (req) => {
				if (req.solution.assignedToName) {
					const solution = this.findAssociatedPin(req).valueObjectMgr.getSolverRequirement().solution;
					solution.assignedToName = req.solution.assignedToName;
					solution.assignedPeripheralPin = req.solution.assignedPeripheralPin;
					solution.assignedInterfacePin = req.solution.assignedInterfacePin;
					solution.warningText = req.solution.warningText;
					solution.warningDetailsText = req.solution.warningDetailsText;
				} else {
					errors = errors.concat(req.solution.errorDetailsText);
				}
			});

			// For errors, determine which ball choice the error was for, and apply it to the used pins
			// without solutions if that ball is one of their valid mappings

			if (errors.length) {
				_.each(this.pins, (pin) => {
					const sol = pin.valueObjectMgr.getSolverRequirement().solution;
					if (!sol.assignedToName && pin.valueObjectMgr.getUsed()) {
						const mappings = _.map(pin.valueObjectMgr.getOverrideMember().getDevicePins(),
							(devicePin) => this.formattersMap.getEncodingTag(devicePin));
						sol.errorDetailsText = _.filter(errors, (e) => {
							const ball = _.split(e, " ")[0];
							return -1 !== _.indexOf(mappings, ball);
						});
						if (!_.isEmpty(sol.errorDetailsText)) {
							sol.errorText = "Resource conflict";
						}
					}
				});
			}
		}

		_.each(this.pins, (pin) => {
			pin.valueObjectMgr.solveComplete();
		});
	}

	public getSelectAll() {
		return this.selectAll;
	}

	public setCount(value: number) {
		this.memberMgrs.$numPins.set(value, SetSource.USER_ASSIGN);
	}

	public getSelectedOption() {
		const enumOption: EnumerationOption<number> = {
			name: this.managedObject.$numPins,
		};
		return enumOption;
	}

	public setSelectAll(value: boolean) {
		this.selectAll = value;
		_.each(this.pins, (pinInst) => {
			pinInst.valueObjectMgr.setUsed(value, SetSource.USER_ASSIGN);
		});
	}

	public getPinMemberMgrs() {
		return _.filter(this.pins, (pin) => pin.def.name in this.memberMgrs);
	}

	public getVisiblePinMgrs() {
		return filterHiddenPinMembers(this.pins);
	}

	public getNumOfPinsOptions() {
		return this.numPins.def.options;
	}

	public override validate(validations: Validations): void {
		_.each(this.pins, (p) => p.valueObjectMgr.validate(validations));
	}

	public applySolverValidation() {
		if (this.tooFewUsedPins) {
			this.runtime.getValidations().logError("Not enough pins enabled", this);
		}
		_.each(this.pins, (p) => p.valueObjectMgr.applySolverValidation(p));
	}

	protected override preRemove() {
		this.updateSolverReqs(0); // clean up
	}

	private updateSolverReqs(count: number) {

		// We have one multi-pin requirement for each underlying pin

		if (count > _.size(this.solverReqs)) {

			// count increased, add more pins

			while (count > _.size(this.solverReqs)) {
				const pin = new Pin(this.solverReqs.length.toString(), [], undefined, this.reserved);
				this.formattersMap.set(pin, (options) => {

					const userPin = this.findAssociatedPin(pin);

					// If not found, then we're likely formatting to print out solver debug info
					// so just use the name of the generated multi-interface requirement

					const member = userPin ? userPin.def.name : pin.getUnqualifiedName();
					return format(this.parentMgr, options, member);
				});
				this.solverReqs.push(pin);
			}
		} else {

			// Count decreased, drop the extra pins

			while (count < _.size(this.solverReqs)) {
				const pin = this.solverReqs.pop();
				this.formattersMap.delete(pin);
			}
		}
	}

	private findAssociatedPin(solverReq: Pin) {

		const assignedTo = solverReq.solution.assignedInterfacePin;
		if (assignedTo) {
			return _.find(this.pins, (p) => _.first(p.valueObjectMgr.getSolverRequirement().interfacePins).name === assignedTo);
		} else {

			// Technically, it maps to every pin that has an error, but we'll just pick the first one.
			// Under normal use, this will never happen (you would never refer to a solver req that doesn't use anything),
			// but the test harness may try to format it to indicate "hey - this didn't solve!??!?"

			return _.find(this.pins, (p) => !!p.valueObjectMgr.getSolverRequirement().solution.errorText);
		}
	}

	private createPinMemberMgrs() {

		return _.map(this.pinSet.useCasePins, (uc) => {

			const pin = new PinMgr(
				this.runtime,
				(options) => format(this.parentMgr, options, uc.name),
				uc.name,
				this.peripheralFilter,
				uc,
				null,
				{},
				this,
			);

			const pinMemberMgr = new PinMemberMgr(
				pin,
				this.formattersMap,
				{
					name: uc.name,
				},
				this,
			);
			return pinMemberMgr;
		});
	}

	private createNumPinsConfigurableDef(): EnumerationConfigurableDef<number> {
		const pinSet = this.pinSet;

		// We don't want to allow hidden pins to be part of the multi-pin solution
		// These are likely pins that can't be pinned out

		const maxCount = _.chain(this.pins)
			.filter((pin) => !pin.uiState.hidden)
			.size()
			.value();

		// Create an option for each count value

		const options = _.times(maxCount - pinSet.minCount + 1, (i) => {
			const index = i + pinSet.minCount;
			return {
				name: index,
			};
		});

		return {
			name: numPinsConfigurableName,
			displayName: "Number of pins",
			options,
			default: pinSet.defaultCount,
		};
	}
}
