import * as _ from "lodash";
import type {
	ITreeNodeStatus,
	ITreeNode,
} from "../../components/TreeNode";
import { TreeNodeStatusType } from "../treeNodeStatusType";

import { ModuleMgr } from "./module";
import { HardwareComponent, SourceLocation } from "public/runtime";
import { HardwareMgr } from "../objectManagers/hardwareMgr";
import { TreeNodeStatus } from "./treeStatus";
import { IButtonInfo, TreeButtonIcons, IButtonMenuChoice } from "./button";
import { getDisplayName } from "../utils";
import { ModuleInstanceMgr } from "../objectManagers/moduleInstance";
import { NodeSelection } from "./nodeSelection";
import { SelectionInNode } from "../objectManagers/ui/selection";
import { Tab } from "../tabs";
import { Validations, ValidationSummary } from "../objectManagers/validations";
import { ButtonDisplay } from "../treeNodeButtonDisplay";

// Takes a hardware component list and creates tree entries from it
export class HardwareComponentMgr implements ITreeNode {

	private readonly subComponents: HardwareComponentMgr[];
	private readonly attachButtonInfo: AttachSoftwareButtonInfo;
	private readonly detachButtonInfo: DetachSoftwareButtonInfo;
	private readonly treeNodeStatus: TreeNodeStatus;
	private readonly supportedModules: ModuleMgr[];
	private readonly parentComponent: HardwareComponentMgr;
	private expanded = true;
	private userShowLongDescPref = false;
	private nodeSelection: NodeSelection<ModuleInstanceMgr>;
	private nodePath: string[];

	constructor(
		private readonly hwComponent: HardwareComponent,
		private readonly hardwareMgr: HardwareMgr,
		private readonly isSubComponent: boolean,
		private readonly parentNode: ITreeNode,
	) {

		this.supportedModules = this.hardwareMgr.getSupportModules(this.hwComponent);
		this.treeNodeStatus = new TreeNodeStatus(TreeNodeStatusType.BADGE, this.getID() + "Icon");
		this.attachButtonInfo = new AttachSoftwareButtonInfo(this, this.isSubComponent, this.getID + "AddButton");
		this.detachButtonInfo = new DetachSoftwareButtonInfo(this, this.isSubComponent, this.getID + "RemoveButton");
		this.parentComponent = parentNode instanceof HardwareComponentMgr ? parentNode : null;
		this.nodePath = parentNode ? [...parentNode.getNodePath(), this.getID()] : [this.getID()];
		this.subComponents = _.map(this.hwComponent.subComponents, (sub) => {
			return new HardwareComponentMgr(sub, this.hardwareMgr, true, this);
		});
		this.nodeSelection = new NodeSelection(() => this.getInstances());
		this.hardwareMgr.setTreeNode(this.hwComponent, this);
	}

	public getUIHash(): string {

		// There's never a lot of hardware components, so indicating we always need to refresh shouldn't cause a slowdown

		return undefined;
	}

	public getParentNode() {
		return this.parentNode;
	}

	public getParentTab(): Tab {
		return null;
	}

	public getInstances() {
		return this.hardwareMgr.getAddedListItems(this.hwComponent);
	}

	public getHwComponent() {
		return this.hwComponent;
	}

	public getID() {
		return this.hwComponent.name.replace(/\s+/g, "");
	}

	public getDisplayName(displayScriptName: boolean) {
		return getDisplayName(this.hwComponent, displayScriptName);
	}

	public getAttachButtonInfo(): AttachSoftwareButtonInfo {
		return this.attachButtonInfo;
	}

	public getDetachButtonInfo(): DetachSoftwareButtonInfo {
		return this.detachButtonInfo;
	}

	public getChildren(): HardwareComponentMgr[] {
		return this.subComponents;
	}

	public getParentSource(): SourceLocation {
		if (this.isSubComponent) {
			return this.parentComponent.getParentSource();
		} else {
			return this.getHwComponent().source;
		}

	}

	public isTitle() {
		return false;
	}

	public getTooltip() {
		return this.hwComponent.description;
	}

	public getStatus(validations: Validations): ITreeNodeStatus[] {
		const addedModules = (!_.isEmpty(this.hardwareMgr.getAddedListItems(this.hwComponent)));
		const summary = validations.getSummary(this);
		const error = summary === ValidationSummary.Error;
		const warning = summary === ValidationSummary.Warning;
		const success = !error && !warning && addedModules;
		this.treeNodeStatus.setStatus({ error, warning, success });
		return [this.treeNodeStatus];
	}

	public isExpanded() {
		return this.expanded;
	}

	public toggleExpanded() {
		this.expanded = !this.expanded;
	}

	public isDisabled() {
		return false;
	}

	public isDetached() {
		return _.isEmpty(this.getInstances());
	}

	public getSupportedModules() {
		return this.supportedModules;
	}

	public showButton() {
		return _.isEmpty(this.supportedModules) ? ButtonDisplay.Hide : ButtonDisplay.Show;
	}

	public getSelectedMyListItem() {
		return this.nodeSelection.getSelectedMyListItem();
	}

	public setShowUserLongDescPref(status: boolean) {
		this.userShowLongDescPref = status;
	}

	public getShowUserLongDescPref() {
		return this.userShowLongDescPref;
	}

	public getLongDescription() {
		return this.getHwComponent().longDescription || "";
	}

	public getAlwaysShowUserLongDesc() {
		return false;
	}

	public getSelection() {
		return this.nodeSelection.getSelection();
	}

	public setSelection(selection: SelectionInNode) {
		this.nodeSelection.setSelection(selection);
	}

	public getNodePath() {
		return this.nodePath;
	}

	public getUsedPins() {
		const selectedItem = this.getSelectedMyListItem();
		return selectedItem ? selectedItem.getUsedPins() : new Set<string>();
	}

	public getRuntimeSelection() {
		return this.getSelectedMyListItem()?.managedObject;
	}
}

class AttachSoftwareButtonInfo implements IButtonInfo {

	private readonly softwareChoices: SoftwareChoice[] = null;
	private readonly numSoftwareChoices: number;
	private readonly toolTip: string;
	private readonly text: string;
	private readonly icon: TreeButtonIcons;

	constructor(
		private readonly hwComponentMgr: HardwareComponentMgr,
		private readonly isSubComponent: boolean,
		private readonly id: string,
	) {
		const supportedModules = hwComponentMgr.getSupportedModules();
		this.softwareChoices = _.map(hwComponentMgr.getSupportedModules(), (moduleMgr) => {
			return new SoftwareChoice(moduleMgr);
		});
		this.numSoftwareChoices = _.size(this.softwareChoices);
		if (this.numSoftwareChoices > 1) {
			this.toolTip = "Select Software to Use";
			this.text = "Use Software";
			this.icon = TreeButtonIcons.ADD_WITH_CHOICE;
		} else {
			this.toolTip = this.numSoftwareChoices === 1 ?
				`Use  ${supportedModules[0].getDisplayName(false)} (TI Drivers)` : "";
			this.text = "Use Software";
			this.icon = this.isSubComponent ? TreeButtonIcons.ADD_SUB : TreeButtonIcons.ADD;
		}
	}

	public getText() {
		return this.text;
	}

	public getID() {
		return this.id;
	}

	public getTooltip() {
		return this.toolTip;
	}

	public getMenuChoices() {
		return this.softwareChoices;
	}

	public isDisabled() {

		if (this.numSoftwareChoices === 0) {
			return true;
		}

		if (this.numSoftwareChoices === 1) {
			return this.softwareChoices[0].isDisabled();
		}

		return false;
	}

	public getIcon(): TreeButtonIcons {
		return this.icon;
	}

	public show(): boolean {
		return this.hwComponentMgr.isDetached();
	}
}

class DetachSoftwareButtonInfo implements IButtonInfo {

	constructor(
		private readonly hwComponentMgr: HardwareComponentMgr,
		private readonly isSubComponent: boolean,
		private readonly id: string,
	) {
	}

	public getID(): string {
		return this.id;
	}

	public getText(): string {
		return "Remove Software";
	}

	public getIcon(): TreeButtonIcons {
		return this.isSubComponent ? TreeButtonIcons.REMOVE_SUB : TreeButtonIcons.REMOVE;
	}

	public getTooltip(): string {
		return "Remove all attached Software";
	}

	public getMenuChoices(): SoftwareChoice[] {
		return [];
	}

	public show(): boolean {
		return !this.hwComponentMgr.isDetached();
	}

	public isDisabled(): boolean {
		return !_.every(this.hwComponentMgr.getInstances(), (i) => i.isRemovable());
	}
}

export class SoftwareChoice implements IButtonMenuChoice {

	constructor(
		private readonly moduleMgr: ModuleMgr) {
	}

	public getText(displayScriptName: boolean) {
		return this.moduleMgr.getDisplayName(displayScriptName);
	}

	public isDisabled() {
		// can't add any more instances of this module
		return this.moduleMgr.getMaxAllowed() <= this.moduleMgr.getNumberOfUsed();
	}

	public getModuleMgr() {
		return this.moduleMgr;
	}
}
