import * as _ from "lodash";
import { assertUnreachable, assertUnreachableNoThrow } from "../utils";
import { CompilerType } from "public/runtime";
import { ThemeType } from "../../components/styles/themes";
import { ArgTypes, ParsedArgs, ArgsError, OptionLongName, ScriptArgTypes, argsDef, IArgDef } from "./argTypes";

/**
 * Take an argv array and map by long name, performing a necessary validation and applying default values.
 * @param argv arguments
 * @param expectScript is a target script argument expected
 * @throws ArgError - Reports issues with provided args
 * @returns And object containing
 *  - Map of long names to an object holding the value and original name (short or long)
 *  - SysConfig script file name, if provided as the last parameter.
 */
export function parseArgs(argv: string[], expectScript: boolean) {
	argv = _.cloneDeep(argv);
	const parsedArgs: ParsedArgs = {
		script: [{}],
	};

	try {
		while (!_.isEmpty(argv)) {

			// Extract the next argument in the array, and try to decode what option is specifies

			const currentArg = argv.shift();
			const selectedOption = toLongName(currentArg);
			if (!selectedOption) {
				handleUnknownArgument(currentArg, argv, expectScript, parsedArgs);
				return { parsedArgs };
			}

			// Boolean options are global (not per-script), and have no value component (true if seen)

			else if (isBooleanOption(selectedOption)) {
				parsedArgs[selectedOption] = {
					value: true,
					userArgName: currentArg,
				};
			} else {

				// Extract the value of the specified option, and ensure it's not another argument

				const value = argv.shift();
				if ((isOption(value))) {
					throw new ArgsError(`Missing value following argument ${currentArg}`);
				}

				// Does the option apply to just the script or globally?
				// Determine and then extract the option as appropriate

				if (isPerScriptOption(selectedOption)) {
					handlePerScriptOption(selectedOption, value, currentArg);
				} else if (selectedOption === "script") {
					handleScriptOption(value);
				} else {
					handleGlobalOption(selectedOption, value, currentArg);
				}
			}
		}
	} catch (e) {
		if (e instanceof ArgsError) {
			return { parsedArgs, argsError: e };
		}
		throw e;
	}

	return { parsedArgs };

	function handlePerScriptOption(selectedOption: keyof ScriptArgTypes, value: string, currentArg: string) {

		// Options specific to a script must be added to the array entry under "script"
		// for the specific script they are associated with.  Since we build it up in 
		// order, the last element is the script entry this option is associated with.

		const currentPerScriptArgs = _.last(parsedArgs.script);

		// Find the type of this argument, and add it's entry to the script-specific args

		if (isStringArrayOption(selectedOption)) {
			const existing = currentPerScriptArgs[selectedOption] || [];
			currentPerScriptArgs[selectedOption] = [
				...existing,
				{
					value,
					userArgName: currentArg,
				}];
		} else if (isStringOption(selectedOption)) {
			if (currentPerScriptArgs[selectedOption]) {
				throw new ArgsError(`Argument declared multiple times without an additional --script: '${value}`);
			}

			currentPerScriptArgs[selectedOption] = {
				value,
				userArgName: currentArg,
			};
		} else {
			assertUnreachable(selectedOption);
		}
	}

	function handleScriptOption(value: string) {

		// A --script indicates that this is a new script, so we must create a new array 
		// entry under "script" and add it there.  However, we pre-add one for the legacy
		// way of specifying the script at the end, so if that exists and is empty, they're
		// mixing the old and new way of defining the script entry.

		const script = { value, userArgName: "--script" };
		const scriptArgs = _.last(parsedArgs.script);
		if (_.isEmpty(scriptArgs)) {
			scriptArgs.script = script;
		} else if (!scriptArgs.script) {
			throw new ArgsError("--script declared after script-specific arguments");
		} else {
			parsedArgs.script.push({ script });
		}
	}

	function handleGlobalOption(
		selectedOption: keyof (Omit<ParsedArgs, "script" | BooleanOptionLongName>), value: string, currentArg: string) {

		// It's a global option other than "script".  Determine it's type and add it and 
		// it's value to parsedArgs

		if (isStringArrayOption(selectedOption)) {
			const existing = parsedArgs[selectedOption] || [];
			parsedArgs[selectedOption] = [
				...existing,
				{
					value,
					userArgName: currentArg,
				}];
		} else {
			const existing = parsedArgs[selectedOption];
			if (existing) {
				throw new ArgsError(`Argument declared multiple times: '${value}`);
			}

			if (isStringOption(selectedOption)) {
				parsedArgs[selectedOption] = {
					value,
					userArgName: currentArg,
				};
			} else if (isCompilerOption(selectedOption)) {
				if (!isCompilerType(value)) {
					throw new ArgsError(`Invalid compiler value '${value}'`);
				}
				parsedArgs[selectedOption] = {
					value,
					userArgName: currentArg,
				};
			} else if (isThemeOption(selectedOption)) {
				if (!isThemeType(value)) {
					throw new ArgsError(`Invalid theme value '${value}'`);
				}
				parsedArgs[selectedOption] = {
					value,
					userArgName: currentArg,
				};
			} else {
				assertUnreachable(selectedOption);
			}
		}
	}
}

function isOption(argument: string) {
	return _.startsWith(argument, "-");
}

function toLongName(argument: string) {
	if (_.startsWith(argument, "--")) {
		const candidateLongName = _.trimStart(argument, "-");
		return candidateLongName in argsDef ? candidateLongName as OptionLongName : null;
	} else if (_.startsWith(argument, "-")) {
		return shortNameToLongName[_.trimStart(argument, "-")];
	}
	return null;
}

function handleUnknownArgument(currentArg: string, argv: string[], expectScript: boolean, parsedArgs: ParsedArgs) {
	if (expectScript && !isOption(currentArg)) {
		if (_.size(parsedArgs.script) !== 1) {
			throw new ArgsError(`Unrecognized argument: ${currentArg}`);
		}
		const scriptArgs = _.last(parsedArgs.script);
		scriptArgs.script = {
			value: currentArg,
			userArgName: "--script",
		};
		if (!_.isEmpty(argv)) {
			scriptArgs.scriptArgs = {
				value: argv.join(" "),
				userArgName: "--scriptArgs",
			};
		}
	} else {
		throw new ArgsError(`Unrecognized argument: ${currentArg}`);
	}
}

type Action<T extends OptionLongName> = (argDef: IArgDef<ArgTypes[T]>, longName: T) => void;
function eachArgsDef<T extends OptionLongName>(action: Action<T>) {
	_.each(argsDef, (argDef, key) => {
		action(argDef as IArgDef<ArgTypes[T]>, key as T);
	});
}

const shortNameToLongName: { [shortName: string]: OptionLongName } = {};
eachArgsDef((c, longName) => {
	if (c.shortName) {
		shortNameToLongName[c.shortName] = longName;
	}
});

// see conditional types 
// https://www.typescriptlang.org/docs/handbook/advanced-types.html
// we can use this to group and pull out particular types of options in a way where the type system
// ensures we don't miss a type

type PickKeysByType<T, T2> = { [K in keyof T]: T[K] extends T2 ? K : never }[keyof T];
type BooleanOptionLongName = PickKeysByType<ArgTypes, boolean>;
type StringOptionLongName = Exclude<PickKeysByType<ArgTypes, string>, SpecialStringOptionLongName>;
type StringArrayOptionLongName = PickKeysByType<ArgTypes, string[]>;
type SpecialStringOptionLongName = CompilerOptionLongName | ThemeOptionLongName;
type CompilerOptionLongName = "compiler";
type ThemeOptionLongName = "theme";

function wrongType(_x: never) { return false; }

function isPerScriptOption(v: string): v is keyof ScriptArgTypes {
	const cv = v as keyof ScriptArgTypes;
	switch (cv) {
		case "output":
		case "context":
		case "scriptArgs":
		case "dependentScript":
			return true;
		default:
			return wrongType(cv);
	}
}

function isBooleanOption(v: string): v is BooleanOptionLongName {
	const cv = v as BooleanOptionLongName;
	switch (cv) {
		case "treatWarningsAsErrors":
		case "listGeneratedFiles":
		case "listReferencedFiles":
		case "ccxxImageMode":
		case "showAllContexts":
		case "showSaveIcons":
		case "quiet":
			return true;
		default:
			return wrongType(cv);
	}
}

function isStringOption(v: string): v is StringOptionLongName {
	const cv = v as StringOptionLongName;
	switch (cv) {
		case "board":
		case "device":
		case "package":
		case "part":
		case "output":
		case "context":
		case "script":
		case "scriptArgs":
		case "ipcf":
		case "rtos":
			return true;
		default:
			return wrongType(cv);
	}
}

function isStringArrayOption(v: string): v is StringArrayOptionLongName {
	const cv = v as StringArrayOptionLongName;
	switch (cv) {
		case "product":
		case "dependentScript":
			return true;
		default:
			return wrongType(cv);
	}
}

function isCompilerOption(v: string): v is CompilerOptionLongName {
	const cv = v as "compiler";
	return cv === "compiler" || wrongType(cv);
}

function isThemeOption(v: string): v is ThemeOptionLongName {
	const cv = v as "theme";
	return cv === "theme" || wrongType(cv);
}

function isCompilerType(compilerType: string): compilerType is CompilerType {
	const casted = compilerType as CompilerType;
	switch (casted) {
		case "ccs":
		case "gcc":
		case "iar":
		case "ticlang":
		case "keil":
			return true;
		default:
			assertUnreachableNoThrow(casted); // Type check that we didn't miss a case
			return false;
	}
}

function isThemeType(themeType: string): themeType is ThemeType {
	const casted = themeType as ThemeType;
	switch (casted) {
		case ThemeType.LIGHT:
		case ThemeType.DARK:
			return true;
		default:
			assertUnreachableNoThrow(casted); // Type check that we didn't miss a case
			return false;
	}
}

const defaults = _.chain(argsDef)
	.mapValues((value, name) => isBooleanOption(name) ? false : value.default)
	.omitBy((value) => _.isUndefined(value))
	.mapValues((value, userArgName) => ({ value, userArgName }))
	.value();
const globalDefaults = _.omitBy(defaults, (_v, key) => isPerScriptOption(key));
const scriptDefaults = _.omitBy(defaults, (_v, key) => !isPerScriptOption(key));

export function applyDefaults<T>(parsedArgs: ParsedArgs<T>): ParsedArgs<T> {
	return {
		...globalDefaults,
		...parsedArgs,
		script: _.map(parsedArgs.script, (scriptArgs) => ({
			...scriptDefaults,
			...scriptArgs,
		})),
	};
}
