import * as _ from "lodash";
import { AdaptedDeviceInfo, DevicePin, PeripheralPin, InterfacePin } from "dataInterfaces";
import { Header, HeaderPin, HardwareComponent } from "public/runtime";

export const enum PinType {
	FREE, 			// mapped out pins, or header pins if on a board, not necessarily muxable
	COMPONENT, 		// pins wired to a component.  (nothing is of this type if not using a board)
	VIRTUAL,		// DMA channels etc
	UNEXPORTED,		// pins that aren't wired out anywhere
}

interface HeaderInfo {
	header: Header;
	headerPin: HeaderPin;
}

export interface MapEntry {
	type: PinType;
	headerInfo?: HeaderInfo[];
	component?: HardwareComponent;
	preferredTypes?: string[];
}

export class PinMap {

	private readonly theMap: { [devicePinName: string]: MapEntry };
	private readonly hasPinPrefs: boolean;
	private readonly board: boolean;

	constructor(
		deviceData: AdaptedDeviceInfo,
	) {
		// Start off mapping all pins as either free or virtual.
		// If this is a board, mark them unmapped or virtual - we'll mark the free ones next

		const defaultPinType = deviceData.board ? PinType.UNEXPORTED : PinType.FREE;
		this.theMap = _.mapValues(deviceData.devicePins,
			(pin) => ({ type: "Virtual" === pin.devicePinType ? PinType.VIRTUAL : defaultPinType }));

		this.board = !!deviceData.board;
		this.hasPinPrefs = false;
		if (this.board) {
			// Mark all header pins as free, and store the preferred type

			_.chain(deviceData.board.headers)
				.sortBy((header) => header.default) // look at default headers first, so they're first in headerInfo
				.each((header) => {
					_.each(header.pins, (headerPin) => {
						if (headerPin.ball) {

							// If a pin is mapped to two header pins, use the intersection of all non-empty preferences

							let { preferredTypes } = this.theMap[headerPin.ball];
							if (!_.isEmpty(headerPin.preferredType)) {
								preferredTypes = _.isEmpty(preferredTypes) ? headerPin.preferredType :
									_.intersection(preferredTypes, headerPin.preferredType);
							}

							// Keep track of all header pins associated with this device pin, not just the first

							const headerInfo: HeaderInfo[] = _.get(this.theMap, [headerPin.ball, "headerInfo"], []);
							this.theMap[headerPin.ball] = {
								type: PinType.FREE,
								headerInfo: [...headerInfo, { header, headerPin }],
								preferredTypes,
							};
						}
					});
				})
				.value();

			// Mark all component pins as such, and link to their component

			_.each(_.flatMap(deviceData.board.components, gatherComponents), (component) => {
				_.each(component.signals, (signal) => {
					if (signal.devicePin) {
						this.theMap[signal.devicePin.name] = {
							...this.theMap[signal.devicePin.name], // pull in header/headerPin
							type: PinType.COMPONENT,
							component,
							preferredTypes: undefined, // remove preferredTypes (it's whatever the hardware is connected to)
						};
					}
				});
			});

			this.hasPinPrefs = _.some(this.theMap, (entry) => !_.isEmpty(entry.preferredTypes));
		}
	}

	public forEachMapping(
		interfacePins: InterfacePin[] | { [key: string]: InterfacePin },
		type: PinType | null,
		callback: (devicePin: DevicePin, peripheralPin: PeripheralPin, info: MapEntry) => void,
		includeUnmappable = false) {

		// cast to an array as lodash types don't realize that array | map are both possible for _.each

		_.each(interfacePins as InterfacePin[], (interfacePin) => {
			_.each(interfacePin.pinMappings, (peripheralPin) => {
				const devicePinFound = _.chain(peripheralPin.pinMappings)
					.filter((devicePin) =>
						type === null ||
						type === this.get(devicePin).type ||
						PinType.VIRTUAL === this.get(devicePin).type)
					.each((devicePin) =>
						callback(devicePin, peripheralPin, this.get(devicePin)))
					.isEmpty()
					.value();

				if (includeUnmappable && !devicePinFound) {
					callback(null, peripheralPin, null);
				}
			});
		});
	}

	public get(devicePin: DevicePin) {
		return this.theMap[devicePin.name];
	}

	public getFreePins() {
		return _.filter(_.keys(this.theMap), (name) => PinType.FREE === this.theMap[name].type);
	}

	public pinPreferencesAvailable() {
		return this.hasPinPrefs;
	}

	public isBoard() {
		return this.board;
	}
}

function gatherComponents(component: HardwareComponent): HardwareComponent[] {
	return ([
		component,
		..._.flatMap(component.subComponents, gatherComponents),
	]);
}
