import { AMemberMgr } from "../member";
import { ModuleInstance, ModuleInstanceArray } from "public/runtime";
import {
	ContainerNode,
	ViewNode,
	createUIStatements,
	ValidationLeafNode,
	LeafNode,
	MatchedPathRetType,
} from "../viewNodes";
import { ModuleInstanceAdderMgr, instanceAdderProxyHandler } from "../moduleInstanceAdderMgr";
import { FormattersMap } from "../../formatting/formattersMap";
import { ModuleInstanceMgr } from "../moduleInstance";
import { Runtime } from "../../resources/runtime";
import { SerializationOptions } from "../../scripting/toScript";
import { createModuleInstanceArrayCreateStatement, createChildIdentifier } from "../../scripting/serialize";
import * as _ from "lodash";
import { ModuleInstanceAdderRequirement, InstanceArgs } from "public/defs";
import { Validations } from "../validations";

// This class manages the ModuleInstanceAdder with respect to the parent instance mgr.
// Since it extends AMemberMgr, it could be thought of as similar to a ConfigurableMgr.
// It's actual value is the ModuleInstanceAdder redirected through a Proxy handler.
// Also, this class is responsible for the implementation of the container node that is
// present in the UI.
export class ModuleInstanceAdderMemberMgr
	extends AMemberMgr<ModuleInstance[], ModuleInstance, ModuleInstanceAdderRequirement>
	implements ContainerNode {
	public readonly type = "container";
	public valueObjectMgr: ModuleInstanceAdderMgr;
	private collapsed: boolean;
	private readonly defaultCollapsedState: boolean;
	private showLongDescription = false;
	private validationNode: ValidationLeafNode;
	constructor(
		parentObjectMgr: ModuleInstanceMgr<ModuleInstance>,
		formattersMap: FormattersMap,
		public override readonly def: ModuleInstanceAdderRequirement,
		private readonly runtime: Runtime,
		instanceCreator: (adderMgr: ModuleInstanceAdderMgr, index: number) => ModuleInstanceMgr,
	) {
		super(parentObjectMgr, formattersMap, def, []);
		this.valueObjectMgr =
			new ModuleInstanceAdderMgr(
				def,
				runtime,
				instanceCreator,
			);
		this.valueObjectMgr.create(this.getDefaultInstanceCount());
		const collapsed = !(def.collapsed === false);
		this.collapsed = collapsed;
		this.defaultCollapsedState = collapsed;
		this.validationNode = new ValidationLeafNode(this, this.runtime.getValidations());
	}

	public override getUIHash(_validations: Validations): string {

		// return undefined for the same reason as ObjectMemberManager

		return undefined;
	}

	public getValidationsummary(validations: Validations) {
		return validations.getSummary(this.valueObjectMgr);
	}

	public getKey() {
		return this.valueObjectMgr.getName();
	}

	public getNumColumns() {
		return 1;
	}

	public isHidden() {
		return false;
	}

	public getChildren(): ViewNode[] {
		return [this.validationNode, this.valueObjectMgr];
	}

	public getHeading(displayScriptName?: boolean) {
		return this.valueObjectMgr.getDisplayName(displayScriptName);
	}

	public getTitleNode(): LeafNode {
		return null;
	}

	public getLongDescription() {
		return this.def.longDescription;
	}

	public getSecondaryHeading() {
		return this.def.description;
	}

	public isCollapsed() {
		return this.collapsed;
	}

	public setCollapsed(val: boolean) {
		this.collapsed = val;
	}

	public getDefaultCollapsedState() {
		return this.defaultCollapsedState;
	}

	public isLongDescriptionVisible() {
		return this.showLongDescription;
	}

	public setLongDescriptionVisibility(val: boolean) {
		this.showLongDescription = val;
	}

	public isReadOnly() {
		return !!this.def.readOnly;
	}

	public updateArgs(newReq: ModuleInstanceAdderRequirement) {

		this.valueObjectMgr.updateArgs(newReq, this.parentObjectMgr);

		this.def.requiredArgs = newReq.requiredArgs;
		this.def.args = newReq.args;
	}

	public matchSubItemPath(itemPath: string[]): MatchedPathRetType {
		// This container node is not in the item hierarchy so it gets bypassed
		// and pass on the itemPath to the actual adderMgr.
		const matched = _.some(this.getChildren(), (c) => {
			const [childMatched] = c.matchSubItemPath(itemPath);
			return childMatched;
		});
		return [matched, itemPath];
	}

	public override remove() {
		this.valueObjectMgr.destroyAll();
	}

	public override get() {
		return new Proxy(this.valueObjectMgr, instanceAdderProxyHandler) as any as ModuleInstanceArray;
	}

	public override set() {
		throw Error("Cannot set to an instance adder, use create() instead");
	}

	public setValueFromRequiredArgs() {
		this.set();
	}

	public setValueFromArgs() {
		this.set();
	}

	public removeArgs(args: InstanceArgs) {
		this.valueObjectMgr.removeArgs(args);
	}

	public removeReqArgs(args: InstanceArgs, origin: ModuleInstanceMgr) {
		this.valueObjectMgr.removeReqArgs(args, origin);
	}

	public generateScriptStatements(parentIdentifier: string, options: SerializationOptions) {
		let statements =
			this.valueObjectMgr.generateScriptStatements(createChildIdentifier(parentIdentifier, this.def.name), options);

		if (this.valueObjectMgr.getNumberOfUsed() !== this.getDefaultInstanceCount()) {
			statements = [
				createModuleInstanceArrayCreateStatement(
					this.def,
					parentIdentifier,
					this.valueObjectMgr.getNumberOfUsed(),
				),
				...statements,
			];
		}

		if (options.includeUIState) {
			statements = [
				...statements,
				...createUIStatements(parentIdentifier, this),
			];
		}
		return statements;
	}

	public override isUserModified() {
		return _.some(this.valueObjectMgr.instances, (i) => i.isUserModified()) ||
			// We might have a default of n and remove m from default without modifying any members
			this.valueObjectMgr.getNumberOfUsed() !== this.getDefaultInstanceCount();
	}

	public getAdder() {
		return this.valueObjectMgr;
	}

	protected override shouldSerialize(): boolean {
		return true; // Always need to serialize $name on underlying children
	}

	private getDefaultInstanceCount() {
		return this.def.defaultInstanceCount || this.def.minInstanceCount || 0;
	}
}
