import { contextifyMetaCode, MetaCodeLoader } from "../contextify";
import { IMetaContentLoader } from "./resourceLoader";
import { Product } from "../../product/types";
import * as _ from "lodash";
import * as path from "path";

// This class loads resources out of a bundle who's source is passed into the 
// constructor

export class BundleLoader implements IMetaContentLoader {

	private readonly resources: { [key: string]: MetaCodeLoader } = {};
	constructor(bundle: string, private readonly product: Product) {
		// eslint-disable-next-line no-new-func
		const defineResources = new Function("defineResource", bundle);
		defineResources((resourceName: string, factory: MetaCodeLoader) => {
			this.resources[resourceName] = factory;
		});
	}

	public hasResource(fullPath: string) {

		if (fullPath in this.resources) {
			return true;
		}

		fullPath = _.trimEnd(fullPath, "/"); // path.dirname will drop the trailing slash
		return _.some(this.resources, (_r, resourceName) => path.dirname(resourceName) === fullPath);
	}

	public loadResource(fullPath: string) {
		return contextifyMetaCode(fullPath, this.resources[fullPath]);
	}

	public getProduct() {
		return this.product;
	}

	public listResources(fullPath: string) {
		fullPath = _.trimEnd(fullPath, "/"); // path.dirname will drop the trailing slash
		return (
			_.chain(this.resources)
				.keys()
				.filter((resourceName) => path.dirname(resourceName) === fullPath)
				.map((resourceName) => path.basename(resourceName))
				.value()
		);
	}

	public isFile(fullPath: string) {
		return !!this.resources[fullPath];
	}

	public getCombinedPath(fullPath: string): string {
		return fullPath;
	}
}
