import { forbiddenModification } from "./utils";

export interface AccessSpecification {
	read?: boolean;
	write?: boolean;
}

let deprecatedMemberAccess: AccessSpecification = {};

export function withDeprecatedAccess<Ret>(type: AccessSpecification, cb: () => Ret) {
	const originalType = deprecatedMemberAccess;
	try {
		deprecatedMemberAccess = type;
		return cb();
	} finally {
		deprecatedMemberAccess = originalType;
	}
}

export const enum AccessType {
	READ,
	WRITE,
}

export function validateDeprecatedAccess(type: AccessType) {
	if (
		(type === AccessType.READ && !deprecatedMemberAccess.read) ||
		(type === AccessType.WRITE && !deprecatedMemberAccess.write)
	) {
		forbiddenModification("Deprecated configurables may only be accessed from user scripts");
	}
}
