
import * as _ from "lodash";
import { IMyListItem } from "../IMyListItem";
import { SelectionInNode } from "../objectManagers/ui/selection";

export class NodeSelection<T extends IMyListItem> {

	private selection: SelectionInNode = { instanceId: null, memberPath: [] };
	constructor(private readonly getInstances: () => T[]) {
	}

	public getSelectedMyListItem() {
		this.resetSelectionIfNeeded();
		return this.getSelectedInstance();
	}

	public getSelection() {
		this.resetSelectionIfNeeded();
		return this.selection;
	}

	public setSelection(selection: SelectionInNode) {
		this.selection = selection;
		const inst = this.getSelectedInstance();
		if (inst) {
			inst.revealMember(selection.memberPath);
		}
	}

	private getSelectedInstance() {
		return _.find(this.getInstances(), (i) => i.getID() === this.selection.instanceId);
	}

	private resetSelectionIfNeeded() {
		const instances = this.getInstances();
		if (!this.isSelectionValid()) {
			const selection: SelectionInNode
				= { instanceId: instances[0] && instances[0].getID(), memberPath: [] };
			this.setSelection(selection);
		}
	}

	private isSelectionValid() {
		return (
			_.some(this.getInstances(), (i) => i.getID() === this.selection.instanceId) ||
			_.isEmpty(this.getInstances()) && !this.selection.instanceId
		);
	}
}
