/* eslint-disable no-console */

function empty() { }

export class ConsoleMessages {

	private readonly log = console.log;
	private readonly warn = console.warn;
	private readonly info = console.info;
	private readonly error = console.error;

	public enable() {
		console.log = this.log;
		console.warn = this.warn;
		console.info = this.info;
		console.error = this.error;
	}

	public disable() {
		console.log = empty;
		console.warn = empty;
		console.info = empty;
		console.error = empty;
	}
}
