import * as _ from "lodash";
export function processSerially<T>(
	collection: _.List<T>,
	predicate: (value: T, key?: number) => Promise<any>): Promise<void>;
export function processSerially<T>(
	collection: _.Dictionary<T>,
	predicate: (value: T, key?: string) => Promise<any>): Promise<void>;
export function processSerially<T>(
	collection: _.Dictionary<T> | _.List<T>,
	predicate:
		((value: T, key?: string) => Promise<any>) |
		((value: T, key?: number) => Promise<any>)): Promise<void> {

	const toProcess = _.map(collection as _.Dictionary<T>, (a, b) => {
		return () => {
			return (predicate as (value: T, key?: string) => Promise<any>)(a, b);
		};
	});

	function processNext(): Promise<void> {
		if (!_.isEmpty(toProcess)) {
			return toProcess.shift()()
				.then(() => processNext());
		}
		return Promise.resolve();
	}

	return processNext();
}
