interface KeyValueMap {
	[s: string]: any;
}

/**
 * get an object from the look up maps, based on the id property and value
 */
function getObjFromIDProp(lookupMaps: KeyValueMap, idProp: string, value: any) {

	const lookupMapName = idProp.replace("ID", "s");
	const map = lookupMaps[lookupMapName];

	if (map !== "undefined") {
		return map[value];
	}

	return null;
}

function updateWrapperReferences(lookupMaps: KeyValueMap, obj: KeyValueMap, i: string, makeArray: boolean) {

	// Fix wrapper, only needed for XML
	const listName = i.replace("Wrapper", "s");
	obj[listName] = makeArray ? [] : {}; // new array

	// go through each object in the wrapper
	_.each(obj[i], (ids) => {
		_.each(ids, (idValue, id) => {
			const refObj = getObjFromIDProp(lookupMaps, id, idValue);
			if (makeArray) {
				obj[listName].push(refObj);
			} else {
				if (!(obj[listName])[refObj.name]) {
					(obj[listName])[refObj.name] = refObj;
				}
			}
		});
	});

	delete obj[i];
}

/**
 * Update all ID properties with an actual object instance
 * 
 */
function updateIDReferences(obj: KeyValueMap, lookupMaps: KeyValueMap) {

	for (const i in obj) {

		// Update ID reference
		if (_.endsWith(i, "ID")) {

			// Create a new property and update the reference
			const refObj = getObjFromIDProp(lookupMaps, i, obj[i]);
			const newPropName = i.replace("ID", "");
			obj[newPropName] = refObj;

			// delete ID property
			delete obj[i];

		} else if (_.endsWith(i, "Wrapper")) {
			updateWrapperReferences(lookupMaps, obj, i, false);
		} else if (_.isObject(obj[i])) {
			updateIDReferences(obj[i], lookupMaps);
		}
	}
}

function augmentType<T>(base: any, toAdd?: any, toAddIfExists?: any, toDeleteFromBase?: string[]): T {

	const temp = _.extend(base, toAdd);
	_.each(toAddIfExists, (value: any, key: string) => {
		if (value) {
			temp[key] = value;
		}
	});

	_.each(toDeleteFromBase, (key: string) => {
		delete base[key];
	});

	return temp;
}

// Create data object as needed by the solver and UI from the unprocessed deviceInfo
function getAdaptedDeviceInfo(
	deviceInfo: DeviceInfo.DeviceInfo, deviceId: string, partId: string, packageId: string): Omit<AdaptedDeviceInfo, "core" | "clocktree"> {

	let deviceValid = true;

	const versions: Versions = {
		tool: null,
	};

	let showIOSets = false;
	const showPreferredVoltage = Object.keys(deviceInfo.powerDomains).length > 0;

	// We don't want to export device pins that aren't pinned out on the package (and thus 
	// useless), so we'll iterate over the device pins linked to from a package pin

	const devicePackage = deviceInfo.packages[packageId];
	const devicePackageName = devicePackage.name;
	const packageDescription = devicePackage.packageDescription;
	const devicePins: NameToDevicePinMap = _.chain(devicePackage.packagePin)
		.map((packagePin) => {

			// Convert the devicePinInfo into what we see as a devicePin.
			// "ball" is a legacy alias for "name".  Legacy templates still use it

			const devicePin: DevicePin = _.extend(packagePin.devicePin, {
				ball: packagePin.ball,
				designSignalName: packagePin.devicePin.name,
				name: packagePin.ball,
				pinMappings: [],
			});
			if (packagePin.powerDomain) {
				devicePin.powerDomain = packagePin.powerDomain;
			}
			return devicePin;
		})
		.keyBy((designPin) => designPin.name)
		.value();

	// However, we do want to export virtual pins, even though not on the package.  Virtual pins
	// are things like DMA channels - ie. resources that can be claimed by peripherals, but for 
	// which a non-trivial mapping exists (meaning a peripheral can't necessarily use EVERY DMA
	// channel).  It's not really a "device pin", but as you can see it follows the same basic 
	// rules so we model it like one.

	_.reduce(deviceInfo.devicePins, (result, devicePin) => {
		if (devicePin.devicePinType === "Virtual") {
			result[devicePin.name] = _.extend(devicePin, {
				designSignalName: devicePin.name,
				pinMappings: [],
			});
		}
		return result;
	}, devicePins);

	const peripherals: NameToPeripheralMap = {};
	const peripheralPins: NameToPeripheralPinMap = {};

	// go through the peripheral and link to its interface
	const part = deviceInfo.parts[partId];
	const devicePartName = part.name;

	_.each(part.peripherals, (peripheral) => {

		if (peripherals[peripheral.name]) {
			console.error("Duplicate peripheral found in part: " + peripheral.name + " with id: " + peripheral.id);
			deviceValid = false;
		}

		// convert IO sets to a map
		const adaptedIoSetGroup: IOSet[] = [];

		if (typeof (peripheral.ioSetGroups) !== "undefined") {

			showIOSets = true;

			if (peripheral.ioSetGroups.length > 1) {
				// Solver needs to be changed to account for IO Set groups
				console.error("Solver cannot handle multiple IO set groups seen in " + peripheral.name);
				deviceValid = false;
			}

			const ioSetGroup = peripheral.ioSetGroups[0];
			if (typeof (ioSetGroup.ioSet) !== "undefined") {
				_.each(ioSetGroup.ioSet, (ioSet) => {
					const isSetRules: IOSetRuleMap = {};
					_.each(ioSet.ioSetRule, (ioSetRule) => {
						isSetRules[ioSetRule.peripheralPin.name] = ioSetRule.devicePin.name;
					});
					const newIOSet: IOSet = {
						name: ioSet.name,
						ioSetRules: isSetRules,
					};
					adaptedIoSetGroup.push(newIOSet);
				});

			}

		}

		let numPeripheralPinsPinnedOut = 0;
		_.each(peripheral.peripheralPins, (peripheralPin) => {

			const newPeripheralPin: PeripheralPin = peripheralPin as PeripheralPin;

			newPeripheralPin.peripheralName = peripheral.name;
			peripheralPins[newPeripheralPin.name] = newPeripheralPin;
			newPeripheralPin.pinMappings = [];
			// Add device pin mappings
			const reverseMux = deviceInfo.reverseMuxes[newPeripheralPin.id];
			if (typeof (reverseMux) !== "undefined") {
				const muxSettings = reverseMux.muxSetting;
				_.each(muxSettings, (muxSetting) => {

					// Pin may not be on the package, or may be a power pin etc, so explicitly look
					// it up

					const devicePin = muxSetting.devicePin as DevicePin;
					if (devicePin === devicePins[devicePin.name]) {
						newPeripheralPin.pinMappings.push(devicePin);
					}
				});
			}

			// We may have multiple mappings, but just keep track of it once

			newPeripheralPin.pinMappings = _.uniqBy(newPeripheralPin.pinMappings, (pin) => pin.name);

			if (typeof (newPeripheralPin.interfacePin) !== "undefined") {

				// add to interface pin mappings
				if (typeof (newPeripheralPin.interfacePin.pinMappings) === "undefined") {
					newPeripheralPin.interfacePin.pinMappings = [];
				}

				newPeripheralPin.interfacePin.pinMappings.push(newPeripheralPin);
			}

			if (newPeripheralPin.pinMappings.length > 0) {
				numPeripheralPinsPinnedOut++;
			}

		});

		let interfaces: NameToInterfaceMap = null;
		// add to interface, if legacy data
		if (peripheral.interface) {
			interfaces = {};
			interfaces[peripheral.interface.name] = peripheral.interface as Interface;
		}

		const newPeripheral = augmentType<Peripheral>(peripheral, {
			ioSets: adaptedIoSetGroup,
		},
			{
				interfaces: interfaces ? interfaces : peripheral.interfaces,
			},
			["interface", "ioSetGroups"],
		);

		peripherals[newPeripheral.name] = newPeripheral;

		_.each(peripheral.interfaces, (perphInterface) => {

			const newPerhInterface = perphInterface as Interface;
			newPerhInterface.isConfigurablesOnly = !perphInterface.interfacePins || !_.size(perphInterface.interfacePins);

			if (typeof (newPerhInterface.peripherals) === "undefined") {
				newPerhInterface.peripherals = [];
			}

			// at least 1 pin is pinned out or is configurable only peripheral
			// at least 1 pin is pinned out usecase is for f28x, where certain
			// peripherals are not available on certain packages, however
			// they do want them to be shown, but disabled
			if (numPeripheralPinsPinnedOut > 0 || newPerhInterface.isConfigurablesOnly) {
				newPerhInterface.peripherals.push(newPeripheral);
			}

		});
	});

	// go though and link use cases to interfaces
	_.each(deviceInfo.useCases, (useCase) => {

		// add to interface
		const perphInterface = useCase.interface as Interface;
		if (typeof (perphInterface.useCases) === "undefined") {
			perphInterface.useCases = {};
		}

		let useCasePins = {};
		const useCasePinSets: UseCasePinSet[] = [];

		// go through use case pins
		// adapt them to UI interface pins; which is a combination of interface pins and use case pins
		if (typeof (useCase.useCasePin) !== "undefined") {
			useCasePins = toNameMap(useCase.useCasePin, (pin) => {
				deviceValid = false;
				console.error(`Duplicate use case pin ${pin.name} in ${useCase.description} of ${useCase.interface.name}`);
			});
		}

		if (typeof (useCase.useCasePinSet) !== "undefined") {

			_.each(useCase.useCasePinSet, (useCasePinSet) => {
				const pins = toNameMap(useCasePinSet.useCasePin, (pin) => {
					deviceValid = false;
					console.error(`Duplicate use case pin ${pin.name} in ${useCase.description} of ${useCase.interface.name}`);
				});
				const newUseCasePinSet = augmentType<UseCasePinSet>(useCasePinSet, { useCasePins: pins }, ["useCasePin"]);

				useCasePinSets.push(newUseCasePinSet);
			});
		}

		const newUseCase = augmentType<UseCase>(
			useCase,
			{
				useCasePins,
				useCasePinSets,
			},
			["useCasePin", "useCasePinSet"],
		);

		perphInterface.useCases[newUseCase.name] = newUseCase;

	});

	// Add a reference to the mux in the device pin

	_.each(deviceInfo.muxes, (mux) => {
		if (mux.devicePin) {
			const devicePin = devicePins[mux.devicePin.name];
			if (devicePin === mux.devicePin) {
				devicePin.mux = mux;
			}
			delete mux.devicePin;
		}
	});

	// For now, copy over specific members from the pin common 
	// infos to the corresponding device pin.  

	_.each(devicePins, (devicePin) => {
		const pci = deviceInfo.pinCommonInfos[devicePin.id];
		if (undefined !== pci) {
			devicePin.controlRegisterOffset = pci.controlRegisterOffset;
			devicePin.pupdStateAfterHHV = pci.pupdStateAfterHHV;
			devicePin.pupdStateDuringHHV = pci.pupdStateDuringHHV;
		}
	});

	const interfaces = toNameMap(deviceInfo.interfaces, (iFace) => {
		deviceValid = false;
		console.error("Duplicate interface detected: " + iFace.name);
	}) as NameToInterfaceMap;
	const powerDomains = toNameMap(deviceInfo.powerDomains, (powerDomain) => {
		deviceValid = false;
		console.error("Duplicate power domain detected: " + powerDomain.name);
	});

	// For the GPIO interface, determine which balls can be used as GPIO
	// Additionally, if the GPIO interface has one pin per peripheral, 
	// and that pin has only one possible ball mapping, and that's 
	// unique across GPIO peripherals, then mark it as "standardGPIO".  
	// We can then ignore requirements for those pins and instead just 
	// pick whatever GPIO balls remain and use that to infer the 
	// "solved" GPIO peripheral/pin

	const gpioPins: GPIOMap = {};
	let isOptimizable = false;
	const gpioIface = _.find(interfaces, (_iface, name) => 0 === name.toUpperCase().search(/GPIO.*/));

	if (gpioIface) {

		// Collect all GPIO pin info

		_.each(gpioIface.peripherals, (peripheral) => {
			_.each(peripheral.peripheralPins, (peripheralPin) => {
				_.each(peripheralPin.pinMappings, (devicePin) => {
					gpioPins[devicePin.name] = {
						devicePin,
						peripheralPin,
						interfacePin: peripheralPin.interfacePin,
					};
				});
			});
		});

		// For each interface pin, determine if all choices would restrict GPIO, if
		// no choices would restrict GPIO, or if it's a combination

		_.each(interfaces, (iface) => {
			_.each(iface.interfacePins, (interfacePin) => {
				const always = _.every(interfacePin.pinMappings, (peripheralPin) =>
					_.every(peripheralPin.pinMappings, (devicePin) => devicePin.name in gpioPins));
				if (!always) {
					const sometimes = _.some(interfacePin.pinMappings, (peripheralPin) =>
						_.some(peripheralPin.pinMappings, (devicePin) => devicePin.name in gpioPins));
					interfacePin.restrictsGPIO = sometimes ? "sometimes" : "never";
				} else {
					interfacePin.restrictsGPIO = "always";
				}
			});
		});

		// Technically we are able to optimize banks of GPIOs, but historically we haven't, and doing
		// so now might cause issues with reading in saved pinmux files.  So for now, disable if that's
		// how the SOC data has been described

		isOptimizable = 1 === _.size(gpioIface.interfacePins) &&
			_.size(gpioIface.peripherals) === _.size(gpioPins);
	}

	// adapt interfaces
	_.each(interfaces, (iface) => {

		// init
		iface.peripherals = iface.peripherals || [];

		// Sort certain arrays now so:
		// 1) the solver will always solve them in the same order
		// 2) the ui doesn't need an extra step to sort them
		naturalSort(iface.peripherals, (p) => p.name);
	});

	// Check for interface pin choices where some choices are in an
	// IO-set (meaning IO-set rules apply), but one choice is not in
	// ANY IO-set.  Those choices can never be taken, so we should
	// mark them as such

	_.each(peripherals, (peripheral) => {
		_.each(peripheral.peripheralPins, (pin, pinName) => {

			const ioSetChoices2 = _.chain(peripheral.ioSets)
				.map((ioSet) => ioSet.ioSetRules[pinName])
				.reject((ball) => {
					return undefined === ball;
				})
				.value();

			if (!_.isEmpty(ioSetChoices2)) {
				_.each(pin.pinMappings, (mapping) => {
					if (!_.includes(ioSetChoices2, mapping.name)) {
						mapping.excludedInEveryIOSet = true;
					}
				});
			}
		});
	});

	const showExtendedPinTypes = _.some(devicePins,
		(pin) => pin.devicePinType === "Power" || pin.devicePinType === "Ground" || pin.devicePinType === "Fixed");

	if (!deviceValid) {
		throw new Error("Device data is invalid");
	}

	return {
		versions,
		showIOSets,
		showPreferredVoltage,
		devicePins,
		peripherals,
		peripheralPins,
		packageDescription,
		interfaces,
		powerDomains,
		gpio: {
			isOptimizable,
			pinInfo: gpioPins,
		},
		templates: null,
		showExtendedPinTypes,
		rowColumnInverted: deviceInfo.rowColumnInverted,
		deviceId,
		device: deviceId,
		package: devicePackageName,
		part: devicePartName,
		cores: deviceInfo.cores,
	};
}

// Create the adapted device description object
function getAdaptedDeviceDescription(discoveryRoot: Discovery.DiscoveryJSON) {

	const devices = discoveryRoot.devices;
	const renames: { [key: string]: string } = {};

	// It is not possible to filter out packages based on the part choice.
	// This is a new requirement for the TM4 devices. Thus, newer PackageDescriptions have ID's
	// that could be referenced by part descriptions. However, the older devices will not have this
	// and will need to be accounted for.
	_.each(devices, (deviceDescription) => {

		// lets first go through all the package descriptions and create an ID to Package Description map
		const packageDescriptionLookup: { [key: string]: Discovery.PackageDescription } = {};

		_.each(deviceDescription.package, (pkg) => {
			if (pkg.id) {
				packageDescriptionLookup[pkg.id] = pkg;
			}
		});

		_.each(deviceDescription.part, (part) => {

			if (part.packageDescriptionWrapper) {
				updateWrapperReferences({
					packageDescriptions: packageDescriptionLookup,
				}, part, "packageDescriptionWrapper", true);
			} else {
				// if no packages are defined by the part.. than make all parts available

				(part as any as PartDescription).packageDescriptions = deviceDescription.package;
			}
		});

		// create a table of device names that have been changed
		_.each(deviceDescription.legacyNames, (legacyName) => {
			renames[legacyName] = deviceDescription.name;
		});

	});

	const newDiscoveryRoot = augmentType<DiscoveryJSON>(discoveryRoot,
		{ renames },
	);

	// Sort everything
	newDiscoveryRoot.devices = _.sortBy(newDiscoveryRoot.devices, (device) => device.name);

	return newDiscoveryRoot;
}

async function loadDeviceData(deviceId: string, partId: string, packageId: string) {

	const deviceInfoText = await http.get("deviceData/" + deviceId + "/" + deviceId + ".json");
	const deviceInfo = parseJSON<DeviceInfoRaw.IndexedDeviceInfo>(deviceInfoText);
	updateIDReferences(deviceInfo, deviceInfo);
	return getAdaptedDeviceInfo((deviceInfo as any as DeviceInfo.DeviceInfo), deviceId, partId, packageId);
}

async function loadClockTree(deviceId: string) {
	const discoveryJSON = await getDeviceDescriptions();
	if (_.find(discoveryJSON.devices, (d) => d.name === deviceId).hasClocktree) {
		const clockTreeText = await http.get("deviceData/" + deviceId + "/clocktree.json");
		return parseJSON<ClockTree>(clockTreeText);
	}
	return undefined;
}

function loadDeviceDataTemplates(
	templatesRoot: string, templates: TemplatesInfo.TemplatesInfo, deviceInfo: Pick<AdaptedDeviceInfo, "templates">) {

	const fileListArray = _.flatMap(templates, (templateFiles, outputType) => {
		return _.map(templateFiles, (templateFile) => {
			return {
				name: templateFile.split("/").pop().replace(/\.xdt$/, ""),
				path: templatesRoot + "/" + templateFile,
				category: outputType,
				// device SOC data templates are non-conditional
				alwaysRun: true,
				ignoreErrors: true,
			};
		});
	});
	naturalSort(fileListArray, (item) => item.name);
	deviceInfo.templates = { fileListArray };
}

async function loadDefaultTemplates(deviceId: string, deviceInfo: Pick<AdaptedDeviceInfo, "templates" | "versions">) {

	const templatesRoot = "/" + deviceId + "/templates";
	const templatesHttpPath = "deviceData" + templatesRoot;
	const templates = await http.get(templatesHttpPath + "/index.json");
	return loadDeviceDataTemplates(templatesRoot, parseJSON<TemplatesInfo.TemplatesInfo>(templates), deviceInfo);
}

const getDeviceDataImpl = memoizeOne(async (deviceId: string, partId: string, packageId: string, loadTemplates: boolean) => {

	const builtInDevice = builtInDevices[deviceId];
	if (builtInDevice) {
		return builtInDevice.adaptedDeviceInfo;
	}

	const [deviceData, clockTree] = await Promise.all([
		loadDeviceData(deviceId, partId, packageId),
		loadClockTree(deviceId),
	]);

	deviceData.clockTree = clockTree;
	deviceData.versions.tool = getToolVersion();

	// default templates
	if (loadTemplates) {
		await loadDefaultTemplates(deviceId, deviceData);
	}
	return deviceData;
});

export async function getDeviceData(
	deviceId: string,
	partId: string,
	packageId: string,
	loadTemplates: boolean,
): Promise<AdaptedDeviceInfo> {

	// Get a cache of the device data without "board" or "core" specified using the memoized 
	// function.  Then return a shallow clone so board/core can be added without affecting the
	// cache

	return _.clone(await getDeviceDataImpl(deviceId, partId, packageId, loadTemplates));
}

// used when load script/pinmux files to adapt for changed device names
export function getRenamedDeviceId(deviceId: string, discoveryData: DiscoveryJSON) {
	return discoveryData.renames[deviceId] || deviceId;
}

/** 
 * Get a http promise to data describing available devices
 */
async function createDeviceDescriptions() {
	try {
		const raw = await http.get("deviceData/devices.json");
		return parseDeviceDescriptions(raw);
	} catch (e) {
		throw new Error("Failed to load device data: please run build_device_data in build/scripts");
	}
}
// Generate device descriptions on load
const deviceDescriptions = createDeviceDescriptions();
export function getDeviceDescriptions() {
	return deviceDescriptions;
}

export function parseDeviceDescriptions(rawData: string) {
	const devices = getAdaptedDeviceDescription(parseJSON<Discovery.DiscoveryJSON>(rawData));
	devices.devices = [
		...devices.devices,
		...(_.map(builtInDevices, (b) => b.deviceDescription)),
	];
	return devices;
}

export function findDeviceInfo(
	discoveryData: DiscoveryJSON,
	deviceName: string,
	partName?: string,
	packageName?: string,
) {
	deviceName = getRenamedDeviceId(deviceName, discoveryData);
	const device = _.find(discoveryData.devices, (d) => d.name === deviceName);
	if (!device) {
		throw new SetupError(deviceName + ". This device may be available in a newer version of SysConfig", "Device not found");
	}

	const part = partName ? _.find(device.part, (p) => p.name === partName) : _.first(device.part);
	if (!part) {
		throw new SetupError(partName + ". This part may be available in a newer version of SysConfig", "Part not found");
	}

	const pkg = packageName
		? _.find(part.packageDescriptions, (p) => p.name === packageName)
		: _.first(part.packageDescriptions);
	if (!pkg) {
		throw new SetupError(packageName + ". This package may be available in a newer version of SysConfig", "Package not found");
	}

	return {
		deviceId: device.name,
		partId: part.partID,
		packageId: pkg.packageID,
	};
}
