import * as _ from "lodash";
import { ObjectMemberManager } from "../objectMember";
import { ModuleRequirement, SharedModuleInstanceRequirement, ModuleInstanceRequirement } from "public/defs";
import { ModuleInstance } from "public/runtime";
import { StaticModuleInstanceMgr } from "../staticModuleInstance";
import { ViewNode, ContainerNode, LeafNode, MatchedPathRetType } from "../viewNodes";
import { getDisplayName } from "../../utils";
import { ModuleInstanceMgr } from "../moduleInstance";
import { Runtime } from "../../resources/runtime";
import { Validations } from "../validations";

// Base class with common functionality for members that manage
// some sort of a module instance
export abstract class InstanceMemberMgr<
	ValueObjectMgrType extends ModuleInstanceMgr | StaticModuleInstanceMgr,
	RequirmentType extends SharedModuleInstanceRequirement | ModuleInstanceRequirement | ModuleRequirement>
	extends ObjectMemberManager<ValueObjectMgrType, ModuleInstance, ModuleInstanceMgr, RequirmentType>
	implements ContainerNode {

	public type: "container";
	protected readonly runtime: Runtime;
	private collapsed: boolean;
	private showLongDescription: boolean;
	private readonly defaultCollapsedState: boolean;

	constructor(
		valueObjectMgr: ValueObjectMgrType,
		runtime: Runtime,
		def: RequirmentType,
		parentObjectMgr: ModuleInstanceMgr,
		options: {
			internalReference?: boolean,
			collapsed: boolean,
		}) {
		const { collapsed, ...rest } = options;
		super(valueObjectMgr, runtime.getFormattersMap(), def, parentObjectMgr, rest);
		this.runtime = runtime;
		this.type = "container";
		this.showLongDescription = false;
		this.collapsed = collapsed;
		this.defaultCollapsedState = collapsed;
	}

	public override validate(validations: Validations) {
		super.validate(validations, false); // the value is a module instance and will validate itself as normal
	}

	public getValidationsummary(validations: Validations) {
		return validations.getSummary(this.valueObjectMgr);
	}

	public getChildren(): ViewNode[] {
		return this.valueObjectMgr.getViewNodes();
	}

	public getHeading(displayScriptName: boolean): string {
		return getDisplayName(this.def, displayScriptName);
	}

	public getTitleNode(): LeafNode {
		return null;
	}

	public getNumColumns() {
		return 1;
	}

	public getSecondaryHeading(): string {
		return this.def.description;
	}

	public getKey(): string {
		return this.def.name;
	}

	public isHidden(): boolean {
		return _.every(this.getChildren(), (c) => c.isHidden());
	}

	public isCollapsed(): boolean {
		return this.collapsed;
	}

	public setCollapsed(val: boolean): void {
		this.collapsed = val;
	}

	public getDefaultCollapsedState() {
		return this.defaultCollapsedState;
	}

	public isLongDescriptionVisible() {
		return this.showLongDescription;
	}

	public setLongDescriptionVisibility(val: boolean) {
		this.showLongDescription = val;
	}

	public getLongDescription() {
		return this.valueObjectMgr.getModuleMgr().getLongDescription();
	}

	public isReadOnly() {
		return !!this.def.readOnly;
	}

	public matchSubItemPath(itemPath: string[]): MatchedPathRetType {
		const matched = this.valueObjectMgr.getNameMgr().getValue() === _.first(itemPath);
		return [matched, _.tail(itemPath)];
	}

	protected override validateValue(newInst: ModuleInstance) {
		super.validateValue(newInst, false);
		const instModName = newInst.$module.$name;
		if (instModName !== this.def.moduleName && // fast check
			this.runtime.getModuleMgr(instModName) !== this.runtime.getModuleMgr(this.def.moduleName)) { // slower check (delegate case)

			throw new Error(`Invalid instance type, expected = ${this.def.moduleName}, actual = ${instModName}`);
		}
	}
}
