import { AbstractChoice, RelatedChoices } from "./common";
import { PeripheralChoices } from "./peripheral";
import { DevicePinChoices } from "./devicePin";
import { not, chooseOneOfOnlyIf } from "../clauseGeneration";
import { addLiteral, endClause } from "../clauses";
import { nameChoices, formatNameChoice } from "../debug";
import * as data from "dataInterfaces";

// -----------------------------------------------------------------------------
// IOSetChoices
// A factory for creating a choice of a specific ioSet for a peripheral when it
// is chosen.  Also eventually generates the clauses for all the relationships 
// of these choices and pin choices
// -----------------------------------------------------------------------------

export class IOSetChoices {
	private readonly byRequirement = new RelatedChoices<number, IOSetChoices.Choice>();

	constructor(private readonly pinChoices: DevicePinChoices) { }

	public newChoice(peripheralChoice: PeripheralChoices.Choice, ioSet: data.IOSet) {
		const choice = new IOSetChoices.Choice(peripheralChoice, ioSet);

		this.byRequirement.get(peripheralChoice.id).push(choice);
	}

	public generateClauses() {
		chooseOneOfOnlyIf(this.byRequirement, null,
			"must choose one ioset per requirement, but only if the matching peripheral is selected");

		// A pin may only be chosen if it exists in a chosen ioset, or is not in any iosets 

		this.byRequirement.forEach((_choices, peripheralChoiceId) => {
			const ioSetChoices = this.byRequirement.get(peripheralChoiceId);
			const pinChoices = this.pinChoices.byParent.get(peripheralChoiceId) || [];
			for (const pinChoice of pinChoices) {
				let pinExistsInAnyIOSet = false;
				for (const ioSetChoice of ioSetChoices) {
					if (pinChoice.peripheralPin.name in ioSetChoice.ioSet.ioSetRules) {
						pinExistsInAnyIOSet = true;
						if (ioSetChoice.ioSet.ioSetRules[pinChoice.peripheralPin.name] === pinChoice.devicePin.name) {
							addLiteral(ioSetChoice.id);
						}
					}
				}
				if (pinExistsInAnyIOSet) {
					addLiteral(not(pinChoice.id));
					endClause(
						"only choose a pin if it's mapping is in the chosen ioset, or the interface pin is not part of any ioset");
				}
			}
		});
	}
}

export namespace IOSetChoices {

	export class Choice extends AbstractChoice {
		public readonly ioSet: data.IOSet;
		constructor(private peripheralChoice: PeripheralChoices.Choice, ioSet: data.IOSet) {
			super();
			this.ioSet = ioSet;

			if (nameChoices) {
				this.name = "IOSet " + formatNameChoice(peripheralChoice.peripheralReq) + "->" + ioSet.name +
					" (" + peripheralChoice.peripheral.name + ")";
			}
		}

		public apply() {
			this.peripheralChoice.peripheralReq.solution.ioSet = this.ioSet.name;
		}
	}
}
