import * as _ from "lodash";
import { Resource } from "./requirements";
import { FormattersMap } from "../formatting/formattersMap";
import { FormatStyle } from "../formatting/formattingTypes";

export const debug = false;
export const debugSolution: number[] = [];
export const textBasedClauses = debug || debugSolution.length || false;
export const nameChoices = debug || textBasedClauses || false;
export const summarizeData = debug || false;
export const profile = false;
export const profileGlucose = profile || false;
let abortOnErrorSetting = false;

export function abortOnError(val?: boolean) {
	if (!_.isUndefined(val)) {
		abortOnErrorSetting = val;
	}

	return abortOnErrorSetting;
}

export let formatNameChoice = (_req: Resource) => {
	logicError("function called before it's defined");
};

export function setFormatNameChoice(formattersMap: FormattersMap) {
	formatNameChoice = (req) => formattersMap.getFormatter({ style: FormatStyle.CLI })(formattersMap.getEncodingTag(req));
}

export function log(message: string) {
	if (!debug && !textBasedClauses && !summarizeData && !profile && !profileGlucose) {
		debugger; // eslint-disable-line no-debugger
	}
	console.log(message); // eslint-disable-line no-console
}

const enum GlucoseVerbosity {
	NONE = 0,
	SUMMARY = 1,	// Summarize budget usage
	STATS = 2,		// Above with solver stats on configuration and progress
	GC_STATS = 3,	// Above with garbage collection info
}

export const glucoseVerbosity = {
	verbosity: textBasedClauses ? GlucoseVerbosity.SUMMARY : GlucoseVerbosity.NONE,
	verbEveryConflicts: 1000,
};

// We run out of memory around 3828393 conflicts and 128765074 propagations, so
// I initially set the budget at 1/10 that to hopefully ensure we never run out 
// of memory.
// Later, with more complex devices, the solver couldn't find trivial solutions.  
// This was because the restart restriction was too low.  As such, I developed 
// measureBudget (solver_tests -m measureBudget) which outputs new budgets 
// encountered.  Looking at the true case (false and undefined would be treated 
// as "false" anyway, so we really only need look at the true case) for the latest
// data gives a max budget of 63192, 4059486, 287.  However, a budget that high
// makes simple cases a lot slower.  
//
// So instead, I've made the restarts budget parameter to be variable.  If the 
// solver finds that the solver failed to find a solution when it should have, 
// restarts is multiplied by restartsMultiplier and the solve is re-tried.  When
// a new device is initialized, the restarts parameter is reset.
// 
// See https://jira.itg.ti.com/browse/PMUX-508 for additional details
//
// Latest data from measureBudget is 248377, 27501014, 1397 from AM263x_beta_ZCZ_AM263x

export const glucoseBudget = {
	conflicts: 250000,			// Glucose parameter
	propagations: 28000000,		// Glucose parameter
	restarts: 14,				// Glucose parameter
	restartsInit: 14,			// Initial value of restarts
	restartsMultiplier: 3,		// Value to multiply restarts by when solving gets tough
	restartsMax: 1397,			// Max value to allow restarts to reach
};

export function logicError(errorText: string) {

	if (abortOnError()) {
		throw new Error(errorText);
	}
	console.error(errorText);
}
