import * as bigInt from "big-integer";
import { NumericConfigurable } from "public/defs";
import { RuntimeObject } from "public/runtime";
import { FormattersMap } from "../../formatting/formattersMap";
import { SetSource } from "../member";
import { AObjectMgr } from "../object";
import { ConfigurableMgr } from "./configurableMgr";
import {
	NumStrFormatType,
	getRadix,
	getAdvancedDisplayFormatOptions,
} from "../../numberUtils";

export abstract class NumericConfigurableMgr<NumberType extends number | bigInt.BigInteger>
	extends ConfigurableMgr<NumberType> {

	// Storing the numeric value of this configurable as a string allows for it to be displayed in the
	// numeric input HTML tag

	constructor(
		parentObjectMgr: AObjectMgr<RuntimeObject>,
		formattersMap: FormattersMap,
		public override readonly def: NumericConfigurable<NumberType>,
	) {
		super(parentObjectMgr, formattersMap, def);
	}

	// Set the value of this numeric configurable, given a string value from the GUI
	public setValueAsString(val: string, source: SetSource) {
		this.set(this.stringToNum(val), source);
	}

	// Get the value of the property as a string to be displayed by the GUI
	public getValueAsString() {
		return this.numToString(this.value);
	}

	public abstract getFormats(): NumStrFormatType[];

	protected abstract stringToNum(val: string): NumberType;

	protected abstract numToString(val: NumberType): string;

	protected getRadix() {
		return getRadix(this.def.displayFormat);
	}

	protected getAdvancedDisplayFormatOptions(opt: "fixedPoint" | "bitSize") {
		return getAdvancedDisplayFormatOptions(opt, this.def.displayFormat);
	}
}
