import * as _ from "lodash";
import { InterfaceInstanceMgr } from "../objectManagers/interfaceInstance";
import { format as formatModule } from "./moduleFormatter";
import { FormatStyle, FormatOptions, CLIFormatOptions, UIFormatOptions } from "./formattingTypes";
import { toFormattedLink, FormattedLinkAndDestination } from "./link";
import { assertUnreachable, formatRootInterfaceCLI } from "../utils";
import { TabName } from "../tabNames";

export function format(instMgr: InterfaceInstanceMgr, options: CLIFormatOptions, member?: string): string;
export function format(
	instMgr: InterfaceInstanceMgr, options: UIFormatOptions, member?: string): FormattedLinkAndDestination;
export function format(
	instMgr: InterfaceInstanceMgr, options: FormatOptions, member?: string): string | FormattedLinkAndDestination;
export function format(instMgr: InterfaceInstanceMgr, options: FormatOptions, member?: string) {

	switch (options.style) {
		case FormatStyle.CLI:
			return formatCLI(instMgr, member);
		case FormatStyle.UI:
			return formatUI(instMgr, options, member);
		default:
			assertUnreachable(options);
			return "";
	}
}

function formatCLI(instMgr: InterfaceInstanceMgr, member?: string): string {

	// If we have a parent, use it's formatting and tag on our member

	if (instMgr.parentModuleMgr) {
		const memberName = _.find(instMgr.parentModuleMgr.memberMgrs,
			(mgr) => mgr.getValue() === instMgr.managedObject).def.name;
		if (member) {
			return `${formatModule(instMgr.parentModuleMgr, { style: FormatStyle.CLI }, memberName)}.${member}`;
		}
		return formatModule(instMgr.parentModuleMgr, { style: FormatStyle.CLI }, memberName);
	}

	return formatRootInterfaceCLI(instMgr, member);

}

function formatUI(instMgr: InterfaceInstanceMgr, options: UIFormatOptions, member?: string) {

	// If we have a parent, use it's formatting, but replace with our member if necessary

	if (instMgr.parentModuleMgr) {
		const instDef = _.find(instMgr.parentModuleMgr.memberMgrs, (mgr) => mgr.getValue() === instMgr.managedObject).def;
		if (member) {
			const memberDef = instMgr.memberMgrs[member].def;
			const formattedModule = formatModule(instMgr.parentModuleMgr, options, instDef.name);
			formattedModule.destination.memberPath.pop(); // remove interfaceInstanceMemberMgr name			
			formattedModule.destination.memberPath.push(instMgr.getID()); // add the instance ID
			formattedModule.destination.memberPath.push(memberDef.name); // add the pin name
			if (formattedModule.baseText === instDef.displayName) { // If in the current selection
				formattedModule.baseText = memberDef.displayName;  // Point to our member
			}
			return formattedModule;
		}
		return formatModule(instMgr.parentModuleMgr, options, instDef.name);
	}

	return toFormattedLink(
		instMgr.getContextId(),
		instMgr.getContextDisplayName(),
		instMgr.isReservation() ?
			TabName.RESERVATION :
			TabName.PERIPHERALS,
		instMgr.managedObject.$interface.name,
		instMgr,
		instMgr.memberMgrs[member || "$assign"].def,
		options.selection,
	);
}
