import * as _ from "lodash";
// Manages javascript modules defined in sdk products.
import { AInstanceContainer } from "./instanceContainer";
import { ModuleInstanceMgr, ModuleInstanceMgrFactory } from "../objectManagers/moduleInstance";
import { Module, ModuleInstance } from "public/runtime";
import { Runtime } from "../resources/runtime";
import { InstanceArgs, IValidationLogger, UIAdd } from "public/defs";
import { StaticModuleInstanceMgr } from "../objectManagers/staticModuleInstance";
import { internalBoundary } from "../niceExceptions";
import { validateInstanceCreateAllowed } from "../validateAdd";
import { recursiveFindTopModuleCategory } from "../product/topModules";
import { InstanceArgType } from "../objectManagers/member";
import { Validations } from "../objectManagers/validations";
import { assertUnreachable } from "../utils";

function getLongDescription(mod: Module) {

	// store the long description for this module
	// if moduleStatic and moduleStatic.longDescription is defined, it will use the longDescription
	// and documentation from the static; otherwise, it will use the one in the module

	const longDescription = (mod.moduleStatic && !_.isEmpty(mod.moduleStatic.longDescription)) ?
		mod.moduleStatic.longDescription
		: (mod.longDescription || "");

	return longDescription;
}
/**
 * Class to track managers for instances of a particular type of module.
 */
export class ModuleMgr extends AInstanceContainer<ModuleInstanceMgr> {

	public static: StaticModuleInstanceMgr = null;
	private readonly namePrefix: string;
	private readonly displayName: string;
	private readonly longDescription: string;

	// user pref for show or hiding long description
	private userShowLongDescPref: boolean;
	private alwaysShowLongDescription: boolean;

	constructor(
		protected readonly runtime: Runtime,
		public readonly module: Module,
	) {

		super(module.$name);
		this.displayName = module.displayName || this.namePrefix;
		this.longDescription = getLongDescription(module);
		this.alwaysShowLongDescription = !!module.alwaysShowLongDescription;
		this.userShowLongDescPref = !!module.alwaysShowLongDescription;
	}

	// Canonical of the module (not the instance)
	// ie. /ti/drivers/UART
	public getName() {
		return this.module.$name;
	}

	public getSolverRequirements() {
		return _.flatMap(this.allInstancesIncludingStatic(), (inst) => inst.getSolverRequirements());
	}

	public solveComplete() {
		_.each(this.allInstancesIncludingStatic(), (inst) => inst.solveComplete());
	}

	// Name of the module in the left pane
	// ie. UART
	public getDisplayName(displayScriptName: boolean): string {
		return displayScriptName ? this.module.$name : this.displayName;
	}

	public getNonInstUsedPins(): Set<string> {
		// return all pins used in staticModuleMgr
		return this.static ? this.static.getUsedPins() : new Set<string>();
	}

	public getModuleCategory(): string {
		const moduleName = this.module.$name;
		const topModuleCategories = this.runtime.getTopModules().getModuleCategories();
		return recursiveFindTopModuleCategory(topModuleCategories, moduleName);
	}

	public getMaxAllowed(): number {
		if (this.isStaticOnly()) {
			return 1;
		} else {
			return this.module.maxInstances || Number.POSITIVE_INFINITY;
		}
	}

	// return error msg if exceed max allowed
	public validateInstanceCount(validation: IValidationLogger, moduleInstance: ModuleInstance) {
		if (_.size(this.instances) > this.getMaxAllowed()) {
			const msg = `Maximum of ${this.getMaxAllowed()} instance(s) allowed.`;
			validation.logError(msg, moduleInstance);
		}
	}

	public isStaticOnly() {
		return this.module.uiAdd === "staticOnly";
	}

	public getNumberOfUsed(): number {
		return this.isStaticOnly() && !!this.static ? 1 : this.instances.length;
	}

	public validate(validations: Validations) {
		_.each(this.allInstancesIncludingStatic(), (i) => i.validate(validations));
	}

	public finalValidate() {
		_.each(this.allInstancesIncludingStatic(), (i) => i.finalValidate());
	}

	public applySolverValidation() {
		_.each(this.allInstancesIncludingStatic(), (i) => i.applySolverValidation());
	}

	public getScriptIdentifier(): string {
		const identifers = this.runtime.getSerializationContext().getModuleIdentifiers();
		const basename = _.last(this.module.$name.split("/")).replace(/\..*$/, "");
		return identifers.getScriptIdentifiers(this, basename);
	}

	public getLongDescription(): string {
		return this.longDescription;
	}

	public getDescription(): string {
		return this.module.description;
	}

	public isTop() {
		return this.runtime.isTopModule(this.module.$name);
	}

	public initStatic(userCreated: boolean) {

		if (!this.static) {
			// init if not initialized
			StaticModuleInstanceMgr.createStatic(
				this.runtime,
				this,
				userCreated,
			);
		}

		// The module may have already been implicitly pulled in (via modules() statement from 
		// another module), but if we're now trying to explicitly pull it in as user-created, then
		// we must explicitly override whatever its current setting is

		if (userCreated) {
			this.static.setUserCreatedOrTouched(userCreated);
		}

		return this.static;
	}

	public getUIView() {
		return this.module.uiView;
	}

	public getDefaultInstanceName(fullModuleFilePath: string) {
		// replace leading / with space
		let defaultInstanceName = fullModuleFilePath.replace(/^\//, "");
		// replace remaining with _
		defaultInstanceName = defaultInstanceName.replace(/\//g, "_");
		// remove extension
		return defaultInstanceName.replace(/\..*$/, "");
	}

	public allInstancesIncludingStatic() {
		return this.static ? [...this.instances, this.static] : this.instances;
	}

	public addInstance(args: InstanceArgs = {}, isUserCreated = true) {

		validateInstanceCreateAllowed(this.module);
		const objMgr = internalBoundary(() => ModuleInstanceMgrFactory.createInstance(this.runtime, this.module, isUserCreated, {}));
		objMgr.setValueFromArgs(args, InstanceArgType.USER);

		return objMgr;
	}

	public addStatic(): StaticModuleInstanceMgr {
		return this.initStatic(true);
	}

	// try to remove as much of the module as possible
	public removeModule() {
		this.removeAllRemovableInstances();
		if (this.static && this.static.isRemovable()) {
			this.static.remove();
		}
	}

	public removeModuleDisabled() {

		if (!this.static) {
			return true;
		}

		return _.every(this.allInstancesIncludingStatic(), (i) => !i.isRemovable());
	}

	public staticAddDisabled() {
		return !!this.static;
	}

	public override instanceAddDisabled() {
		return this.getUIAdd() === "instanceOnly" ? super.instanceAddDisabled() : !this.static;
	}

	public getUIAdd(): UIAdd {
		return this.module.uiAdd;
	}

	public getListItemForFormatter(): ModuleInstanceMgr {
		if (this.getUIAdd() === "instanceOnly") {
			return this.getSelectedMyListItem();
		} else if (this.getUIAdd() === "staticAndInstance") {
			return _.isEmpty(this.instances) ? this.static : this.getSelectedMyListItem();
		} else {
			return this.static;
		}
	}

	public override setShowUserLongDescPref(status: boolean) {
		this.userShowLongDescPref = status;
	}

	public getShowUserLongDescPref() {
		return this.userShowLongDescPref;
	}

	public override getAlwaysShowUserLongDesc() {
		return this.alwaysShowLongDescription;
	}

	public override treeNodeAddDisabled() {
		// if module is type summary than we don't want the option to add
		const uiAdd = this.getUIAdd();
		switch (uiAdd) {
			case "summary":
				return true;
			case "staticAndInstance":
				return this.isAdded();
			case "instanceOnly":
			case "staticOnly":
				return super.treeNodeAddDisabled();
			default:
				assertUnreachable(uiAdd);
		}
	}

	public getRuntimeSelection() {
		return this.getSelectedMyListItem()?.managedObject ||
			this.static?.managedObject;
	}

	public getInstance(name: string) {
		return _.find(this.instances, (inst) => {
			return inst.managedObject.$name === name;
		});
	}

	protected override isAdded() {
		return !!this.static;
	}
}
