import * as _ from "lodash";
import {
	argsDef,
	IArgsDef,
	IArgDef,
} from "../pinmux/services/args/argTypes";
import { keys } from "../pinmux/services/utils";

// All Cli Args
interface ICLIArgsDef extends IArgsDef {
	help: IArgDef<boolean>;
	version: IArgDef<boolean>;
}

const extendedCLIArgsDef: ICLIArgsDef = {
	...argsDef,
	help: {
		description: "Show this screen",
	},
	version: {
		description: "Show version",
	},
};
export function getOptionsText() {

	const maxOptionsLineLength = 80;
	const prefixAndDescriptionSpacing = 4;
	const prefixIndentSpacing = 1;

	const optionHeadingsAndDescriptions = _.map(keys(extendedCLIArgsDef), (longName) => {
		const argDef = extendedCLIArgsDef[longName];
		const isFlag = _.isBoolean(argDef.default);
		const optionTypeText = argDef.pathType || !isFlag && "string";

		let heading = "";
		if (argDef.shortName) {
			heading += `-${argDef.shortName}`;
			if (optionTypeText) {
				heading += ` <${optionTypeText}> `;
			} else {
				heading += " ";
			}
		}

		heading += `--${longName}`;
		if (optionTypeText) {
			heading += ` <${optionTypeText}>`;
		}

		const description = _.isUndefined(argDef.default) ? argDef.description : `${argDef.description} [${argDef.default}]`;

		return {
			description,
			heading,
		};

	});

	const headingTextMaxLength = _.maxBy(optionHeadingsAndDescriptions, ({ heading }) => heading.length).heading.length;

	const lines = _.flatMap(optionHeadingsAndDescriptions, ({ heading, description }) => {

		const wrappedDescription = wrap(description,
			maxOptionsLineLength - headingTextMaxLength - prefixAndDescriptionSpacing - prefixIndentSpacing);

		const optionLines = _.map(wrappedDescription, (descriptionLine, index) => {
			const prefix = _.padEnd(index === 0 ? heading : "", headingTextMaxLength + prefixAndDescriptionSpacing);
			return `${_.repeat(" ", prefixIndentSpacing)} ${prefix}${descriptionLine}`;
		});

		return optionLines;
	});

	return (
		`Options:
	
${_.join(lines, "\n")}
					`
	);
}

function wrap(str: string, wrapAt: number) {

	const words = _.split(str, " ");
	const lines: string[][] = [];

	let currentLineWords: string[] = [];
	let currentLineLength = 0;
	let index = 0;

	while (index < words.length) {

		const word = words[index];
		const addToSameLine = (currentLineLength + word.length) < wrapAt;

		if (addToSameLine) {
			currentLineWords.push(word);
			currentLineLength += word.length + 1; // +1 for the space
			index++;
		}

		if (!addToSameLine || index === words.length) {
			lines.push(currentLineWords);
		}

		if (!addToSameLine) { // reset
			currentLineLength = 0;
			currentLineWords = [];
		}
	}

	return _.map(lines, (line) => _.join(line, " "));
}
