import * as _ from "lodash";
import { ModuleInstance, ModuleInstanceFactory } from "public/runtime";
import { InstanceArgs } from "public/defs";
import { Runtime } from "../resources/runtime";
import { internalBoundary } from "../niceExceptions";
import { InstanceArgType } from "../objectManagers/member";

export class ModulesImpl {

	constructor(
		private readonly runtime: Runtime,
	) { }

	public readonly add = (modulePath: string, staticInstArgs: InstanceArgs = {}, isUserCreated = true):
		ModuleInstanceFactory & ModuleInstance & { [memberName: string]: any } => {

		// If we're adding modules, we can now safely freeze the board content

		this.runtime.freezeBoardContent();

		// This first step will likely run the meta-code to define the module

		const mod = this.runtime.getModuleMgr(modulePath);

		// This will actually create a static instance, but also runs meta-code to determine
		// dependencies

		const staticInstMgr = internalBoundary(() => mod.initStatic(isUserCreated));

		// Finally, we can apply user args and return

		staticInstMgr.setValueFromArgs(staticInstArgs, InstanceArgType.USER);
		return staticInstMgr.managedObject;
	}
}
