import * as _ from "lodash";
import { Product as RealProduct, AvailableProductInfo as RealAvailableProductInfo } from "./product/types";
import { AdaptedDeviceInfo as RealAdaptedDeviceInfo, DeviceDescription as RealDeviceDescription } from "dataInterfaces";
import { systemContext, ResolvedArgs } from "./args/argTypes";
import { ContextInfo, ProductContextsMap } from "public/defs";
import { scriptDirProductName } from "./product/loadResources";
import { Named } from "public/common";

// This returns all the contexts that are valid choices in the UI.  In the UI we only want to allow 
// the user to pick a context that is valid for the lone product they've chosen and not every 
// possibly valid context there is.
//
// This returns Named vs ContextInfo, as while we do resolve it, we don't necessarily have 
// everything in ContextInfo

export function getUIContextChoices(product: AvailableProductInfo, device: DeviceDescription): Named[] {
	return _.map(resolve(getProductContexts([product.contexts], device), device));
}

// This returns all the context names that are valid to specify on the command line.  Unlike the 
// start page, the command line may specify multiple products, or even reserved peripherals for a
// context none of the products configure

export function getCLIContextChoices(
	products: Product[],
	deviceData: AdaptedDeviceInfo | DeviceDescription
): Named[] {
	if (_.isEmpty(products)) {
		return [systemContextEntry]; // core pinmux case
	} else {

		// Find the contexts for the products we have

		const contextsMaps = _.compact(_.map(products, (p) => p.file.contexts));
		const productDefinedContexts = getProductContexts(contextsMaps, deviceData);

		// Include the system context first, and additional core definitions at the end, but don't
		// duplicate if already defined by a product

		return _.chain([systemContextEntry, ...productDefinedContexts, ...(deviceData.cores ?? [])])
			.uniqBy((c) => c.name)
			.value();
	}
}

// This returns all the contexts which need to be actually represented at runtime.  This means all
// contexts for which there is a script configuring it, or the lone context specified with 
// --context on the command line.  One runtime needs to be created for each one

export function getRuntimeContexts(products: Product[], deviceData: AdaptedDeviceInfo, resolvedArgs: ResolvedArgs): ContextInfo[] {

	const contexts = resolve(getCLIContextChoices(products, deviceData), deviceData);
	if (resolvedArgs.showAllContexts) {
		return contexts;
	}

	// Extract all contexts specified on the command line

	const contextNames = _.map(resolvedArgs.script, (scriptArgs) => scriptArgs.context);
	return _.filter(contexts, (c) => _.includes(contextNames, c.name));
}

// This filters out products that do not indicate they support the current context.
// It will always filter out fake products added to support loading from the .syscfg as they should not participate in
// migration

export function filterProductsByContext<T extends Product>(products: T[], context: string, deviceData: AdaptedDeviceInfo) {
	return _.chain(products)
		.reject((product) => product.file.name === scriptDirProductName)
		.filter((product) => _.some(getProductContexts([product.file.contexts], deviceData), (c) => c.name === context))
		.value();
}

export function getDefaultContext(products: NamedProduct[], device: { deviceId: string }): string {
	// We want to use the first context in the array at the appropriate device entry in product.json as the default.
	// However, if not every product agrees with that, then the "system" context is used instead

	const firstContexts = _.chain(products)
		.filter((p) => p.file.name !== scriptDirProductName)
		.map((p) => _.first(getProductContexts([p.file.contexts], device)))
		.uniq()
		.value();

	if (_.size(firstContexts) === 1) {
		return _.first(firstContexts).name;
	}
	return systemContextEntry.name;
}

// This combines the contexts from multiple products together

function getProductContexts(
	contextsMaps: ProductContextsMap[],
	deviceData: AdaptedDeviceInfo | DeviceDescription | { deviceId: string }
): Named[] {

	// Find the entry in each contexts map that matches the current device

	const deviceName = getName(deviceData);
	const contexts = _.chain(contextsMaps)
		.compact()
		.flatMap((c) => _.find(c, (_value, key) => new RegExp(key).test(deviceName)))
		.compact()
		.map((c) => _.isString(c) ? { name: c } : c) 		// allow string short form
		.uniqBy((c) => c.name) 								// remove duplicates
		.value();

	return _.isEmpty(contexts) ? [systemContextEntry] : contexts;
}

// This resolves contexts defined in products with data from the deviceData
// If the FULL device data was passed in, then we can upgrade the returned type to be ContextInfo

function resolve(
	contexts: Named[],
	device: AdaptedDeviceInfo,
): ContextInfo[];
function resolve(
	contexts: Named[],
	device: DeviceDescription,
): Named[];
function resolve(
	contexts: Named[],
	device: AdaptedDeviceInfo | DeviceDescription,
): ContextInfo[] {

	return _.map(contexts, (context) => {
		const deviceCore = _.find(device.cores, (core) => core.name === context.name);
		if (deviceCore) {
			return {
				...deviceCore,
				...context,
			};
		}
		return context;
	});
}

function getName(deviceData: AdaptedDeviceInfo | DeviceDescription | { deviceId: string }) {
	return (deviceData as AdaptedDeviceInfo).device ??
		(deviceData as DeviceDescription).name ??
		(deviceData as { deviceId: string }).deviceId;
}

// These replacement types are to enable the above functions to use the expected type, but then be
// able to call them with simpler types for testing

type Product = { file: Pick<RealProduct["file"], "contexts" | "name"> };
type NamedProduct = { file: Pick<RealProduct["file"], "contexts" | "name"> };
type AvailableProductInfo = Pick<RealAvailableProductInfo, "contexts">;
type AdaptedDeviceInfo = Pick<RealAdaptedDeviceInfo, "cores" | "device">;
type DeviceDescription = Pick<RealDeviceDescription, "cores" | "name">;

const systemContextEntry = {
	name: systemContext,
	description: "Settings that affect the entire system",
};

