import * as _ from "lodash";
// This file contains the legacy data structures that were used by pinmux.  We
// still have them maintained so that we can read in legacy .pinmux files.  

// DO NOT ADD TO OR RENAME ANYTHING IN THIS FILE!
// Removing things is fine - it means we don't need that definition to properly
// read legacy pinmux files

import { Const } from "../utils";
import { ConfigurableValue } from "solutionObj";

/**
 * Used by the solver to indicate the state of each PinRequirement
 * @returns
 */
class LegacySolution {

	public nameDecoratorText = "";
	public assignedToName = "";
	public errorText = "";
	public warningText = "";
	public errorDetailsText: string[] = [];
	public warningDetailsText: string[] = [];
	public errorCount = 0;
	public warningCount = 0;
	public nonSolverErrorCount = 0;
	public gpioPinsUsed?: number;
	public gpioPinsTotal?: number;
	public ioSet?: string;
	// summary view state, does not need to be serialized/deserialized
	public isExpanded?: boolean;
}

class LegacyDevicePinSolution extends LegacySolution {
	public requirementName = "";
	public requirementId = "";
	public interfacePin = "";
}

/**
 * Abstract requirement
 */
class LegacyAbstract {
	public used: boolean;
	public solution: LegacySolution;
	public nonSolverSolution: LegacySolution;
	constructor(copy?: LegacyAbstract) {
		if (copy) {
			this.used = copy.used;
			this.solution = copy.solution;
			this.nonSolverSolution = copy.nonSolverSolution;
		} else {
			this.used = true;
			this.solution = new LegacySolution();
			this.nonSolverSolution = new LegacySolution();
		}
	}
}

/**
 * Abstract Pin Requirement
 * @returns
 */
class LegacyAbstractPin extends LegacyAbstract {

	public readonly type: string;
	public assignedToName: string = Const.ANY;

	// is it possible to remove this requirement
	public removable = false;
}

const enum PinType {
	MULTIPIN = "Multi",
	SINGLEPIN = "Single",
}

export function isMultiPin(pin: LegacyPin | LegacyMultiPin): pin is LegacyMultiPin {
	return pin.type === PinType.MULTIPIN;
}

/**
 * Single Pin Requirement
 * @returns
 */
interface LegacyInterfacePin {
	name: string;
}

interface LegacyUseCasePin {
	name: string;
	interfacePin: LegacyInterfacePin;
}

export class LegacyPin extends LegacyAbstractPin {

	public override readonly type: string = PinType.SINGLEPIN;
	public override used = true;
	public readonly name: string;
	public readonly interfacePinName: string;
	public configurables?: { [key: string]: ConfigurableValue };
	public configOptions?: { [key: string]: ConfigurableValue }; // legacy name for configurables 

	constructor(useCasePin: LegacyUseCasePin) {
		super();
		this.name = useCasePin.name;
		this.interfacePinName = useCasePin.interfacePin.name;
	}
}

/**
 * MultiPinRequirement 
 * @param count
 * @param selected
 * @param interfacePins
 * @pdevicePinNamescePins
 * @param selectedDevicePins
 * @returns
 */
export class LegacyMultiPin extends LegacyAbstractPin {

	public override readonly type: string = PinType.MULTIPIN;
	public override used = true;
	public override assignedToName: string = Const.ANY;
	public override solution = new LegacySolution();
	public count: number;
	public defaultCount: number;
	public pinRequirements: LegacyPin[];

	constructor(count: number, pinRequirements: LegacyPin[]) {
		super();
		this.defaultCount = count; // count specified in the use case
		this.pinRequirements = pinRequirements;
		this.count = count;
	}

}

/**
 *  Peripheral requirement
 * @param name
 * @returns
 */
export class LegacyPeripheral extends LegacyAbstract {
	// The "name" could actually be changed at any time by the user. 
	// Thus, we need to keep an id for tracking that is constant.
	public id: string;
	public name: string;

	// The name/id of the user-level requirement that added this peripheral
	// requirement.  For an interface requirement, it would be just the 
	// peripheral requirement, but for the GPIO requirement, it would point to
	// the higher-level GPIO requirement etc.
	// The name could be better, but changing it would require a new version of
	// the pinmux data format.  So for now, I'm leaving this named poorly
	public parentReqName: string;
	public parentReqID: string;

	public selectedInstance: string = Const.ANY;
	public selectedVoltage: string = Const.ANY;
	public selectedUseCase: string = null;
	public configurables?: { [key: string]: ConfigurableValue };
	public configOptions?: { [key: string]: ConfigurableValue }; // legacy name for configurables
	public pinConfigurablesHeader?: { [key: string]: ConfigurableValue };
	public isNameInvalid?: boolean;
	public removable?: boolean;
	public pinRequirements: (LegacyPin | LegacyMultiPin)[] = [];
	public peripheralSolution = new LegacySolution();
	public voltageSolution = new LegacySolution();
	public isNameValid = true;
	public assignedToName = "";

	// Specifies the name of the interface.
	// previously this was not needed because; we kept an interfaceRequirmentsMap
	// which grouped requirements by interfaces. We no longer keep that map; Instead
	// we group requirments into Requirement.BaseGroup which would allow us to mix
	// and match requirements across different interfaces to create "higher level requirements".
	// Note: The interfaceRequirementsMap is now created dynamically to satifsy the solver interface.
	public interfaceName: string;

	public requirementNameErrorMessage?: string;

	constructor(id: string, interfaceName: string);
	constructor(id: string, interfaceName: string, userReqID: string, userReqName: string)
	// The overloads mean that if you pass userReqId, you must pass userReqName
	// But tslint is confused and thinks it could be the same - hence disabling
	constructor(id: string, interfaceName: string, userReqID?: string, userReqName?: string) {
		super();
		this.id = id;
		this.name = id;
		this.interfaceName = interfaceName;

		if (userReqID && userReqName) {
			this.parentReqName = userReqName;
			this.parentReqID = userReqID;
		}
	}
}

interface LegacyBaseGroupMap {
	[s: string]: LegacyBaseGroup;
}

interface LegacyInterfaceGroupMap {
	[s: string]: LegacyInterfaceGroup;
}

interface LegacyPowerDomainSettings {
	[key: string]: string;
}

interface LegacyDevicePinSolutionMap {
	[key: string]: LegacyDevicePinSolution;
}

/**
 * Root object for capturing requirements
 * @returns
 */
export class LegacyDeviceV2 extends LegacyAbstract {

	public devicePinMap: LegacyDevicePinSolutionMap;
	public powerDomainSettings: LegacyPowerDomainSettings;
	public powerDomainSettingsEnabled: boolean;

	public isLoad: boolean;
	public isBoard: boolean;

	// "1.0.0" - Original Version
	// "2.0.0" - New version
	// 		   - Interface requirement switched to MultiPerpheral requirement
	//         - interfaceRequirementsMap removed, it is not serialized or de-serialized
	//         - Added requirements to track higher level MultiPerpheral requirements
	// "2.0.1" - Same as 2.0.0, but PMUX-1594 is fixed (empty gpio reqs are removed)	
	// high level group requirements
	public groupRequirements: LegacyBaseGroupMap;

	// when switching to 2.0.0; also fixed a typo, "verision" -> version
	// track requirements version
	public version: "2.0.0" | "2.0.1" = "2.0.1";

	constructor(legacyDevice?: LegacyDeviceV1, isStandardGPIO?: boolean) {
		super(legacyDevice);
		if (legacyDevice) {
			this.devicePinMap = legacyDevice.devicePinMap;
			this.powerDomainSettings = legacyDevice.powerDomainSettings;
			this.powerDomainSettingsEnabled = legacyDevice.powerDomainSettingsEnabled;
			this.isLoad = legacyDevice.isLoad;
			this.isBoard = legacyDevice.isBoard;
			this.groupRequirements = {};

			// interface requirement should be treated as a  group requirement
			_.each(legacyDevice.interfaceRequirementsMap, (groupRequirement, interfaceName) => {
				this.groupRequirements[interfaceName] = interfaceName === "GPIO" && isStandardGPIO ?
					loadLegacyStandardGPIO(groupRequirement, interfaceName) :
					loadLegacyNonStandardGPIO(groupRequirement, interfaceName);
			});
		} else {
			this.devicePinMap = {};
			this.powerDomainSettings = {};
			this.powerDomainSettingsEnabled = false;
			this.isLoad = false;
			this.isBoard = false;
			this.groupRequirements = {};
		}
	}
}

class LegacyDeviceV1 extends LegacyAbstract {
	public devicePinMap: LegacyDevicePinSolutionMap;
	public powerDomainSettings: LegacyPowerDomainSettings;
	public powerDomainSettingsEnabled: boolean;

	public isLoad: boolean;
	public isBoard: boolean;

	// added for solver 
	// dynamically created when loading
	public interfaceRequirementsMap: LegacyInterfaceGroupMap;

	public verision: "1.0.0" = "1.0.0";

	constructor(device: LegacyDeviceV2) {
		super(device);
		this.devicePinMap = device.devicePinMap;
		this.powerDomainSettings = device.powerDomainSettings;
		this.powerDomainSettingsEnabled = device.powerDomainSettingsEnabled;
		this.isLoad = device.isLoad;
		this.isBoard = device.isBoard;
		this.interfaceRequirementsMap = {};
		const groups = device.groupRequirements;
		_.chain(groups)
			.filter((group: LegacyBaseGroup) => group.requirements.length > 0)
			.each((group) => {
				let ifaceGroup: LegacyInterfaceGroup;
				if (isGPIOInterfaceGroup(group)) {

					ifaceGroup = new LegacyInterfaceGroup(group.name);
					ifaceGroup.used = group.used;
					ifaceGroup.solution = group.solution;
					ifaceGroup.nonSolverSolution = group.nonSolverSolution;
					ifaceGroup.requirements
						= _.reduce<LegacyGPIO, LegacyPeripheral[]>
							(group.requirements, (prev, gpioReq) => [...prev, ...gpioReq.requirements],
								[] as LegacyPeripheral[]);

				} else {
					ifaceGroup = group as LegacyInterfaceGroup;
				}

				this.interfaceRequirementsMap[ifaceGroup.name] = ifaceGroup;
			})
			.value();
	}
}

/**
 * Group of requirements.
 * @param name
 * @returns
 */
class LegacyGBaseGroup<T> extends LegacyAbstract {

	public name: string;
	public id: string;
	public requirementNameErrorMessage?: string;
	public requirementsNameIndex = 1;
	public requirements: T[] = [];

	constructor(pname: string) {
		super();
		this.name = pname;
		this.id = pname;
	}
}

type LegacyBaseGroup = LegacyInterfaceGroup | LegacyGPIOInterfaceGroup;

export class LegacyGPIO extends LegacyAbstract {

	public pinConfigurablesHeader: { [key: string]: ConfigurableValue };
	public requirementNameErrorMessage?: string;
	public requirementsNameIndex = 1;
	public requirements: LegacyPeripheral[] = [];
	public configurables: { [key: string]: ConfigurableValue };

	// This used to keep track of the number of pins independent of 
	// requirements.length.  We now only use it for isGPIOInterfaceGroup, but
	// can't switch until we get rid of legacy pinmux files.  So it's now 
	// readonly and forced to be 0

	public readonly numOfGPIOPins: 0 = 0;

	public name: string;
	public id: string;
	constructor(pname: string) {
		super();
		this.name = pname;
		this.id = pname;
	}
}

class LegacyInterfaceGroup extends LegacyGBaseGroup<LegacyPeripheral> {
}

class LegacyGPIOInterfaceGroup extends LegacyGBaseGroup<LegacyGPIO> {
}

export function isGPIOInterfaceGroup(group: LegacyBaseGroup): group is LegacyGPIOInterfaceGroup {
	if (!group.requirements.length) {
		throw new Error("Can't differentiate between Group types without looking at child requirments");
	}
	return typeof (group.requirements[0] as LegacyGPIO).numOfGPIOPins !== "undefined";
}

function uniqueInternalReqName(parent: LegacyBaseGroup | LegacyGPIO) {
	return parent.id + "_intenal_" + parent.requirementsNameIndex++;
}

function adaptLegacyGPIOPeripheralRequirement(peripheralRequirement: LegacyPeripheral, interfaceName: string) {

	// the interface name for the perpheral name can no longer be deferred from the groupRequirement
	// this will allow us to mix perpheral requirements across interfaces

	peripheralRequirement.interfaceName = interfaceName;

	return peripheralRequirement;
}

function loadLegacyNonStandardGPIO(groupRequirement: LegacyInterfaceGroup, interfaceName: string) {

	// requirement it self now has an id and name, this was previously infered from the key
	// which was the interface name
	groupRequirement.name = interfaceName;
	groupRequirement.id = interfaceName;

	_.each(groupRequirement.requirements, (peripheralRequirement) => {
		peripheralRequirement = adaptLegacyGPIOPeripheralRequirement(peripheralRequirement, interfaceName);
	});

	return groupRequirement;
}

function loadLegacyStandardGPIO(groupRequirement: LegacyInterfaceGroup, interfaceName: string) {

	// root level requirement for all GPIO reqs
	const rootGroupRequirement = new LegacyGPIOInterfaceGroup(interfaceName);

	_.each(groupRequirement.requirements, (peripheralRequirement) => {

		peripheralRequirement = adaptLegacyGPIOPeripheralRequirement(peripheralRequirement, interfaceName);

		// each peripheral requirement will now need to be grouped in a parent group requirement
		const parentGroupRequirement = new LegacyGPIO(peripheralRequirement.name);
		parentGroupRequirement.id = peripheralRequirement.id;

		// assign the perpheralRequirment an internal id
		peripheralRequirement.id = uniqueInternalReqName(parentGroupRequirement);
		peripheralRequirement.name = peripheralRequirement.id;

		peripheralRequirement.parentReqName = parentGroupRequirement.name;
		peripheralRequirement.parentReqID = parentGroupRequirement.id;
		parentGroupRequirement.requirements.push(peripheralRequirement);

		rootGroupRequirement.requirements.push(parentGroupRequirement);
		rootGroupRequirement.requirementsNameIndex++;

	});

	return rootGroupRequirement;
}

function adaptPowerDomainSettings(deviceRequirement: LegacyDeviceV1) {
	// the power domain work flow has changed, we now support an enable disabled button
	// we need to ensure that we gracefully handle saved files from before this change
	if (deviceRequirement.powerDomainSettings) {
		// legacy case
		if (typeof deviceRequirement.powerDomainSettingsEnabled === "undefined") {
			deviceRequirement.powerDomainSettingsEnabled = true;
		}
	} else {
		deviceRequirement.powerDomainSettingsEnabled = false;
		deviceRequirement.powerDomainSettings = {};
	}

	return deviceRequirement;
}

// To validate we run through the requrirments.
function validate(deviceRequirement: LegacyDeviceV2) {

	interface GroupOrPeripheral {
		id: string;
		requirements?: GroupOrPeripheral[];
	}

	const ids: { [key: string]: GroupOrPeripheral } = {};

	// eslint-disable-next-line prefer-arrow/prefer-arrow-functions
	function validateRequirement(requirement: GroupOrPeripheral) {

		const existingObj = ids[requirement.id];
		if (existingObj) {
			// conflict
			throw new Error("Conflicting ID -> " + requirement.id);
		}

		ids[requirement.id] = requirement;

		_.each(requirement.requirements, (childRequirement) => {
			validateRequirement(childRequirement);
		});

	}

	// validate that all the id's are unique
	_.map(deviceRequirement.groupRequirements, (requirement) => {
		validateRequirement(requirement);
	});
}

function isLegacy(deviceRequirement: LegacyDeviceV2 | LegacyDeviceV1): deviceRequirement is LegacyDeviceV1 {
	const version = (deviceRequirement as any as LegacyDeviceV2).version;
	return version !== "2.0.1" && version !== "2.0.0";
}

function mayHaveEmptyGPIOReqs(deviceRequirement: LegacyDeviceV2) {
	const version = deviceRequirement.version;
	return version !== "2.0.1";
}

// migrate legacy requirements
export function Adapt(deviceRequirement: LegacyDeviceV2 | LegacyDeviceV1, isStandardGPIO: boolean) {

	if (isLegacy(deviceRequirement)) {
		adaptPowerDomainSettings(deviceRequirement);
		deviceRequirement = new LegacyDeviceV2(deviceRequirement, isStandardGPIO);
	} else if (mayHaveEmptyGPIOReqs(deviceRequirement)) {
		deviceRequirement.version = "2.0.1";
		if (isStandardGPIO) {
			deviceRequirement.groupRequirements.GPIO.requirements =
				_.filter(deviceRequirement.groupRequirements.GPIO.requirements as LegacyGPIO[],
					(req) => !_.isEmpty(req.requirements));
		}
	}

	// validate
	validate(deviceRequirement);
	return deviceRequirement;
}
