import * as _ from "lodash";
import {
	EnumerationOption,
	DisplayFormat,
	EnumerationConfigurableBase,
	DisabledOption,
	NumberDynamicEnumerationConfigurable,
	NumberEnumerationConfigurable,
	NumberMultiValueDynamicEnumerationConfigurable,
	NumberMultiValueEnumerationConfigurable,
} from "public/defs";
import { RuntimeObject } from "public/runtime";
import { FormattersMap } from "../../formatting/formattersMap";
import { getOldMemberMgr, getOldModInstMgr } from "../../migration/migrateUtils";
import { formatNumStr, getRadix, getAdvancedDisplayFormatOptions } from "../../numberUtils";

import { AObjectMgr } from "../object";
import { IOptions } from "../options";
import { Validations } from "../validations";
import { ConfigurableMgr } from "./configurableMgr";

export abstract class BaseEnumerationConfigurableMgr<
	Type extends number | string = string,
	Value extends Type | Type[] = Type,
	RuntimeObjectType extends RuntimeObject = RuntimeObject,
	DefType extends EnumerationConfigurableBase<Type, Value> = EnumerationConfigurableBase<Type, Value>>
	extends ConfigurableMgr<Value, RuntimeObjectType, DefType>
	implements IOptions<Type> {

	protected legacyNamesMap = new Map<Type, Type>();

	constructor(
		parentObjectMgr: AObjectMgr<RuntimeObjectType>,
		formattersMap: FormattersMap,
		def: DefType,
	) {
		super(
			parentObjectMgr,
			formattersMap,
			def,
		);
		this.createLegacyNamesMap();
	}

	public getUIOptions() {
		const optionsByName = this.getOptionsByName();
		const { enabledOptions, disabledOptions } = this.getOptions(optionsByName);

		const disabledDropDownOpts = _.map(disabledOptions, (o) => {
			const opt = optionsByName[_.toString(o.name)];
			return { ...opt, description: o.reason };
		});

		const displayFormat = isNumberEnumerationConfigurable(this.def) ? this.def.displayFormat : null;
		return {
			disabledOptions: toDropDownOptions(disabledDropDownOpts, displayFormat),
			enabledOptions: toDropDownOptions(enabledOptions, displayFormat),
		};
	}

	public getCLIOptions() {
		const { enabledOptions, disabledOptions } = this.getOptions(this.getOptionsByName());
		return {
			enabledOptions: _.map(enabledOptions, (o) => o.name),
			disabledOptions,
		};
	}

	public override getUIHash(validations: Validations): string {
		if (this.def.getDisabledOptions) {
			return undefined;
		}
		return super.getUIHash(validations);
	}

	protected abstract getOptions(
		optionsByName: {
			[name: string]: EnumerationOption<Type>,
		},
	)
		: {
			disabledOptions: DisabledOption<Type>[],
			enabledOptions: EnumerationOption<Type>[],
		};

	protected abstract getOptionsByName(): { [name: string]: EnumerationOption<Type> };

	protected override formatInvalidValue(value: unknown): string {
		const { modInstMgr, memberPath } = this.parentObjectMgr.getContainingModule();
		const copyPath = [...memberPath, this.def.name];
		const oldModMgr = getOldModInstMgr(modInstMgr);
		if (oldModMgr) {
			const memberMgr = getOldMemberMgr(oldModMgr, copyPath);
			if (memberMgr instanceof BaseEnumerationConfigurableMgr) {
				const options = memberMgr.getDropdownOptions();
				if (options) {
					return _.find(options, (o) => o.name === value)?.displayName;
				}
			}
		}
		return null;
	}

	protected createLegacyNamesMap() {
		const options = this.getOptionsByName();
		// create map with legacy names
		_.each(options, (o) => {
			_.each(o.legacyNames, (legacyName) => {
				this.legacyNamesMap.set(legacyName, o.name);
			});
		});
	}

	private getDropdownOptions() {
		return this.getUIOptions().enabledOptions;
	}

}

export function isNumberEnumerationConfigurable(def: any)
	: def is NumberEnumerationConfigurable | NumberDynamicEnumerationConfigurable |
	NumberMultiValueDynamicEnumerationConfigurable | NumberMultiValueEnumerationConfigurable {
	return !!(def as NumberEnumerationConfigurable | NumberMultiValueEnumerationConfigurable |
		NumberDynamicEnumerationConfigurable |
		NumberMultiValueDynamicEnumerationConfigurable).displayFormat;
}

export function verifyOptionTypes<T extends string | number>(
	options: EnumerationOption<T>[]) {

	// Validate options are all the same type

	const nameTypes = _.uniqBy(options, (o) => typeof o.name);
	if (nameTypes.length > 1) {
		throw new Error("Option names must be of the same type.");
	}
}

export function unknownOptionError<T extends number | string>(val: T, validOptions: T[]) {
	throw new Error(`No option named ${val} defined, valid options are\n${validOptions.join("\n")}`);
}

// Convert options to always have a string-based name 
// also format numeric enum values and use that as displayName if none is provided

export function toDropDownOptions<T extends string | number>(
	options: (EnumerationOption<T>)[], displayFormat?: DisplayFormat) {
	return _.map(options, (o) => {
		if (_.isNumber(o.name) && !o.displayName) {
			const nameAsString = formatNumStr(o.name.toString(), getRadix(displayFormat), {
				bitSize: getAdvancedDisplayFormatOptions("bitSize", displayFormat),
				fixedPoint: getAdvancedDisplayFormatOptions("fixedPoint", displayFormat),
			});
			return { ...o, name: o.name.toString(), displayName: nameAsString };
		} else {
			return { ...o, name: o.name.toString() };
		}
	});
}

export function validateDisabledOptions<T extends { reason: string }>(
	disabledOptions: T[], member: string, ensureExists: (option: T) => void) {
	if (!_.isArray(disabledOptions)) {
		throw new Error(`${member}: non-array returned from getDisabledOptions`);
	}
	_.each(disabledOptions, (o) => {
		ensureExists(o);
		if (_.isEmpty(o.reason) || !_.isString(o.reason)) {
			throw new Error(`${member}: attempted to disable option without valid reason`);
		}
	});

}
