
const isValid = require("date-fns/isValid");
import { DateConfigurable } from "public/defs";
import { RuntimeObject } from "public/runtime";
import { FormattersMap } from "../../formatting/formattersMap";
import { SerializationOptions } from "../../scripting/toScript";
import { AObjectMgr } from "../object";
import { ConfigurableMgr } from "./configurableMgr";

// The tool always serializes UTC ISO formatted dates. Similarly, the assumption
// is the user is picking UTC+0 date from the GUI.
export class DateConfigurableMgr extends ConfigurableMgr<Date> {

	constructor(
		parentObjectMgr: AObjectMgr<RuntimeObject>,
		formattersMap: FormattersMap,
		public override readonly def: DateConfigurable,
	) {
		super(parentObjectMgr, formattersMap, def);
	}

	public override getScriptValue() {
		// Time is not important, we can trim that part out for readability
		const strVal = this.value.toISOString().split("T")[0];
		const scriptValue =
			`new Date("${strVal}")`;
		return {
			value: scriptValue,
			shouldQuoteStrings: false,
		};
	}

	public override shouldSerialize(options: SerializationOptions) {
		return (!this.def.nonSerializable || options.includeNonSerializable)
			&& !this.def.deprecated && !this.isCalculated();
	}

	protected override validateValue(val: Date) {
		if (!isValid(val)) {
			this.typeMismatch("Date", typeof val);
		}
	}
}
