import * as _ from "lodash";
// Contains interfaces and utility functions related to serialization.
import { SomeInterfaceInstanceMgr, InterfaceMgr } from "../instanceContainers/interface";
import { ModuleMgr } from "../instanceContainers/module";
import { Member as MemberDef } from "public/defs";
import { SourceLocation } from "public/runtime";
import { StaticModuleInstanceMgr } from "../objectManagers/staticModuleInstance";
import { ModuleInstanceMgr } from "../objectManagers/moduleInstance";

export class BlockComment {
	public readonly type = "blockComment";
	constructor(public readonly comment: string) { }
}

export class BlankLine {
	public readonly type = "blankLine";
}

export class FunctionCall {
	public readonly type = "functionCall";
	constructor(public readonly value: string) { }
}

export class Assignment {
	public readonly type = "assignment";
	constructor(public readonly lvalue: string, public readonly rvalue: string) { }
}

export type Statement = BlockComment | BlankLine | FunctionCall | Assignment;

export class SuggestedSolutionAssignment extends Assignment { }
export class ValidationStatement extends FunctionCall { }
export class BoosterPackAssignment extends Assignment {
	constructor(lvalue: string, rvalue: string, public readonly source: SourceLocation) {
		super(lvalue, rvalue);
	}
}

export function createAddInterfaceInstanceStatement(
	inst: SomeInterfaceInstanceMgr, rootIdentifier: string): Assignment {
	const interfaceName = inst.managedObject.$interface.name;
	const lvalue = `const ${rootIdentifier}`;
	const rvalue = `scripting.addPeripheral("${interfaceName}")`;
	return new Assignment(lvalue, rvalue);
}

export function createAddModuleInstanceStatement(instIdentifier: string, modIdentifier: string, userCreated: boolean) {
	const lvalue = `const ${instIdentifier}`;
	const rvalue = userCreated ? `${modIdentifier}.addInstance()` : `${modIdentifier}.addInstance({}, false)`;
	return new Assignment(lvalue, rvalue);
}

export function createAddModuleStatement(mod: ModuleMgr, userCreated: boolean) {
	const identifier = mod.getScriptIdentifier();
	const lvalue = `const ${identifier}`;
	const rvalue
		= userCreated ?
			`scripting.addModule("${mod.module.$name}")` : `scripting.addModule("${mod.module.$name}", {}, false)`;
	return new Assignment(lvalue, rvalue);
}

export function createModuleInstanceFindStatement(instIdentifier: string, $name: string) {
	const lvalue = `const ${instIdentifier}`;
	const rvalue = `system.clockTree["${$name}"]`;
	return new Assignment(lvalue, rvalue);
}

export function getBPVariableName(source: SourceLocation) {
	if (validDotNotationRegex.test(source.name)) {
		return source.name;
	} else {
		// Strip all invalid characters

		const name = source.name.replace(/[^a-zA-Z_$0-9]*/g, "");
		if (validDotNotationRegex.test(source.name)) {
			return name;
		} else {
			// must start with a number

			return `bp_${name}`;
		}
	}
}

export function createAddComponentStatement(source: SourceLocation) {
	const lvalue = `const ${getBPVariableName(source)}`;
	const param2 = source.attachedTo ? `, "${source.attachedTo}"` : "";
	const rvalue = `scripting.addHardware("${source.definition}"${param2})`;
	return new BoosterPackAssignment(lvalue, rvalue, source);
}

export function quoteStrings(val: any) {
	if (typeof val === "string") {
		return "\"" + val.replace(/\\/g, "\\\\") + "\"";
	}
	return val;
}

// A reasonable regex to determine weather to use obj.<key> or obj[<key>] notation
const validDotNotationRegex = /^[a-zA-Z_$][a-zA-Z_$0-9]*$/;

// Create a full identifier for child by extending parent identifier.
// If possible, use dot notation. Otherwise, use index ([]) notation. 
export function createChildIdentifier(parentIdentifier: string, childIdentifier: string | number) {

	let suffix: string;

	if (typeof childIdentifier === "number") {
		suffix = `[${childIdentifier}]`;
	} else if (validDotNotationRegex.test(childIdentifier)) {
		suffix = `.${childIdentifier}`;
	} else {
		suffix = `["${childIdentifier}"]`;
	}

	return `${parentIdentifier}${suffix}`;
}

function createMemberValueAssignmentArgs(
	def: Pick<MemberDef, "name">,
	rootIdentifier: string,
	val: any,
	options: {
		shouldQuoteStrings?: boolean,
		forceWrite?: boolean,
		invalidAssignment?: string,
		memberPath?: string[],
		oldDisplayName?: string,
	} = { shouldQuoteStrings: true },
) {

	let { shouldQuoteStrings } = options;
	const { forceWrite, invalidAssignment, memberPath, oldDisplayName } = options;

	shouldQuoteStrings = typeof shouldQuoteStrings === "undefined" ? true : shouldQuoteStrings; // default to true

	const lvalue = createChildIdentifier(rootIdentifier, def.name);
	let value = shouldQuoteStrings ? quoteStrings(val) : val;
	value = forceWrite ? `scripting.forceWrite(${value})` : value;
	if (invalidAssignment) {
		value = _.isEmpty(memberPath) ?
			`scripting.invalidAssignment(${value}, "${invalidAssignment}"` :
			`scripting.invalidAssignment(${value}, "${invalidAssignment}", ["${memberPath.join("\", \"")}"]`;
		if (!memberPath && oldDisplayName) {
			// need to pass in empty array for memberPath
			value = value + `, [], \"${oldDisplayName}\"`;
		} else if (oldDisplayName) {
			value = value + `, \"${oldDisplayName}\"`;
		}
		value = value + ")";
	}

	return { lvalue, value };
}

export function createMemberValueAssignmentStatement(
	def: Pick<MemberDef, "name">,
	rootIdentifier: string,
	val: any,
	options: {
		shouldQuoteStrings?: boolean,
		forceWrite?: boolean,
		invalidAssignment?: string,
		memberPath?: string[],
		oldDisplayName?: string,
	} = { shouldQuoteStrings: true },
) {

	const { lvalue, value } = createMemberValueAssignmentArgs(def, rootIdentifier, val, options);
	return new Assignment(lvalue, value);
}

export function createMemberValueSuggestedSolutionStatement(
	def: MemberDef,
	rootIdentifier: string,
	val: any,
	options: {
		shouldQuoteStrings?: boolean,
	} = { shouldQuoteStrings: true },
) {

	const { lvalue, value } = createMemberValueAssignmentArgs(def, rootIdentifier, val, options);
	return new SuggestedSolutionAssignment(lvalue, value);
}

export function createModuleInstanceArrayCreateStatement(
	def: MemberDef,
	rootIdentifier: string,
	val: number,
) {
	const childId = createChildIdentifier(rootIdentifier, def.name);
	return new FunctionCall(`${childId}.create(${val})`);
}

export function createValidationSuppressionStatement(
	rootIdentifier: string,
	matcher: string,
	def?: Pick<MemberDef, "name">,
) {
	return def ? new ValidationStatement(
		`scripting.suppress(${quoteStrings(matcher)}, ${rootIdentifier}, ${quoteStrings(def.name)})`,
	) : new ValidationStatement(
		`scripting.suppress(${quoteStrings(matcher)}, ${rootIdentifier})`,
	);
}

export function createFileOwnershipStatement(filename: string) {
	return new FunctionCall(`scripting.excludeFromBuild(${quoteStrings(filename)})`);
}

// Tracks and provides coordination (shared state) between entities being serialized
export class SerializationContext {

	private readonly modulesAdded = new Set<StaticModuleInstanceMgr | ModuleInstanceMgr>();
	private readonly moduleIdentifiers = new ScriptIdentifiers();
	private readonly moduleInstanceIdentifiers = new Map<ModuleInstanceMgr, string>();

	public getModulesAdded() {
		return this.modulesAdded;
	}

	public getModuleIdentifiers() {
		return this.moduleIdentifiers;
	}

	public getModuleInstanceIdentifiers() {
		return this.moduleInstanceIdentifiers;
	}
}
type Mgr = InterfaceMgr | ModuleInstanceMgr | ModuleMgr;
// Track script identifiers for modules
class ScriptIdentifiers {
	private readonly identifierNameToUsed: { [identifier: string]: boolean } = {};
	private readonly idToScriptIdentifier = new Map<Mgr, string>();

	public getScriptIdentifiers(obj: Mgr, baseName: string) {
		if (!this.idToScriptIdentifier.has(obj)) {
			this.createScriptIdentifiers(obj, baseName);
		}
		return this.idToScriptIdentifier.get(obj);
	}

	private createScriptIdentifiers(obj: Mgr, baseName: string) {

		// try the short version
		let identifier = baseName;

		let startingIndex = 0;
		while (this.identifierNameToUsed[identifier]) {
			startingIndex++;
			identifier += "_";
			identifier += startingIndex;
		}
		this.idToScriptIdentifier.set(obj, identifier);
		this.identifierNameToUsed[identifier] = true;

		return identifier;

	}
}
