import * as _ from "lodash";
import * as data from "dataInterfaces";
import { SolutionMap } from "../choices";
import { AbstractChoice, AbstractErrorChoice, RelatedChoices, RelatedSharedChoices } from "./common";
import { SuggestedSolution } from "../suggestedSolution";
import { SharedCount } from "./sharedCount";
import { PeripheralConflictTracker } from "../conflictTracker";
import { ChoiceValidator } from "./choiceValidator";
import { chooseOneOf, mutuallyExcludeUnsharedChoices } from "../clauseGeneration";
import { Peripheral } from "../requirements";
import { updateSolution, clearSolution, addErrorToSolution } from "../../utils";
import { nameChoices, formatNameChoice } from "../debug";

// -----------------------------------------------------------------------------
// PeripheralChoices
// A factory for creating a choice of a specific peripheral to meet a 
// peripheral requirement.  Also eventually generates the clauses for all the 
// relationships of these choices
// -----------------------------------------------------------------------------

export class PeripheralChoices {
	public readonly sharedChoices: { [sharedHash: string]: PeripheralChoices.Choice[] } = {};
	private readonly byPeripheral = new RelatedSharedChoices<string, PeripheralChoices.Choice>();
	private readonly byRequirement = new RelatedChoices<string, PeripheralChoices.Choice>();
	private readonly errors: { [key: string]: PeripheralChoices.Error } = {};
	private readonly requirements: { [id: string]: Peripheral } = {};
	private readonly sharedCount = new SharedCount();

	constructor(
		private readonly choiceValidator: ChoiceValidator,
		private readonly suggestedSolution: SuggestedSolution,
		private readonly conflictTracker: PeripheralConflictTracker) { }

	public newChoice(peripheral: data.Peripheral, peripheralReq: Peripheral): PeripheralChoices.Choice {
		this.requirements[peripheralReq.id] = peripheralReq;

		if (!this.choiceValidator.isValid(peripheralReq, peripheral)) {

			// Ensure the key is added, so if no choices are valid, we still generate an error

			this.byRequirement.addKey(peripheralReq.id);
			return null;
		}

		const choice = new PeripheralChoices.Choice(peripheral, peripheralReq);
		this.byRequirement.get(peripheralReq.id).push(choice);

		if (this.conflictTracker.areConflictsAllowed(peripheralReq)) {

			// Add it under it's own unique category of shared pins

			const sharedHash = "allowedToConflict" + peripheralReq.userOverride;
			this.byPeripheral.get(peripheral.name).pushShared(choice, sharedHash);

		} else if (peripheralReq.canShareWith) {

			// Include the interface name in the key
			// Ensures we only share peripherals as the same interface

			let sharedHash = peripheralReq.canShareWith + peripheralReq.interfaceName;
			if (peripheralReq.maxShareCount) {
				sharedHash += peripheralReq.maxShareCount;
				_.times(peripheralReq.maxShareCount, (index) => this.sharedCount.newChoice(choice, peripheral.name, index));
			}
			this.byPeripheral.get(peripheral.name).pushShared(choice, sharedHash);
			this.sharedChoices[sharedHash] = this.sharedChoices[sharedHash] || [];
			this.sharedChoices[sharedHash].push(choice);
		} else {
			this.byPeripheral.get(peripheral.name).push(choice);
		}

		return choice;
	}

	public generateClauses() {
		const errorFetcher = (choiceName: string) => this.getError(choiceName);
		chooseOneOf(this.byRequirement, errorFetcher, "must choose one peripheral per requirement");
		mutuallyExcludeUnsharedChoices(this.byPeripheral, "a peripheral can only be chosen once, unless shared");
		this.sharedCount.generateClauses();
	}

	private getError(peripheralReqId: string) {
		if (peripheralReqId in this.errors) {
			return this.errors[peripheralReqId];
		}

		const assumeError = this.suggestedSolution ?
			this.suggestedSolution.containsError(this.requirements[peripheralReqId]) : false;

		const error = new PeripheralChoices.Error(this.requirements[peripheralReqId], assumeError);
		this.errors[peripheralReqId] = error;
		return error;
	}
}

export namespace PeripheralChoices {
	export class Choice extends AbstractChoice implements Choice {

		constructor(public readonly peripheral: data.Peripheral, public readonly peripheralReq: Peripheral) {
			super();

			if (nameChoices) {
				this.name = "Peripheral " + formatNameChoice(peripheralReq) + "->" + peripheral.name;
				if (peripheralReq.canShareWith) {
					this.name += " (shared as " + peripheralReq.canShareWith + ")";
				}
			}
		}

		public apply(solutionMap: SolutionMap) {
			updateSolution(this.peripheralReq.solution, this.peripheral.name);
			const perfs = solutionMap.peripherals[this.peripheral.name] || (solutionMap.peripherals[this.peripheral.name] = []);
			perfs.push(this.peripheralReq);
		}

		public getRequirementId() {
			return this.peripheralReq.id;
		}

		public getShareHash() {
			return this.peripheralReq.canShareWith;
		}

		public hasError() {
			return "" !== this.peripheralReq.solution.errorText;
		}
	}

	export class Error extends AbstractErrorChoice {
		constructor(private readonly peripheralReq: Peripheral, assumeError: boolean) {
			super(peripheralReq.id, false, assumeError);

			if (nameChoices) {
				this.name = "Resource conflict " + formatNameChoice(peripheralReq);
			}
			clearSolution(this.peripheralReq.solution);
		}

		public apply() {

			clearSolution(this.peripheralReq.solution);
			addErrorToSolution(this.peripheralReq.solution, "Resource conflict");

			// Clear the solution for all underlying pins

			for (const pinReq of this.peripheralReq.pinRequirements) {
				clearSolution(pinReq.solution);
			}
		}
	}
}
