import * as _ from "lodash";
import { writeOutputFiles, TemplateSelectionType } from "../pinmux/services/codeGeneration/codeGenerator";
import { runScripts } from "../pinmux/services/scripting/runScript";
import { printValidation } from "./printValidation";
import { ConsoleMessages } from "./consoleMessages";
import * as path from "path";
import { fs } from "../pinmux/services/fileSystem";
import { ErrorStore } from "../pinmux/services/errorStore";
import { ValidationStatus } from "public/test";
import { ipcfGenTemplateFunc } from "../pinmux/services/iarIPCFGen/ipcfGen";
import * as data from "dataInterfaces";
import { ResolvedArgs } from "../pinmux/services/args/argTypes";
import { processSerially } from "../solver_tests/processSerially";

export const enum ScriptStatus {
	SUCCESS = 0,
	ERROR,
	WARNING,
}

function logProgress(message: string, logger: ILogger, quiet?: boolean) {
	if (!quiet) {
		logger.info(message + "...");
	}
}

// There is an implicit precondition for this function:
// At least one of args.listGeneratedFiles or args.listReferencedFiles must be true.
export async function listOutput(
	resolvedArgs: ResolvedArgs,
	errorStore: ErrorStore,
	logger = new ConsoleLogger(),
) {
	// Since we use stdout to report the files, disable console logging in case the metacode is doing something dumb.

	const consoleMessages = new ConsoleMessages();
	consoleMessages.disable();
	const {
		listGeneratedFiles,
		listReferencedFiles,
	} = resolvedArgs;

	try {
		const sysConfig = await runScripts(resolvedArgs, errorStore, false);
		consoleMessages.enable();
		const listOption
			= (listGeneratedFiles && listReferencedFiles) ? "all"
				: listGeneratedFiles ? "generated" : "referenced";

		const allOutput = _.chain(sysConfig.getRuntimes())
			.flatMap((runtime) => {
				const script = runtime.getCurrentScript().get();
				if (script) {
					const { output } = _.find(resolvedArgs.script, (scriptArgs) => scriptArgs.script?.path === script);
					if (output) {
						return runtime.getOutputFiles(listOption, output);
					}
				}
				return [];
			})
			.uniq()
			.join("\n")
			.value();
		logger.log(allOutput, false);
		return ScriptStatus.SUCCESS;
	} finally {
		consoleMessages.enable();
	}
}

function generateIPCF(
	templates: data.CodeGenTemplateFile[],
	referencedFiles: data.ReferenceFile[],
	outputDir: string,
	logger: ConsoleLogger,
	ipcfName: string,
) {
	logProgress("Generating ipcf file", logger);
	const ipcfContent = ipcfGenTemplateFunc(templates, referencedFiles);
	fs.mkdir(outputDir, { recursive: true });
	fs.writeFile(path.join(outputDir, ipcfName), ipcfContent);
}

function toScriptStatus(validationStatus: ValidationStatus) {
	switch (validationStatus) {
		case "error":
			return ScriptStatus.ERROR;
		case "warning":
			return ScriptStatus.WARNING;
		case "success":
			return ScriptStatus.SUCCESS;
		default:
			throw new Error(`Unknown validation status "${validationStatus}"`);
	}
}

export async function generateOutput(
	resolvedArgs: ResolvedArgs,
	errorStore: ErrorStore,
	logger = new ConsoleLogger(),
) {
	let status: ScriptStatus;
	logProgress("Running script", logger, resolvedArgs.quiet);
	const sysConfig = await runScripts(resolvedArgs, errorStore);

	logProgress("Validating", logger, resolvedArgs.quiet);
	const validationStatus = printValidation(sysConfig, logger);
	status = toScriptStatus(validationStatus);

	if (resolvedArgs.treatWarningsAsErrors && status === ScriptStatus.WARNING) {
		logger.log("Treating build as a failure due to --treatWarningsAsErrors", true);
		status = ScriptStatus.ERROR;
	}

	await processSerially(sysConfig.getRuntimes(), async (runtime) => {
		const script = runtime.getCurrentScript().get();
		if (script) {
			const { output } = _.find(resolvedArgs.script, (scriptArgs) => scriptArgs.script?.path === script);
			if (output) {
				const codeGenerator = runtime.getCodeGenerator();
				const referencedFiles = runtime.getReferences();
				if (resolvedArgs.compiler === "iar") {
					generateIPCF(codeGenerator.getTemplates(), referencedFiles, output, logger, resolvedArgs.ipcf);
				}
				const templates = codeGenerator.getTemplates(false, TemplateSelectionType.ALL);
				if (!_.isEmpty(templates)) {
					logProgress(`Generating Code (${path.basename(script)})`, logger, resolvedArgs.quiet);
					fs.mkdir(output, { recursive: true });
					const generated = await codeGenerator.generateAll(templates);
					writeOutputFiles(output, generated, (message) => logProgress(message, logger, resolvedArgs.quiet));
				}
			}
		}
	});

	return status;
}

export interface ILogger {
	info(msg: string): void;
	log(msg: string, error: boolean): void;
}

class ConsoleLogger implements ILogger {
	public info(msg: string): void {
		console.log(msg); // eslint-disable-line no-console
	}
	public log(msg: string, error: boolean) {
		if (error) {
			console.error(msg);
		} else {
			console.log(msg); // eslint-disable-line no-console
		}
	}
}
