import * as _ from "lodash";
import { AdaptedDeviceInfo } from "dataInterfaces";
import { Product } from "../product/types";

// https://jira.itg.ti.com/browse/PMUX-2878
// The device CC2652RB was renamed to CC2652RB1FRGZ, but the radioconfig meta-content in SDKs 
// version 4.30 and earlier explicitly match the device name against a key in an object.  The only
// workaround is to explicitly change the name back
//
// We're doing a pick on AdaptedDeviceInfo only to make testing easier.  Assumption is that 
// an object of the full AdaptedDeviceInfo type would be passed by the normal code

export function handleLegacySDK(deviceData: Pick<AdaptedDeviceInfo, "device" | "deviceId">, products: Product[]) {
	if (deviceData.device === "CC2652RB1FRGZ" && _.some(products, isLegacyLPRFSDK)) {
		deviceData.deviceId = "CC2652RB";
	}
}

function isLegacyLPRFSDK(product: Product) {
	if (product.file.name === "simplelink_cc13x2_26x2_sdk") {
		const [major, minor] = _.split(product.file.version, ".");
		return _.toNumber(major) < 4 ||
			(_.toNumber(major) === 4 && _.toNumber(minor) <= 30);
	}
	return false;
}
