import * as _ from "lodash";
import { ILogger } from "./cli_core";
import { IFormatter, FormatStyle } from "../pinmux/services/formatting/formattingTypes";
import { ISummaryItem } from "../pinmux/services/summaryItems";
import { ValidationStatus } from "public/test";
import { SysConfig } from "../pinmux/services/sysConfig";

/**
 * Used by CLI to print out the validation results and return an appropriate process exit code.
 * Note: that the std error/out output from this function serves as an interface to the CCS problems view
 * @param sysConfig - Object whose validation results to print.
 * @param logger - Logger
 * @return Indicates weather error, warnings were output
 */
export function printValidation(
	sysConfig: SysConfig, logger: ILogger): ValidationStatus {

	const summaryItems = sysConfig.getSummaryItems();
	const groupedSummaryItems = _.groupBy(summaryItems, (item) => item.type);

	const numErrors = _.size(groupedSummaryItems.errors);
	const numWarnings = _.size(groupedSummaryItems.warnings);

	const formatter = sysConfig.getMessageFormatter({ style: FormatStyle.CLI });
	_.each(groupedSummaryItems.errors, (item) => printItem(item, "error", logger, formatter));
	_.each(groupedSummaryItems.warnings, (item) => printItem(item, "warning", logger, formatter));
	_.each(groupedSummaryItems.infos, (item) => printItem(item, "info", logger, formatter));

	const hasErrors = numErrors > 0;
	const hasWarnings = numWarnings > 0;

	if (hasErrors || hasWarnings) {
		logger.log(`${numErrors} error(s), ${numWarnings} warning(s)`, true);
	}

	if (hasErrors) {
		return "error";
	} else if (hasWarnings) {
		return "warning";
	} else {
		return "success";
	}
}

function printItem(item: ISummaryItem, type: "error" | "warning" | "info", logger: ILogger, formatter: IFormatter) {
	const output = `${type}: ${formatter(item.location)}: ${formatter(item.text)}`;
	logger.log(output, type === "error");
	_.each(item.details, (detail) => logger.log(`\t${formatter(detail)}`, type === "error"));
}
