import * as _ from "lodash";
import { AnyMemberMgr } from "../member";

interface ProxyTarget { [memberName: string]: AnyMemberMgr; }

export const managedUIStateProxyHandler: ProxyHandler<ProxyTarget> = {
	get: (target, key: Extract<PropertyKey, string>) => {
		if (target.hasOwnProperty(key) && !target[key].excludeFromInternalMaps()) {
			return target[key].getManagedUIState();
		} else if (key === "hasOwnProperty") {
			return (key2: string) => target.hasOwnProperty(key2) && !target[key2].excludeFromInternalMaps();
		} else if (key === "toString") {
			return () => ({}).toString();
		}
		return undefined;
	},

	set: () => {
		throw new TypeError("read only object");
	},

	ownKeys: (target) => {
		return _.chain(target)
			.keys()
			.reject((key) => target[key].excludeFromInternalMaps())
			.sortBy()
			.value();
	},

	has: (target, key: Extract<PropertyKey, string>) => {
		return target.hasOwnProperty(key) && !target[key].excludeFromInternalMaps();
	},

	defineProperty: () => {
		return false; // disallow
	},

	deleteProperty: () => {
		return false; // disallow
	},

	getOwnPropertyDescriptor: (target, key: Extract<PropertyKey, string>) => {
		if (target.hasOwnProperty(key) && !target[key].excludeFromInternalMaps()) {

			// Node won't let us return that it's not configurable, so instead we'll return 
			// getters/setters vs the raw value at least

			return {
				configurable: true,
				enumerable: true,
				get: () => target[key].getManagedUIState(),
				set: () => {
					throw new TypeError("read only object");
				},
			};
		}
		return undefined;
	},

	setPrototypeOf: () => {
		return false; // disallow
	},
};
