export async function preFetchForResponsiveUI(runtime: Runtime) {

	// createTabs will fetch the module manager for every top module.  That means, loading and 
	// running the meta-code for each module.  For some modules, that's expensive.  As a result, 
	// the UI appears to be hung during createTabs.

	// The long term solution is to refactor createTabs to not immediately require all top module
	// module managers.  But for now, this function requests the same data, so that it's 
	// immediately available when createTabs is actually called, but does so asynchronously.  That 
	// allows the UI to display a progress bar that will have time to redraw itself during the load

	if (!runtime.isCorePinmux()) {
		for (const moduleName of runtime.getTopModules().getModuleNames()) {
			await yieldToRendering();
			runtime.getModuleMgr(moduleName);
		}
	}
}

// Create the Tabs to show
export function createTabs(runtime: Runtime, hardwareMgr: HardwareMgr) {

	runtime.beginTabCreation();
	const preview = getPreview(runtime);
	const isCorePinmux = runtime.isCorePinmux();
	const tabs: Tab[] = [];
	const interfaces = _.values(runtime.getInterfaceMgrs());

	if (isCorePinmux) {

		const tab = new Tab(
			TabName.PERIPHERALS,
			getInitialSelectedInterfaceMgr(interfaces),
			interfaces,
			preview,
		);
		_.each(interfaces, (i) => i.setParentTab(tab));
		tabs.push(tab);

	} else {

		// This is slow for some modules, and it's synchronously for all top modules right here.  
		// If you fix this, please also delete preFetchForResponsiveUI() defined above

		const topModuleMgrs = _.map(runtime.getTopModules().getModuleNames(),
			(moduleName) => runtime.getModuleMgr(moduleName));

		if (!_.isEmpty(topModuleMgrs)) {
			const categories = runtime.getTopModules().getModuleCategories();
			const nodes = createModuleCategoryNodes(
				categories,
				runtime,
			);

			const tab = new Tab(
				TabName.SOFTWARE,
				getInitialSelectedModuleMgr(topModuleMgrs),
				nodes,
				preview,
			);
			_.each(nodes, (n) => n.setParentTab(tab));
			tabs.push(tab);
		}

		const categories = runtime.getTopModules().getClockTreeCategories();

		if (!_.isEmpty(categories)) {
			const nodes = createClockTreeCategoryNodes(
				categories,
				runtime,
			);

			const tab = new Tab(
				TabName.CLOCKTREE,
				getInitialIpInstanceMgr(nodes),
				nodes,
				preview,
			);
			_.each(nodes, (n) => n.setParentTab(tab));
			tabs.push(tab);
		}

		if (!runtime.getPinmuxUIOptions().hasNoPinmux) {

			// For meta content that is not device dependent (i.e used with the Other device)
			// it does not make sense to show the empty reservation tab. 
			if (!_.isEmpty(interfaces) && !runtime.getPinmuxUIOptions().hidePeripheralTab) {
				const tab = new Tab(
					TabName.RESERVATION,
					getInitialSelectedInterfaceMgr(interfaces),
					interfaces,
					preview,
				);
				_.each(interfaces, (i) => i.setParentTab(tab));
				tabs.push(tab);
			}

			const board = runtime.getDeviceData().board;
			if (board) {
				const hwNodes = createHWNodes(board, hardwareMgr);
				if (!_.isEmpty(hwNodes)) {
					const tab = new Tab(
						TabName.HARDWARE,
						hwNodes[0].getChildren()[0],
						hwNodes,
						preview,
					);
					_.each(hwNodes, (n) => n.setParentTab(tab));
					tabs.push(tab);
				}
			}
		}
	}

	// built-in power domains module

	if (runtime.hasPowerSettings() && !runtime.getPinmuxUIOptions().hasNoPinmux) {
		const systemSettingsModules = [runtime.getModuleMgr(powerDomainsModuleName)];
		tabs.push(
			new Tab(
				TabName.POWER,
				systemSettingsModules[0],
				systemSettingsModules,
				preview,
			),
		);
	}

	return tabs;
}

function createModuleCategoryNodes(
	categories: ModuleCategory[],
	runtime: Runtime,
	categoryParent: CategoryNode = null,
): CategoryNode[] {

	return (
		_.map(
			categories,
			(c) => {
				const id = c.displayName.replace(/\s+/g, "");
				const newCategory = new CategoryNode(id, c, categoryParent);
				newCategory.setChildren([
					..._.map(c.modules, (m) => {
						const mod = runtime.getModuleMgr(m);
						mod.setParentNode(newCategory);
						return mod;
					}),
					...createModuleCategoryNodes(c.categories, runtime, newCategory),
				]);
				return newCategory;
			},
		)
	);
}

function createClockTreeCategoryNodes(
	categories: TreeCategory[],
	runtime: Runtime,
	categoryParent: CategoryNode = null,
): CategoryNode[] {

	return (
		_.map(
			categories,
			(c) => {
				const id = c.displayName.replace(/\s+/g, "");
				const newCategory = new CategoryNode(id, c, categoryParent);
				newCategory.setChildren([
					..._.map(c.entries, (e) => new ClockTreeNode(e, newCategory, runtime)),
					...createClockTreeCategoryNodes(c.categories, runtime, newCategory),
				]);
				return newCategory;
			},
		)
	);
}

function createHWNodes(board: Board, hardwareMgr: HardwareMgr) {

	hardwareMgr.resetTreeNodes();

	const hwCategories = _.groupBy(board.components,
		(component) => getDisplayName(component.source, false));

	return (
		_.map(hwCategories, (components, displayName) => {

			const id = displayName.replace(/\s+/g, "");
			const categoryNode = new CategoryNode(id, { displayName, description: "Hardware components" }, null);

			// remove duplicates (alias entries)
			const children = _.map(_.uniq(components), (hwComponent) => {
				return new HardwareComponentMgr(hwComponent, hardwareMgr, false, categoryNode);
			});

			categoryNode.setChildren(children);
			return categoryNode;
		})
	);
}

// Represents a Tab in the left hand navigation
export class Tab {
	private readonly id: string; // test id
	private selection: SelectionInTab;
	private selectedNode: ITreeNode;
	constructor(
		private readonly title: TabName,
		initialSelectedNode: ITreeNode,
		private readonly nodes: ITreeNode[],
		private readonly preview: Preview,
	) {

		this.id = "tab" + title.replace(/\s/g, "");

		const selectedItem = initialSelectedNode.getSelectedMyListItem();
		this.setSelection(
			{
				treeNodePath: initialSelectedNode.getNodePath(),
				instanceId: selectedItem && selectedItem.getID(),
				memberPath: [],
			},
		);
	}

	public getTitle() {
		return this.title;
	}

	public getNodes(): ITreeNode[] {
		return this.nodes;
	}

	public getNodesFlat(): ITreeNode[] {
		return _.flatMap(this.nodes, (n) => flattenNode(n));
	}

	public setSelection(selection: SelectionInTab) {
		this.selectedNode = findAndExpandParents(this.nodes, selection.treeNodePath);
		this.selectedNode.setSelection(selection);
		this.selection = selection;
	}

	public getSelection(): SelectionInTab {

		// update the node selection part, in-case it has changed
		// due to deletion
		const nodeSelection = this.selectedNode.getSelection();

		this.selection = {
			...this.selection,
			instanceId: nodeSelection.instanceId,
			memberPath: nodeSelection.memberPath,
		};

		return this.selection;
	}

	public getId() {
		return this.id;
	}

	public getPreview() {
		return this.preview;
	}

	public getSelectedNode() {
		return this.selectedNode;
	}

}

function findAndExpandParents(treeNodes: ITreeNode[], treeNodePath: string[]): ITreeNode {
	return findNode(
		treeNodes,
		treeNodePath,
		(node) => {
			if (!node.isExpanded()) {
				node.toggleExpanded();
			}
		},
	);
}

export function findNode(
	treeNodes: ITreeNode[],
	treeNodePath: string[],
	actionOnAncestors = (_node: ITreeNode) => { },
): ITreeNode {
	const part = treeNodePath[0];
	const node = _.find(treeNodes, (t) => t.getID() === part);
	if (node) {
		actionOnAncestors(node);
		const remaining = _.slice(treeNodePath, 1);
		return _.isEmpty(remaining) ? node : findNode(node.getChildren(), remaining, actionOnAncestors);
	}
	return null;
}

function getInitialSelectedModuleMgr(moduleMgrs: ModuleMgr[]) {
	return (
		_.find(moduleMgrs, (m) => !_.isEmpty(m.allInstancesIncludingStatic()))
		|| _.first(moduleMgrs)
	);
}

function getInitialSelectedInterfaceMgr(ifaceMgrs: InterfaceMgr[]) {
	// find the first interface with instances or else first one that is not disabled 
	return (
		_.find(ifaceMgrs, (i) => !_.isEmpty(i.instances))
		|| _.find(ifaceMgrs, (i) => !i.isDisabled())
	);
}

function getInitialIpInstanceMgr(nodes: ITreeNode[]): ITreeNode {
	const first = _.first(nodes);
	const children = first.getChildren();
	return _.isEmpty(children) ? first : getInitialIpInstanceMgr(children);
}
