import * as _ from "lodash";
import {
	Module as ModuleDef,
	FileTextConfigurable,
	TextConfigurable,
	NumberConfigurable,
	HardwareConfigurable,
	NameConfigurable,
} from "public/defs";
import { Module as RuntimeModule, ConfigByName } from "public/runtime";
import { freezeDeep } from "../utils";
import { flattenConfigs } from "../objectManagers/configGroups";
import { modFrozenKeys, modSealedKeys } from "../objectManagers/moduleRestrictedKeys";
import { isDirectoryConfigurable, isTextConfigurable, isNumberConfigurable } from "../objectManagers/configurables/configurable";
import { validateUIAdd, hasInstanceConfig } from "../validateAdd";
import { SimpleEvent } from "../simpleEvent";

const event = new SimpleEvent<(runtimeMod: RuntimeModule) => void>();
export function onAdaptToModule() {
	return event.asRegistration();
}

export function adaptToModule(metaMod: ModuleDef = {}, $name: string) {

	const uiAdd = getDefaultUIAddValue(metaMod);

	const runtimeMod: RuntimeModule = {
		...metaMod,
		displayName: metaMod.displayName || $name,
		$name,
		$instances: [],
		$static: null,
		$configByName: generateConfigByName(metaMod),
		moduleStatic: metaMod.moduleStatic ? adaptToModule(metaMod.moduleStatic, `${$name}$static`) : undefined,
		uiAdd,
	};

	event.fire(runtimeMod);

	// Define modules that will always use recreateOnArgsChange behaviour because they break otherwise.
	const exceptions = [
		"/ti/drivers/RTOS", // TIDRIVERS-4244
		"/ti/drivers/apps/Button", // TIDRIVERS-4246
		"/ti/drivers/apps/LED", // TIDRIVERS-4246
		"/ti/ble5stack/ble", // BLESTACK-5346
		"/ti/easylink/easylink", // EZLINKPROP-912
	];
	if (
		(runtimeMod.recreateOnArgsChange !== false) && // allow excepted modules to still opt-in if explicit
		_.includes(exceptions, $name)) {
		runtimeMod.recreateOnArgsChange = true;
	}

	// Legacy SDKs used system.getScript to access $static, and we'd like those SDKs to keep working.
	// So for CCS 9.2 we are adding a $static hook from the exports to read $static, but with a warning.

	Object.defineProperty(metaMod, "$static", {
		get: () => {
			console.warn(
				`Access to $static using system.getScript is deprecated.  Please use system.modules["${$name}"].$static`);
			const { stack } = new Error();
			const line = _.split(stack, "\n")[2];
			console.warn(line);
			return runtimeMod.$static;
		},
	});

	if (runtimeMod.uiView === "fileTree") {
		runtimeMod.uiAdd = "staticAndInstance";
		validateFileModule(runtimeMod);
	}

	_.each(modFrozenKeys, (prop) => {
		freezeDeep(runtimeMod[prop]);
	});

	_.each(modSealedKeys, (prop) => {
		Object.seal(runtimeMod[prop]);
	});

	// validate the UIAdd value
	validateUIAdd(runtimeMod);

	return runtimeMod;
}

function getDefaultUIAddValue(metaMod: ModuleDef) {

	if (!_.isUndefined(metaMod.uiAdd)) {
		return metaMod.uiAdd;
	}

	return hasInstanceConfig(metaMod) ? "instanceOnly" : "staticOnly";
}

function generateConfigByName(metaMod: ModuleDef): ConfigByName {

	// Can't rely on the duplicate check elsewhere, as we only refer to these configurables via
	// this map going forward

	const $configByName = _.chain(flattenConfigs(metaMod.config))
		.groupBy((c) => c.name)
		.mapValues((c, name) => {
			if (1 !== _.size(c)) {
				throw new Error(`Duplicate configurable definition: '${name}'`);
			}
			return _.first(c);
		})
		.value();

	// Define default $name/$hardware configurables in case they weren't defined.
	/* eslint-disable deprecation/deprecation */

	const defaultFilter = () => false;
	const $hardware: HardwareConfigurable = {
		name: "$hardware",
		filterHardware: metaMod.filterHardware || defaultFilter,
		onChange: metaMod.onHardwareChanged,
	};
	const $name: NameConfigurable = {
		name: "$name",
		defaultPrefix: metaMod.defaultInstanceName || "",
	};

	if ($configByName.$hardware) {
		const configHardware = $configByName.$hardware as HardwareConfigurable;
		if (!configHardware.onChange && metaMod.onHardwareChanged) {
			configHardware.onChange = metaMod.onHardwareChanged;
		}
		if (!configHardware.filterHardware && metaMod.filterHardware) {
			configHardware.filterHardware = metaMod.filterHardware;
		}
		if ((configHardware.onChange && metaMod.onHardwareChanged &&
			configHardware.onChange.toString() !== metaMod.onHardwareChanged.toString()) ||
			(configHardware.filterHardware && metaMod.filterHardware &&
				configHardware.filterHardware.toString() !== metaMod.filterHardware.toString())) {
			throw new Error("The legacy filterHardware and/or onHardwareChanged functions are defined" +
				" by the module while also defining a $hardware configurable." +
				" This functionality is now handled by the configurable only and the legacy functions will not be called");
		}
	}

	if ($configByName.$name && ($configByName.$name as NameConfigurable).defaultPrefix && metaMod.defaultInstanceName) {
		throw new Error("The legacy defaultInstanceName member is defined by the module while also defining a $name configurable." +
			" This functionality is now handled by the configurable only");
	}

	/* eslint-enable deprecation/deprecation */

	return {
		$hardware,
		$name,
		...$configByName, // will override default $name/$hardware if defined
	};
}

function validateFileModule(mod: RuntimeModule) {
	// must have a static module
	if (!mod.moduleStatic) {
		throw new Error(`Must define moduleStatic in ${mod.$name}`);
	}
	// must have config in static module
	if (!mod.moduleStatic.config) {
		throw new Error(`Must define moduleStatic.config in ${mod.$name}`);
	}
	// must have rootDirCfg
	const rootDirCfg = _.find(mod.moduleStatic.config, (c) => c.name === "rootDirCfg") as FileTextConfigurable;
	if (!rootDirCfg) {
		throw new Error(`Must define rootDirCfg in moduleStatic.config in ${mod.$name}`);
	}
	// rootDirCfg must be a file configurable, and pickDirectory should always be true
	if (!isDirectoryConfigurable(rootDirCfg)) {
		throw new Error(`rootDirCfg in ${mod.$name} must be a file configurable and with pickDirectory=true`);
	}
	// must have config 
	if (!mod.config) {
		throw new Error(`Must define moduleStatic.config in ${mod.$name}`);
	}
	// must have filePathCfg
	const filePathCfg = _.find(mod.config, (c) => c.name === "filePathCfg") as TextConfigurable;
	if (!filePathCfg) {
		throw new Error(`Must define filePathCfg in config in ${mod.$name}`);
	}
	// filePathCfg must be a text configurable	
	if (!isTextConfigurable(filePathCfg)) {
		throw new Error(`filePathCfg in ${mod.$name} must be a text configurable`);
	}
	// could have paddingSizeCfg
	const paddingSizeCfg = _.find(mod.config, (c) => c.name === "paddingSizeCfg") as NumberConfigurable;
	// paddingSizeCfg must be a numeric configurable	
	if (paddingSizeCfg && !isNumberConfigurable(paddingSizeCfg)) {
		throw new Error(`paddingSizeCfg in ${mod.$name} must be a number configurable`);
	}
}
