import * as _ from "lodash";
import { InterfacePinChoices } from "./interfacePin";
import { MinimizeResources, SharedChoices, ConflictingChoices } from "./minimizeResources";
import { DevicePinChoices } from "./devicePin";
import { IChoice } from "./common";
import { mutuallyExclude } from "../clauseGeneration";
import { PinMap } from "../../pinMap";

// A factory for creating implications in order to minimize choices that restrict GPIO choices.
// This allows the GPIO optimization to succeed even in the presence of shared pins.

export class MinimizeGPIOPins extends MinimizeResources {

	constructor(
		private readonly interfacePinChoices: InterfacePinChoices,
		private readonly devicePinChoices: DevicePinChoices,
		private readonly isGpioOptimizable: boolean,
		private readonly pinMap: PinMap,
	) {
		super("Minimize GPIO Pins");
	}

	public override generateClauses() {
		super.generateClauses();

		// Prevent any of the UsingSameResource in this.implications from being true when they 
		// jointly use a resource that doesn't restrict GPIO.  This is important because our base
		// class will add clauses to indicate if any resource (sharing or not) picked a choice that
		// didn't use GPIO, and we don't want to count UsingSameResource an extra time.

		_.each(this.implications, (implication) => {
			_.each(implication.combinations, (usingSameResource) => {
				_.each(usingSameResource.getDependentChoices(), (depChoice) => {
					_.each(this.devicePinChoices.freesOneGPIO.get(depChoice.id), (nonRestrictingChoice) => {
						mutuallyExclude(nonRestrictingChoice, usingSameResource,
							"Don't count a resource minimized if they both used a non-GPIO restricting resource - count that separately");
					});
				});
			});
		});
	}

	// Find all the shareable choices and group them by:
	// 1) those that can be shared together
	// 2) the requirements
	// 3) the choice of assignment for each requirement

	protected getSharedChoices() {
		if (!this.isGpioOptimizable) {
			return {}; // No point if we can't optimize GPIO
		}

		const sharedPins: SharedChoices = {};

		_.each(this.interfacePinChoices.sharedChoices, (choices, sharedHash) => {
			_.each(choices, (choice) => {
				if ("never" !== choice.pinReq.restrictsGPIO(this.pinMap)) {
					const requirementId = choice.parentChoice.getRequirementId() + choice.pinReq.getUnqualifiedName();
					_.set(sharedPins, [sharedHash, requirementId, choice.peripheralPin.name], choice);
				}
			});
		});

		return sharedPins;
	}

	protected getConflictingChoices() {
		if (!this.isGpioOptimizable) {
			return {}; // No point if we can't optimize GPIO
		}

		const conflictingPins: ConflictingChoices = {};

		_.each(this.interfacePinChoices.allowedConflicts, (choices) => {
			_.each(choices, (choice) => {
				if ("never" !== choice.pinReq.restrictsGPIO(this.pinMap)) {
					const requirementId = choice.parentChoice.getRequirementId() + choice.pinReq.getUnqualifiedName();
					const entry = _.get(conflictingPins, [choice.pinReq.userOverride, requirementId], []);
					entry.push(choice);
					_.set(conflictingPins, [choice.pinReq.userOverride, requirementId], entry);
				}
			});
		});

		return conflictingPins;
	}

	protected getDirectlyMinimizingChoices(): IChoice[] {
		if (!this.isGpioOptimizable) {
			return []; // No point if we can't optimize GPIO
		}

		const result: IChoice[] = [];
		this.devicePinChoices.freesOneGPIO.forEach((value) => result.push(...value));
		return result;
	}
}
