// Track known products
import * as _ from "lodash";
import { fsUtils } from "../fsutil";
import { fs } from "../fileSystem";
import { parseJSON, availableProductsRoute, keys } from "../utils";
import { AvailableProductInfo, AvailableProductsAndTargets, Product, ValidTargets } from "./types";
import * as path from "path";
import { isCloud, isUnderTest, getProcess } from "../platform";
import { loadMinProductFile, toProductFile, loadProductFile } from "./parseProductFile";
import { http } from "../http";
import { createLoader } from "../resources/otherLoaders/scriptAndProductLoader";
import { loadProducts } from "./loadResources";
import { getBoardOptions } from "./supportedDeviceAndBoard";
import { DiscoveryJSON } from "dataInterfaces";
import { getDeviceDescriptions } from "../data";
import { verifyMinToolVersion } from "./versionCheck";
import { getToolVersion } from "../toolVersion";

export interface IAvailableProducts {
	update(productPaths: AvailableProductInfo[]): void;
	getProductInfo(): AvailableProductInfo[];
	getProductAndTargetInfo(): Promise<AvailableProductsAndTargets[]>;
}

export class NullAvailableProducts implements IAvailableProducts {

	public update() { }

	public getProductInfo(): AvailableProductInfo[] {
		return [];
	}

	public getProductAndTargetInfo(): Promise<AvailableProductsAndTargets[]> {
		return Promise.resolve([]);
	}
}

export class LocalAvailableProducts implements IAvailableProducts {

	constructor(private infos: AvailableProductInfo[], private save: (fileContent: string) => void) {
	}

	public update(newInfos: AvailableProductInfo[]) {

		// Strip out any extra keys so we don't save EVERYTHING in the product

		newInfos = _.map(newInfos, (p) => _.pick(p, ...getAvailableProductInfoKeys()));

		// Combine with existing data, but prefer the updated data

		this.infos = _.uniqBy([...newInfos, ...this.infos], (i) => i.name + i.version);
		this.validateAndSave();
	}

	public getProductInfo() {
		this.validateAndSave();
		return this.infos;
	}

	public getProductAndTargetInfo() {
		return getProductAndTargetInfo(createLoader(fs), this.getProductInfo());
	}

	private validateAndSave() {
		const validInfos = _.filter(this.infos, (i) => fs.fileExists(i.path));
		this.infos = validInfos;
		this.save(JSON.stringify(validInfos, null, 2));
	}

}

export async function getProductAndTargetInfo(
	loader: ReturnType<typeof createLoader>, availableProducts: AvailableProductInfo[]) {
	const loaded = await Promise.all(_.map(availableProducts, async (info) => {
		try {
			const [product] = await loadProducts([info.path], loader);
			const boards = getBoardOptionsOfProduct(product, await getDeviceDescriptions());
			const devices = product.file.devices;
			return { ...info, boards, devices };
		} catch (e) {
			// We want to avoid crashes if any product fails validation
			return null;
		}
	})
	);

	// remove non loaded
	const valid = _.compact(loaded);

	return valid;
}

export function getIntersectingTargetInfo(products: Product[], discoveryData: DiscoveryJSON): ValidTargets {

	// Get the set or regexs to match against - a valid device must match all of them

	const deviceRegExps = _.map(products, (p) => new RegExp(_.join(p.file.devices, "|")));
	const deviceValid = (device: string) => _.every((deviceRegExps), (regex) => regex.test(device));

	// Now combine all the boards in all products, but only if the device underneath is valid

	const boards = _.chain(products)
		.flatMap((p) => getBoardOptionsOfProduct(p, discoveryData))
		.uniqBy((b) => b.name)
		.filter((b) => deviceValid(b.device))
		.value();

	return { deviceValid, boards };
}

function getBoardOptionsOfProduct(product: Product, discoveryData: DiscoveryJSON) {
	return (
		_.chain(getBoardOptions([product], discoveryData))
			.map(({ boardFile, boardDef }) => {
				const { displayName, device, part, package: pkg, emulated } = boardDef;
				return { name: boardFile, displayName, device, part, package: pkg, emulated };
			})
			.uniqBy((boardOptions) => boardOptions.name)
			.value()
	);
}

export function createLocalAvailableProducts(productsFilePath: string) {

	let fileContent = fs.fileExists(productsFilePath) ? fs.readFile(productsFilePath) : "[]";
	const infos = _.chain(safelyParseProductsFile(fileContent))
		.filter((product) => fs.fileExists(product.path))
		.map((product) => {
			const actualProduct = loadProductFile(product.path);
			return _.pick(actualProduct, getAvailableProductInfoKeys());
		})
		.value();
	return new LocalAvailableProducts(infos, (data) => {
		if (data !== fileContent) {
			fs.writeFile(productsFilePath, data);
			fileContent = data;
		}
	});
}

function safelyParseProductsFile(fileContent: string) {
	// https://jira.itg.ti.com/browse/PMUX-2299
	try {
		return parseJSON<AvailableProductInfo[]>(fileContent);
	} catch (e) {
		// ignore
		return [];
	}
}

class CloudAvailableProducts implements IAvailableProducts {

	constructor(private readonly infos: AvailableProductsAndTargets[]) { }

	public update() { }

	public getProductInfo() {
		return this.infos;
	}

	public async getProductAndTargetInfo() {
		return this.infos;
	}
}

class CLIAvailableProducts implements IAvailableProducts {

	constructor(private cliFilePath: string) { }
	public update(newInfos: AvailableProductInfo[]) {
		const localAvailableProducts = createLocalAvailableProducts(this.cliFilePath);
		localAvailableProducts.update(newInfos);
	}

	public getProductInfo(): AvailableProductInfo[] {
		return [];
	}

	public getProductAndTargetInfo(): Promise<AvailableProductsAndTargets[]> {
		return Promise.resolve([]);
	}

}

const cloudProducts = _.memoize(async () => {
	const response = await http.get(availableProductsRoute);
	return new CloudAvailableProducts(parseJSON<AvailableProductsAndTargets[]>(response));
});

const appDir = fsUtils.getAppDataDir();
const productsFilePath = isUnderTest() ?
	path.join(path.dirname(getProcess().execPath), "products.json") :
	path.join(appDir, "products.json");

export async function createAvailableProducts(): Promise<IAvailableProducts> {
	return isCloud() ? cloudProducts() : createLocalAvailableProducts(productsFilePath);
}

function getAvailableProductInfoKeys(): (keyof AvailableProductInfo)[] {

	// Required<> ensures that optional keys are not omitted

	const dummyAvailableProductInfo: Required<AvailableProductInfo> = {
		name: "",
		displayName: "",
		version: "",
		path: "",
		includesCCXXImageComponents: true,
		contexts: {},
		rtos: [],
		defaultDevice: "",
	};

	return keys(dummyAvailableProductInfo);
}

export function createAvailableProductsFromPaths(paths: string[], logger: { info: (message: string) => void }) {
	const available = _.chain(paths)
		.map((path2) => {

			try {

				// Parse and validate the product.json

				const unvalidated = loadMinProductFile(path2, fs.readFile(path2));
				verifyMinToolVersion([unvalidated], getToolVersion());
				const product = toProductFile(unvalidated);

				// While product holds the entire json, we're only going to extract/return some of it
				// That way, we won't transfer extra data from the server to the client

				return {
					..._.pick(product, getAvailableProductInfoKeys()),
					path: path2,
				} as AvailableProductInfo;
			} catch (e) {
				logger.info(`Ignoring invalid product at ${path2} due to error: ${e}`);
				return null;
			}
		})
		.compact()
		.value();
	return new LocalAvailableProducts(available, async () => { });
}

export function createCLIAvailableProductsfromPath(cliFilePath = productsFilePath) {
	return new CLIAvailableProducts(cliFilePath);
}
