import * as _ from "lodash";
import { IValidationLogger } from "public/defs";
import { ModuleInstanceMgr } from "../moduleInstance";
import { LegacyInstanceValidation } from "../validationLogger";

type ValidationProxyTarget = Pick<ModuleInstanceMgr, "memberMgrs" | "managedObject"> & { validationLogger: IValidationLogger };

export function validationLoggerWithLegacy(target: ValidationProxyTarget) {
	return new Proxy(target, validationProxyHandler) as any as IValidationLogger & LegacyInstanceValidation;
}

// This is a proxy handler to be used in a proxy for a validation object for a specific module instance.  Ideally, we'd
// just pass the validation object to validate, but there is a legacy interface that we still need to support

const validationProxyHandler: ProxyHandler<ValidationProxyTarget> = {
	get: (target, key: Extract<PropertyKey, string>) => {
		if (key in target.validationLogger) {
			return target.validationLogger[key as keyof IValidationLogger];
		}
		if (target.memberMgrs[key] && !target.memberMgrs[key].excludeFromInternalMaps()) {
			return {
				errors: {
					push: (msg: string) => target.validationLogger.logError(msg, target.managedObject, key),
				},
				warnings: {
					push: (msg: string) => target.validationLogger.logWarning(msg, target.managedObject, key),
				},
				infos: {
					push: (msg: string) => target.validationLogger.logInfo(msg, target.managedObject, key),
				},
			};
		}
		if (key === "$instance") {
			return {
				errors: {
					push: (msg: string) => target.validationLogger.logError(msg, target.managedObject),
				},
				warnings: {
					push: (msg: string) => target.validationLogger.logWarning(msg, target.managedObject),
				},
				infos: {
					push: (msg: string) => target.validationLogger.logInfo(msg, target.managedObject),
				},
			};
		}
		return undefined;
	},

	set: () => {
		return false; // disallow
	},

	// Hide the legacy interface

	ownKeys: (target) => {
		return _.keys(target.validationLogger);
	},

	// Hide the legacy interface

	has: (target, key: Extract<PropertyKey, string>) => {
		return target.validationLogger.hasOwnProperty(key);
	},

	defineProperty: () => {
		return false; // disallow
	},

	deleteProperty: () => {
		return false; // disallow
	},

	// Hide the legacy interface

	getOwnPropertyDescriptor: (target, key: Extract<PropertyKey, string>) => {
		if (target.validationLogger.hasOwnProperty(key)) {

			// Node won't let us return that it's not configurable, so instead we'll return 
			// getters/setters vs the raw value at least

			return {
				configurable: true,
				enumerable: true,
				get: () => validationProxyHandler.get(target, key, null),
			};
		}
		return undefined;
	},

	setPrototypeOf: () => {
		return false; // disallow
	},
};
